import type { Context } from "hono";

// Server-side cache. zo.space server keeps the Hono process warm, so this
// in-memory cache survives across requests and only re-fetches /api/models
// when stale. Keeps the live endpoint from being hammered.
let cache: { fetchedAt: number; payload: unknown } | null = null;
const CACHE_TTL_MS = 5 * 60 * 1000; // 5 minutes

type RawModel = {
  model_name?: string;
  label?: string;
  vendor?: string;
  type?: string;
  is_byok?: boolean;
  context_window?: number | null;
  priority?: number | null;
};

type ProviderGroup = {
  provider: string;
  models: Array<{
    friendlyName: string;
    byokId: string;
    contextWindow: number | null;
    priority: number | null;
  }>;
};

const PROVIDER_DISPLAY: Record<string, string> = {
  "Z.AI": "Z.AI",
  ZenMux: "ZenMux",
  Aether: "Aether",
  Aerolink: "Aerolink",
  BTL: "BTL",
  GC: "GC",
  Nous: "Nous",
  OCG: "OCG",
  TheClawBay: "TheClawBay",
  theclawbay: "theclawbay",
};

// Order: Z.AI first (your default), then alphabetical. Unknowns land at end.
const PROVIDER_ORDER = [
  "Z.AI",
  "ZenMux",
  "Aether",
  "Aerolink",
  "BTL",
  "GC",
  "Nous",
  "OCG",
  "TheClawBay",
  "theclawbay",
];

// Accepts "Z.AI_GLM-5-Turbo" -> ["Z.AI", "GLM-5-Turbo"]. Also accepts "Claude Code - Sonnet".
function classify(label: string): { provider: string; friendlyName: string } {
  const trimmed = label.trim();
  const dotPrefix = /^([A-Za-z][A-Za-z0-9]*\.[A-Za-z][A-Za-z0-9]*)_(.+)$/;
  const m1 = trimmed.match(dotPrefix);
  if (m1 && PROVIDER_ORDER.includes(m1[1])) {
    return { provider: m1[1], friendlyName: m1[2] };
  }
  const plainPrefix = /^([A-Za-z][A-Za-z0-9]+)_(.+)$/;
  const m2 = trimmed.match(plainPrefix);
  if (m2 && PROVIDER_ORDER.includes(m2[1])) {
    return { provider: m2[1], friendlyName: m2[2] };
  }
  const cc = trimmed.match(/^Claude Code\s*-\s*(.+)$/i);
  if (cc) return { provider: "Claude Code", friendlyName: cc[1] };
  return { provider: "Unknown", friendlyName: trimmed };
}

async function fetchFromLive(): Promise<{ models: RawModel[]; source: string }> {
  // Live endpoint: zo.space control plane. Reachable from inside the bun server.
  const resp = await fetch("http://localhost:3099/api/models", {
    headers: { Accept: "application/json" },
  });
  if (!resp.ok) {
    throw new Error(`upstream ${resp.status}`);
  }
  const data = (await resp.json()) as { models: RawModel[] };
  return { models: data.models || [], source: "http://localhost:3099/api/models" };
}

function buildGroups(models: RawModel[]): ProviderGroup[] {
  const byok = models.filter((m) => m.is_byok && m.model_name);
  const groups = new Map<string, ProviderGroup>();
  for (const p of [...PROVIDER_ORDER, "Claude Code", "Unknown"]) {
    groups.set(p, { provider: p, models: [] });
  }
  for (const m of byok) {
    const label = m.label || m.model_name || "";
    const { provider, friendlyName } = classify(label);
    const byokId = m.model_name || "";
    const grp = groups.get(provider) || groups.get("Unknown")!;
    grp.models.push({
      friendlyName,
      byokId,
      contextWindow: m.context_window ?? null,
      priority: m.priority ?? null,
    });
  }
  for (const grp of groups.values()) {
    grp.models.sort((a, b) => a.friendlyName.localeCompare(b.friendlyName));
  }
  return [...groups.values()];
}

export default async (c: Context) => {
  const now = Date.now();
  const stale = !cache || now - cache.fetchedAt > CACHE_TTL_MS;
  let source = "cache";
  let totalUpstream = 0;
  let totalByok = 0;

  if (stale) {
    try {
      const live = await fetchFromLive();
      const groups = buildGroups(live.models);
      totalUpstream = live.models.length;
      totalByok = groups.reduce((n, g) => n + g.models.length, 0);
      cache = {
        fetchedAt: now,
        payload: {
          fetchedAt: new Date(now).toISOString(),
          source: live.source,
          totalUpstream,
          totalByok,
          groups,
        },
      };
      source = "live";
    } catch (err) {
      // Live endpoint failed. Serve stale cache if we have one.
      if (cache) {
        source = `cache (live failed: ${String(err)})`;
      } else {
        return c.json({ error: "live endpoint unavailable and no cache", detail: String(err) }, 503);
      }
    }
  }

  const payload = cache!.payload as Record<string, unknown>;
  return c.json({
    ...payload,
    servedFrom: source,
    cacheAgeMs: now - cache!.fetchedAt,
  });
};
' public=True source='custom'

