/api/datasets/viewer.code:
import type { Context } from "hono";
import { execSync, spawn } from "node:child_process";
import { existsSync, mkdirSync, readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";

const SCAN_DIRS = ["/home/workspace/Data", "/home/workspace/Projects"];

function scanDbs(): { sqlite: string[]; duckdb: string[] } {
  const sqlite: string[] = [];
  const duckdb: string[] = [];

  for (const base of SCAN_DIRS) {
    if (!existsSync(base)) continue;
    try {
      const dirs = readdirSync(base, { withFileTypes: true })
        .filter(d => d.isDirectory())
        .map(d => join(base, d.name));

      for (const dir of dirs) {
        try {
          const pkgPath = join(dir, "datapackage.json");
          if (existsSync(pkgPath)) {
            const pkg = JSON.parse(readFileSync(pkgPath, "utf-8"));
            const path: string = pkg.resources?.[0]?.path || "";
            if (path.endsWith(".db") || path.endsWith(".sqlite")) {
              if (!sqlite.includes(path)) sqlite.push(path);
            } else if (path.endsWith(".duckdb")) {
              if (!duckdb.includes(path)) duckdb.push(path);
            }
          }
        } catch {}

        // Also scan for standalone files
        try {
          for (const f of readdirSync(dir)) {
            const fp = join(dir, f);
            if (f.endsWith(".duckdb") && !duckdb.includes(fp)) duckdb.push(fp);
            else if ((f.endsWith(".db") || f.endsWith(".sqlite")) && !sqlite.includes(fp)) sqlite.push(fp);
          }
        } catch {}
      }
    } catch {}
  }

  return { sqlite, duckdb };
}

export default async (c: Context) => {
  try {
    const { sqlite, duckdb } = scanDbs();

    // Kill existing servers
    execSync("pkill -f 'datasette.*8002' || true; pkill -f 'duckdb.*serve.*8003' || true; pkill -f 'python.*8003' || true", { timeout: 5000 });

    const results: any = {};

    // 1. Start Datasette for SQLite on port 8002
    if (sqlite.length > 0) {
      const linkDir = "/tmp/datasette-sqlite";
      mkdirSync(linkDir, { recursive: true });
      execSync(`rm -f ${linkDir}/*`);
      for (const db of sqlite) {
        if (existsSync(db)) {
          const name = db.replace(/\//g, "_").replace(/[^a-zA-Z0-9._-]/g, "_");
          execSync(`ln -sf "${db}" "${linkDir}/${name}"`);
        }
      }
      spawn("nohup", [
        "/root/.local/bin/datasette", linkDir,
        "--port", "8002", "--host", "0.0.0.0", "--cors",
        "--setting", "default_page_size=50",
      ], { detached: true, stdio: "ignore" }).unref();
      results.sqlite = { count: sqlite.length, port: 8002 };
    }

    // 2. Start DuckDB HTTP server for DuckDB files on port 8003
    if (duckdb.length > 0) {
      const firstDuckDb = duckdb[0];
      spawn("nohup", [
        "duckdb", firstDuckDb,
        "-c", `SETHTTP_ENDPOINT=0.0.0.0;PRAGMAPORT=8003;`
      ], { detached: true, stdio: "ignore" }).unref();
      results.duckdb = { count: duckdb.length, path: firstDuckDb, port: 8003 };
    }

    // No datasets found
    if (sqlite.length === 0 && duckdb.length === 0) {
      return c.json({ error: "No SQLite or DuckDB databases found in /home/workspace/Data or /home/workspace/Projects" }, 400);
    }

    return c.json({ success: true, ...results });
  } catch (error: any) {
    return c.json({ success: false, error: error.message }, 500);
  }
};
