/api/failures.code:
import type { Context } from "hono";
import { readFileSync, readdirSync, statSync } from "node:fs";
import { execSync } from "node:child_process";

const LOG_DIR = "/dev/shm";

interface Failure {
  time: string;
  severity: "critical" | "high" | "medium" | "low";
  category: string;
  source: string;
  message: string;
}

function tailFile(path: string, maxLines: number): string[] {
  try {
    const content = readFileSync(path, "utf8");
    const lines = content.split("\n").filter(l => l.trim());
    return lines.slice(-maxLines);
  } catch { return []; }
}

export default (c: Context) => {
  const failures: Failure[] = [];
  const categoryCounts: Record<string, number> = {};
  const severityCounts = { critical: 0, high: 0, medium: 0, low: 0 };

  // 1. Parse proxy logs for 5xx errors
  const proxyLines = tailFile(`${LOG_DIR}/zosite-3099-proxy.log`, 500);
  for (const line of proxyLines) {
    const m = line.match(/^(\d{4}-\d{2}-\d{2}T[\d:.]+Z)\s+(GET|POST|PUT|DELETE|PATCH|OPTIONS|HEAD)\s+(\S+)\s+(\d+)\s+(\d+)ms$/);
    if (!m) continue;
    const status = parseInt(m[4]);
    if (status >= 500) {
      const severity = status >= 503 ? "critical" : "high";
      failures.push({ time: m[1], severity, category: "Network", source: "proxy", message: `${m[2]} ${m[3]} returned ${status} (${m[5]}ms)` });
    }
  }

  // 2. Parse supervisord for crashes
  const supLines = tailFile(`${LOG_DIR}/supervisord.log`, 200);
  for (const line of supLines) {
    const m = line.match(/^(\d{4}-\d{2}-\d{2}\s+[\d:,]+)\s+(INFO|WARN|ERROR|CRIT)\s+(.+)$/);
    if (!m) continue;
    const msg = m[3].trim();
    const time = new Date(m[1].replace(",", ".")).toISOString();

    if (msg.includes("FATAL") || (msg.includes("exited:") && msg.includes("not expected"))) {
      failures.push({ time, severity: "critical", category: "Service", source: "supervisord", message: msg });
    } else if (msg.includes("stopped:") && msg.includes("SIGKILL")) {
      failures.push({ time, severity: "high", category: "Service", source: "supervisord", message: msg });
    }
  }

  // 3. Parse all error logs
  try {
    const files = readdirSync(LOG_DIR);
    for (const f of files) {
      if (!f.endsWith("_err.log")) continue;
      const filePath = `${LOG_DIR}/${f}`;
      const stat = statSync(filePath);
      if (stat.size === 0) continue;

      const source = f.replace("_err.log", "");
      const lines = tailFile(filePath, 50);

      for (const line of lines) {
        const lower = line.toLowerCase();
        if (!lower.includes("error") && !lower.includes("fatal") && !lower.includes("exception") && !lower.includes("⨯") && !lower.includes("panic") && !lower.includes("failed") && !lower.includes("crash")) continue;

        const timeMatch = line.match(/(\d{4}-\d{2}-\d{2}T[\d:.]+Z?)/);
        const time = timeMatch?.[1] || new Date().toISOString();

        let severity: "critical" | "high" | "medium" | "low" = "medium";
        let category = "Unknown";

        if (lower.includes("fatal") || lower.includes("panic") || lower.includes("crash")) {
          severity = "critical"; category = "Compute";
        } else if (lower.includes("econnrefused") || lower.includes("timeout") || lower.includes("502") || lower.includes("503")) {
          severity = "high"; category = "Network";
        } else if (lower.includes("auth") || lower.includes("unauthorized") || lower.includes("forbidden")) {
          severity = "high"; category = "Auth";
        } else if (lower.includes("disk") || lower.includes("storage") || lower.includes("no space")) {
          severity = "high"; category = "Storage";
        } else if (lower.includes("error") || lower.includes("⨯")) {
          severity = "medium"; category = "Service";
        } else {
          severity = "low"; category = "Unknown";
        }

        failures.push({ time, severity, category, source, message: line.slice(0, 400) });
      }
    }
  } catch {}

  // 4. Check zo-space build errors (via Loki recent errors)
  try {
    const lokiResult = execSync(
      `curl -s -G "http://localhost:3100/loki/api/v1/query_range" --data-urlencode 'query={filename=~"/dev/shm/.*"} |~ "(?i)(error|fatal|panic|crash|failed)"' --data-urlencode "start=$(date -d '6 hours ago' +%s)000000000" --data-urlencode "end=$(date +%s)000000000" --data-urlencode "limit=20"`,
      { encoding: "utf8", timeout: 5000 }
    );
    const parsed = JSON.parse(lokiResult);
    if (parsed?.data?.result) {
      for (const stream of parsed.data.result) {
        const filename = stream.stream?.filename || "";
        const source = filename.replace("/dev/shm/", "").replace(".log", "");
        for (const [ts, msg] of stream.values || []) {
          const time = new Date(parseInt(ts) / 1e6).toISOString();
          // Avoid duplicates from file parsing
          if (!failures.some(f => f.message.slice(0, 50) === msg.slice(0, 50))) {
            failures.push({ time, severity: "medium", category: "Service", source, message: msg.slice(0, 400) });
          }
        }
      }
    }
  } catch {}

  // Sort by time descending
  failures.sort((a, b) => b.time.localeCompare(a.time));

  // Count categories and severities
  for (const f of failures) {
    categoryCounts[f.category] = (categoryCounts[f.category] || 0) + 1;
    severityCounts[f.severity]++;
  }

  // Source breakdown
  const sourceBreakdown: Record<string, number> = {};
  for (const f of failures) {
    sourceBreakdown[f.source] = (sourceBreakdown[f.source] || 0) + 1;
  }

  const totalIncidents = failures.length;
  const alertState = severityCounts.critical > 0 ? "Critical" : severityCounts.high > 0 ? "Elevated" : totalIncidents > 0 ? "Guarded" : "Clear";

  return c.json({
    failures: failures.slice(0, 100),
    stats: {
      totalIncidents,
      critical: severityCounts.critical,
      high: severityCounts.high,
      medium: severityCounts.medium,
      low: severityCounts.low,
      categoryCounts,
      sourceBreakdown,
      alertState,
    },
    data_source: "LIVE",
    last_updated: new Date().toISOString(),
  });
};' public=True source='custom'

