import type { Context } from "hono";
import { existsSync, readFileSync } from "fs";

const DATA_DIR = "/home/workspace/Data/flowpulse";

function readJsonl(file: string): any[] {
  const p = `${DATA_DIR}/${file}`;
  if (!existsSync(p)) return [];
  const raw = readFileSync(p, "utf-8").trim();
  if (!raw) return [];
  return raw.split("\n").filter(Boolean).map((l: string) => JSON.parse(l));
}

function readJson(file: string): any {
  const p = `${DATA_DIR}/${file}`;
  if (!existsSync(p)) return null;
  return JSON.parse(readFileSync(p, "utf-8"));
}

function sinceFilter(entries: any[], hours: number): any[] {
  const cutoff = Date.now() - hours * 60 * 60 * 1000;
  return entries.filter((e: any) => new Date(e.triggered_at || e.created_at).getTime() >= cutoff);
}

function computeAgentStatus(agent: any, runs: any[]): any {
  const agentRuns = runs.filter((r: any) => r.agent_id === agent.agent_id);
  const sorted = [...agentRuns].sort((a: any, b: any) => new Date(b.triggered_at).getTime() - new Date(a.triggered_at).getTime());
  const lastRun = sorted[0] || null;
  const recent7d = sinceFilter(agentRuns, 168);
  const failures7d = recent7d.filter((r: any) => r.status === "failure" || r.status === "timeout");
  const failRate = recent7d.length > 0 ? failures7d.length / recent7d.length : 0;

  let consecutiveFailures = 0;
  for (const run of sorted) {
    if (run.status === "failure" || run.status === "timeout") consecutiveFailures++;
    else break;
  }

  const silenceHours = lastRun ? (Date.now() - new Date(lastRun.triggered_at).getTime()) / (1000 * 60 * 60) : null;

  let status = "unknown";
  if (!lastRun) status = "no_data";
  else if (consecutiveFailures >= 3) status = "failing";
  else if (silenceHours !== null && silenceHours > agent.silence_threshold_hours) status = "silent";
  else if (failRate > 0.2) status = "unstable";
  else status = "healthy";

  return {
    agent_id: agent.agent_id,
    agent_name: agent.agent_name,
    description: agent.description,
    status,
    last_run: lastRun?.triggered_at ?? null,
    last_status: lastRun?.status ?? null,
    last_duration_ms: lastRun?.duration_ms ?? null,
    last_error: lastRun?.error_message ?? null,
    silence_threshold_hours: agent.silence_threshold_hours,
    silence_hours: silenceHours ? Math.round(silenceHours * 10) / 10 : null,
    critical: agent.critical,
    enabled: agent.enabled,
    failure_rate_7d: Math.round(failRate * 1000) / 10,
    total_runs_7d: recent7d.length,
    consecutive_failures: consecutiveFailures,
  };
}

export default async (c: Context) => {
  // Page is private (auth handled by Zo), API data is no more sensitive than the page
  // Keep auth for automation (Bearer token) but don't require it for browser requests
  const authHeader = c.req.header("authorization") || "";
  const isAutomation = authHeader.startsWith("Bearer ") && process.env.ZO_API_KEY && authHeader.slice(7) === process.env.ZO_API_KEY;

  const view = c.req.query("view") || "overview";
  const accept = c.req.header("accept") || "";
  if (accept && !accept.includes("application/json") && !accept.includes("*/*")) {
    return c.json({ error: "Accept header must be application/json" }, 400);
  }

  if (view === "agents") {
    const registry = readJson("agent_registry.json");
    if (!registry) return c.json({ agents: [] });
    const runs = readJsonl("agent_runs.jsonl");
    const agents = registry.agents.filter((a: any) => a.enabled !== false).map((a: any) => computeAgentStatus(a, runs));
    return c.json({ agents, last_synced: registry.last_synced });
  }

  if (view === "runs") {
    const agentId = c.req.query("agent_id");
    const hours = parseInt(c.req.query("hours") || "168");
    const limit = parseInt(c.req.query("limit") || "100");
    let runs = readJsonl("agent_runs.jsonl");
    if (agentId) runs = runs.filter((r: any) => r.agent_id === agentId);
    runs = sinceFilter(runs, hours);
    runs.sort((a: any, b: any) => new Date(b.triggered_at).getTime() - new Date(a.triggered_at).getTime());
    return c.json({ runs: runs.slice(0, limit) });
  }

  if (view === "alerts") {
    const limit = parseInt(c.req.query("limit") || "50");
    const alerts = readJsonl("alerts.jsonl");
    alerts.sort((a: any, b: any) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime());
    return c.json({ alerts: alerts.slice(0, limit) });
  }

  if (view === "checker-state") {
    const state = readJson("checker_state.json");
    return c.json(state || { last_check: null, last_sms_sent: {} });
  }

  const registry = readJson("agent_registry.json");
  const agents = registry?.agents || [];
  const runs = readJsonl("agent_runs.jsonl");
  const alerts = readJsonl("alerts.jsonl");
  const recentAlerts = alerts.filter((a: any) => Date.now() - new Date(a.created_at).getTime() < 86400000);
  const criticalAlerts = recentAlerts.filter((a: any) => a.severity === "critical");
  const enabledAgents = agents.filter((a: any) => a.enabled !== false);
  const computed = enabledAgents.map((a: any) => computeAgentStatus(a, runs));

  return c.json({
    agents_tracked: agents.length,
    agents_enabled: enabledAgents.length,
    healthy_agents: computed.filter((a: any) => a.status === "healthy").length,
    at_risk_agents: computed.filter((a: any) => ["unstable", "failing", "silent"].includes(a.status)).length,
    no_data_agents: computed.filter((a: any) => a.status === "no_data").length,
    total_runs: runs.length,
    runs_7d: sinceFilter(runs, 168).length,
    alerts_24h: recentAlerts.length,
    critical_alerts_24h: criticalAlerts.length,
    last_check: readJson("checker_state.json")?.last_check ?? null,
  });
};' public=True source='custom'

