import type { Context } from "hono";

async function validateSession(c: Context): Promise<boolean> {
  const authHeader = c.req.header("Authorization");
  if (authHeader?.startsWith("Bearer ")) {
    const token = authHeader.slice(7);
    if (process.env.ZO_API_KEY && token === process.env.ZO_API_KEY) return true;
  }
  const cookieHeader = c.req.header("Cookie") || "";
  const hasSession =
    cookieHeader.includes("zo_session") ||
    cookieHeader.includes("auth_token") ||
    cookieHeader.includes("x-zo-session") ||
    cookieHeader.includes("__session");
  const zoUser = c.req.header("X-Zo-User");
  if (zoUser === "curtastrophe") return true;
  const host = c.req.header("Host") || "";
  if (host.includes("localhost") || host.includes("127.0.0.1")) return true;
  return false;
}

export default async (c: Context) => {
  if (!await validateSession(c)) return c.json({ error: "Unauthorized" }, 401);
  if (c.req.method !== "POST") return c.json({ error: "Method not allowed" }, 405);

  const body = await c.req.json().catch(() => ({}));
  const providerId = body.provider_id ? Number(body.provider_id) : null;
  const providerArg = body.provider_prefix ? ["--provider", String(body.provider_prefix)] : [];
  const scriptPath = "/home/workspace/Projects/model-explorer/scripts/sync-models.ts";

  try {
    const proc = Bun.spawn(["bun", "run", scriptPath, ...providerArg], {
      stdout: "pipe",
      stderr: "pipe",
      env: { ...process.env },
    });
    const output = await new Response(proc.stdout).text();
    const stderr = await new Response(proc.stderr).text();
    const exitCode = await proc.exited;

    if (exitCode !== 0) {
      return c.json({ error: "Sync failed", stderr: stderr.slice(-500), output: output.slice(-500) }, 500);
    }

    return c.json({ success: true, output: output.slice(-1500) });
  } catch (err: any) {
    return c.json({ error: "Sync execution error", detail: err.message }, 500);
  }
};
' public=True source='custom'

/api/health-check.code:
import type { Context } from "hono";
import { readFileSync, existsSync, readdirSync } from "node:fs";
import { execSync } from "node:child_process";

export default async (c: Context) => {
  const staticResults: any[] = [];
  let agentResults: any[] = [];
  const cachePath = "/home/workspace/.zo/status-check-cache.json";

  let monitorStatus = "Outage";
  let monitorDetails = "Cache file not found";

  try {
    if (existsSync(cachePath)) {
      const cached = JSON.parse(readFileSync(cachePath, "utf-8"));
      agentResults = cached.services || [];

      const lastUpdated = new Date(cached.lastUpdated).getTime();
      const now = Date.now();
      const diffMinutes = (now - lastUpdated) / (1000 * 60);

      if (diffMinutes > 30) {
        monitorStatus = "Outage";
        monitorDetails = `Last updated ${Math.round(diffMinutes)} mins ago`;
      } else if (diffMinutes > 16) {
        monitorStatus = "Degraded";
        monitorDetails = `Delayed (last update ${Math.round(diffMinutes)} mins ago)`;
      } else {
        monitorStatus = "Operational";
        monitorDetails = "Running correctly";
      }
    }
  } catch (e) {
    monitorDetails = "Error reading cache";
  }

  const allResults = [...staticResults, ...agentResults, {
    name: "Background Status Monitor",
    category: "Local Services",
    status: monitorStatus,
    details: monitorDetails
  }];

  // ---- CLAUDE CODE CLI QUOTA CHECK ----
  let claudeUsage: any = {
    five_hour: { utilization: 0, resets_at: null },
    seven_day: { utilization: 0, resets_at: null },
    extra_usage: { is_enabled: false },
    unavailable: true
  };

  try {
    // Check if Claude CLI exists (try each separately - "which claude clc" fails if clc missing)
    let claudeCliExists = false;
    try {
      execSync("which claude 2>/dev/null", { encoding: "utf-8", timeout: 3000 });
      claudeCliExists = true;
    } catch (e) {
      try {
        execSync("which clc 2>/dev/null", { encoding: "utf-8", timeout: 3000 });
        claudeCliExists = true;
      } catch (e2) {}
    }

    if (claudeCliExists) {
      claudeUsage.unavailable = false;

      // Read local stats from Claude Code stats-cache
      const statsPath = "/root/.claude/stats-cache.json";
      if (existsSync(statsPath)) {
        const stats = JSON.parse(readFileSync(statsPath, "utf-8"));

        // Get today's and recent usage
        const today = new Date().toISOString().split("T")[0];
        const dailyActivity = stats.dailyActivity || [];
        const dailyTokens = stats.dailyModelTokens || [];
        const modelUsage = stats.modelUsage || {};

        // Calculate recent activity (last 7 days)
        const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString().split("T")[0];
        const recentActivity = dailyActivity.filter((d: any) => d.date >= sevenDaysAgo);
        const recentMessages = recentActivity.reduce((sum: number, d: any) => sum + (d.messageCount || 0), 0);
        const recentSessions = recentActivity.reduce((sum: number, d: any) => sum + (d.sessionCount || 0), 0);
        const recentToolCalls = recentActivity.reduce((sum: number, d: any) => sum + (d.toolCallCount || 0), 0);

        // Token totals by model
        const opusTokens = (modelUsage["claude-opus-4-6"]?.outputTokens || 0) + (modelUsage["claude-opus-4-6"]?.inputTokens || 0);
        const sonnetTokens = (modelUsage["claude-sonnet-4-5-20250929"]?.outputTokens || 0) + (modelUsage["claude-sonnet-4-5-20250929"]?.inputTokens || 0);
        const haikuTokens = (modelUsage["claude-haiku-4-5-20251001"]?.outputTokens || 0) + (modelUsage["claude-haiku-4-5-20251001"]?.inputTokens || 0);

        // Cache read tokens (these are the big numbers for Pro users)
        const opusCacheTokens = (modelUsage["claude-opus-4-6"]?.cacheReadInputTokens || 0) + (modelUsage["claude-opus-4-6"]?.cacheCreationInputTokens || 0);
        const sonnetCacheTokens = (modelUsage["claude-sonnet-4-5-20250929"]?.cacheReadInputTokens || 0) + (modelUsage["claude-sonnet-4-5-20250929"]?.cacheCreationInputTokens || 0);

        claudeUsage = {
          unavailable: false,
          plan: "Pro (OAuth)",
          totalSessions: stats.totalSessions || 0,
          totalMessages: stats.totalMessages || 0,
          recentMessages,
          recentSessions,
          recentToolCalls,
          statsDate: stats.lastComputedDate || "unknown",
          models: {
            opus: { directTokens: opusTokens, cacheTokens: opusCacheTokens },
            sonnet: { directTokens: sonnetTokens, cacheTokens: sonnetCacheTokens },
            haiku: { directTokens: haikuTokens, cacheTokens: 0 },
          },
          note: "Claude Code Pro uses rolling 5-hour windows. Exact % not available via local stats."
        };
      }
    }
  } catch (e) {
    // Claude CLI not available or error
  }

  // ---- GEMINI CLI QUOTA CHECK ----
  let geminiUsage: any = { status: "unknown", used: 0, limit: 1500, percentage: 0, resetTime: null };

  try {
    // Read telemetry file for actual usage data
    const telemetryPath = "/home/workspace/.zo/gemini-telemetry.jsonl";

    if (existsSync(telemetryPath)) {
      const lines = readFileSync(telemetryPath, "utf-8").split("\n").filter(l => l.trim());
      const totalRequests = lines.length;

      // Check for quota errors in recent telemetry
      const recentErrors = lines.slice(-20).map((line: string) => {
        try { return JSON.parse(line); } catch (e) { return null; }
      }).filter((e: any) => e?.error?.message?.includes("exhausted"));

      // Get daily quota limit (typically 1500 requests/day for free tier)
      const dailyLimit = 1500;
      const usedToday = totalRequests;
      const percentage = Math.min(100, Math.round((usedToday / dailyLimit) * 100));

      // Parse reset time from recent quota error if any
      let resetTime: string | null = null;
      if (recentErrors.length > 0) {
        const errorMsg = recentErrors[0].error?.message;
        const match = errorMsg?.match(/reset after (\d+h)?(\d+m)?(\d+s)?/);
        if (match) {
          const h = parseInt(match[1] || "0");
          const m = parseInt(match[2] || "0");
          const s = parseInt(match[3] || "0");
          const totalMs = (h * 3600 + m * 60 + s) * 1000;
          const resetDate = new Date(Date.now() + totalMs);
          resetTime = resetDate.toISOString();
        }
      }

      geminiUsage = {
        status: recentErrors.length > 0 ? "exhausted" : percentage > 90 ? "warning" : "ok",
        used: usedToday,
        limit: dailyLimit,
        percentage: percentage,
        resetTime: resetTime,
        recentRequests: Math.min(20, lines.length),
      };
    } else {
      // Fall back to error log scanning
      const geminiTmpPath = "/root/.gemini/tmp";
      if (existsSync(geminiTmpPath)) {
        const files = readdirSync(geminiTmpPath);
        const errorFiles = files.filter((f: string) => 
          f.includes("gemini-client-error") && f.endsWith(".json")
        ).sort().slice(-5);

        let quotaExhausted = false;
        let resetTime: string | null = null;

        for (const file of errorFiles) {
          try {
            const content = readFileSync(`${geminiTmpPath}/${file}`, "utf-8");
            const error = JSON.parse(content);

            const msg = error.error?.message || error.message;
            if (msg && msg.includes("exhausted your capacity")) {
              quotaExhausted = true;

              const match = msg.match(/reset after (\d+h)?(\d+m)?(\d+s)?/);
              if (match) {
                const h = parseInt(match[1] || "0");
                const m = parseInt(match[2] || "0");
                const s = parseInt(match[3] || "0");
                const totalMs = (h * 3600 + m * 60 + s) * 1000;
                const resetDate = new Date(Date.now() + totalMs);
                resetTime = resetDate.toISOString();
              }
              break;
            }
          } catch (e) {}
        }

        geminiUsage = {
          status: quotaExhausted ? "exhausted" : "ok",
          used: quotaExhausted ? 1500 : 0,
          limit: 1500,
          percentage: quotaExhausted ? 100 : 0,
          resetTime: resetTime,
          recentRequests: errorFiles.length,
        };
      } else {
        geminiUsage.status = "no_data";
        geminiUsage.details = "Enable telemetry for accurate tracking";
      }
    }
  } catch (e) {
    geminiUsage.status = "error";
    geminiUsage.details = String(e);
  }

  return c.json({
    services: allResults,
    claudeUsage,
    geminiUsage,
  });
};' public=True source='custom'

/api/generate-icon.code:
import type { Context } from "hono";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { randomUUID } from "node:crypto";

const MODEL_NAME = "vercel:moonshotai/kimi-k2.5";
const MAX_RETRIES = 2;
const DAILY_LIMIT = 3;
const RATE_LIMIT_FILE = "/tmp/zo-icon-ratelimit.json";

function getMSTDateString(): string {
  return new Date().toLocaleDateString("en-CA", { timeZone: "America/Edmonton" });
}

function loadRateLimits(): Record<string, { count: number; resetDate: string }> {
  try {
    if (existsSync(RATE_LIMIT_FILE)) {
      return JSON.parse(readFileSync(RATE_LIMIT_FILE, "utf8"));
    }
  } catch {}
  return {};
}

function saveRateLimits(limits: Record<string, { count: number; resetDate: string }>) {
  writeFileSync(RATE_LIMIT_FILE, JSON.stringify(limits));
}

function sanitizeInput(input: string): string {
  if (!input) return "";
  // Strip control characters, newlines, limit to 100 characters to prevent injection
  return input.replace(/[\r\n\t\x00-\x1F]/g, " ").slice(0, 100).trim();
}

function isAuthenticated(c: Context): boolean {
  // Primary check: X-Zo-User header (injected by Zo for authenticated requests)
  const zoUser = c.req.header("X-Zo-User");
  if (zoUser) {
    console.log(`Auth: X-Zo-User=${zoUser}`);
    return true;
  }

  // Secondary: Check for Zo session cookies
  const cookie = c.req.header("Cookie") || "";
  const hasZoSession = cookie.includes("zo_session") || cookie.includes("auth_token");
  if (hasZoSession) {
    console.log(`Auth: Found session cookie`);
    return true;
  }

  // Tertiary: Check referer - if request comes from authenticated space page
  const referer = c.req.header("Referer") || "";
  const isFromAuthenticatedPage = referer.includes("curtastrophe.zo.space") && !referer.includes("/icon-configurator?preview=1");
  if (isFromAuthenticatedPage) {
    console.log(`Auth: Request from authenticated page`);
    return true;
  }

  console.log(`Not authed: zoUser=${zoUser || 'none'}, cookies=${cookie.slice(0, 100)}, referer=${referer.slice(0, 100)}`);
  return false;
}

function getClientIP(c: Context): string {
  return c.req.header("X-Forwarded-For")?.split(",")[0]?.trim()
    || c.req.header("X-Real-IP")
    || "unknown";
}

function checkRateLimit(ip: string): { allowed: boolean; remaining: number } {
  const today = getMSTDateString();
  const limits = loadRateLimits();
  const entry = limits[ip];

  if (!entry || entry.resetDate !== today) {
    return { allowed: true, remaining: DAILY_LIMIT };
  }

  if (entry.count >= DAILY_LIMIT) {
    return { allowed: false, remaining: 0 };
  }

  return { allowed: true, remaining: DAILY_LIMIT - entry.count };
}

function incrementRateLimit(ip: string) {
  const today = getMSTDateString();
  const limits = loadRateLimits();

  // Clean up old entries while we're here
  for (const key of Object.keys(limits)) {
    if (limits[key].resetDate !== today) delete limits[key];
  }

  const entry = limits[ip];
  if (!entry || entry.resetDate !== today) {
    limits[ip] = { count: 1, resetDate: today };
  } else {
    entry.count++;
  }

  saveRateLimits(limits);
}

async function attemptGeneration(jobId: string, logoType: string, colors: string, theme: string): Promise<{ success: boolean; error?: string; agentOutput?: string; promptUsed?: string }> {
