import type { Context } from "hono";
import { Database } from "bun:sqlite";

const DB_PATH = "/home/workspace/Projects/model-explorer/models.db";

async function validateSession(c: Context): Promise<boolean> {
  const authHeader = c.req.header("Authorization");
  if (authHeader?.startsWith("Bearer ")) {
    const token = authHeader.slice(7);
    if (process.env.ZO_API_KEY && token === process.env.ZO_API_KEY) return true;
  }
  const cookieHeader = c.req.header("Cookie") || "";
  const hasSession =
    cookieHeader.includes("zo_session") ||
    cookieHeader.includes("auth_token") ||
    cookieHeader.includes("x-zo-session") ||
    cookieHeader.includes("__session");
  const zoUser = c.req.header("X-Zo-User");
  if (zoUser === "curtastrophe") return true;
  const host = c.req.header("Host") || "";
  if (host.includes("localhost") || host.includes("127.0.0.1")) return true;
  return false;
}

export default async (c: Context) => {
  if (!await validateSession(c)) return c.json({ error: "Unauthorized" }, 401);

  const db = new Database(DB_PATH, { readonly: true });

  const totalModels = db.prepare("SELECT COUNT(*) as count FROM models").get() as { count: number };

  const byProvider = db.prepare(`
    SELECT p.name, p.prefix, p.model_count, p.sync_status
    FROM providers p ORDER BY p.model_count DESC
  `).all() as { name: string; prefix: string; model_count: number; sync_status: string }[];

  const byOwnedBy = db.prepare(`
    SELECT owned_by, COUNT(*) as count
    FROM models WHERE owned_by IS NOT NULL AND owned_by != ''
    GROUP BY owned_by ORDER BY count DESC LIMIT 20
  `).all() as { owned_by: string; count: number }[];

  const modalityStats = db.prepare(`
    SELECT
      SUM(CASE WHEN LOWER(input_modalities) LIKE '%image%' THEN 1 ELSE 0 END) as vision,
      SUM(CASE WHEN LOWER(input_modalities) LIKE '%audio%' THEN 1 ELSE 0 END) as audio,
      SUM(CASE WHEN LOWER(output_modalities) LIKE '%text%' THEN 1 ELSE 0 END) as text_output,
      SUM(CASE WHEN reasoning IS NOT NULL AND reasoning != '' AND reasoning != 'null' THEN 1 ELSE 0 END) as reasoning
    FROM models
  `).get() as { vision: number; audio: number; text_output: number; reasoning: number };

  const contextStats = db.prepare(`
    SELECT MAX(context_window) as max_ctx, MIN(context_window) as min_ctx, AVG(context_window) as avg_ctx
    FROM models WHERE context_window IS NOT NULL AND context_window > 0
  `).get() as { max_ctx: number; min_ctx: number; avg_ctx: number };

  db.close();

  return c.json({
    total_models: totalModels.count,
    providers: byProvider,
    llm_providers: byOwnedBy,
    capabilities: modalityStats,
    context: {
      max: contextStats.max_ctx,
      min: contextStats.min_ctx,
      avg: Math.round(contextStats.avg_ctx || 0),
    },
  });
};
