import type { Context } from "hono";
import { Database } from "bun:sqlite";

const MODEL_DB = "/home/workspace/Projects/model-explorer/models.db";
const OMNI_DB = "/home/workspace/Projects/omniroute/data/storage.sqlite";
const OMNI_URL = "http://127.0.0.1:24128/api/provider-nodes";
const SYNC_SCRIPT = "/home/workspace/Projects/model-explorer/scripts/sync-models.ts";

type OmniNode = {
  id: string;
  type: string;
  name: string;
  prefix?: string | null;
  apiType?: string | null;
  baseUrl?: string | null;
  modelsPath?: string | null;
  secretName?: string | null;
  createdAt?: string | null;
  updatedAt?: string | null;
};

type Provider = {
  id: number;
  name: string;
  prefix: string;
  base_url: string;
  secret_name: string;
  sync_status: string;
  model_count: number;
};

function validateSession(c: Context): boolean {
  const auth = c.req.header("Authorization");
  if (auth?.startsWith("Bearer ") && process.env.ZO_API_KEY && auth.slice(7) === process.env.ZO_API_KEY) return true;
  const cookies = c.req.header("Cookie") || "";
  if (["zo_session", "auth_token", "x-zo-session", "__session", "zocomputer_session"].some((name) => cookies.includes(name))) return true;
  if (c.req.header("X-Zo-User") === "curtastrophe") return true;
  const host = c.req.header("Host") || "";
  return host.includes("localhost") || host.includes("127.0.0.1");
}

function token(value: string): string {
  return value.toUpperCase().replace(/[^A-Z0-9]+/g, "_").replace(/^_+|_+$/g, "");
}

function hostToken(baseUrl: string): string {
  try {
    const host = new URL(baseUrl).hostname.replace(/^api\./, "").replace(/^www\./, "");
    return token(host.split(".")[0] || "");
  } catch {
    return "";
  }
}

function secretCandidates(node: OmniNode, existing?: Provider): string[] {
  const names = Object.keys(process.env).filter((name) => /(?:API|KEY|TOKEN|SECRET)/i.test(name));
  const explicit = String(node.secretName || "").trim();
  if (explicit && names.includes(explicit)) return [explicit];
  if (existing?.secret_name && names.includes(existing.secret_name)) return [existing.secret_name];

  const aliases = Array.from(new Set([token(node.name), token(node.prefix || ""), hostToken(node.baseUrl || "")].filter(Boolean)));
  const exact: string[] = [];
  for (const alias of aliases) {
    for (const candidate of [`${alias}_API_KEY`, `${alias}_API`, `${alias}_KEY`, alias]) {
      if (names.includes(candidate)) exact.push(candidate);
    }
  }
  if (exact.length) return Array.from(new Set(exact));

  const prefixMatches = names.filter((name) => aliases.some((alias) => name === alias || name.startsWith(`${alias}_`)));
  return Array.from(new Set(prefixMatches)).sort();
}

async function readOmniNodes(): Promise<{ nodes: OmniNode[]; source: "admin_api" | "sqlite" }> {
  const adminKey = process.env.OMNIROUTE_ADMIN_API;
  if (adminKey) {
    try {
      const response = await fetch(OMNI_URL, { headers: { Authorization: `Bearer ${adminKey}`, Accept: "application/json" } });
      if (response.ok) {
        const payload = await response.json() as { nodes?: OmniNode[] };
        if (Array.isArray(payload.nodes)) return { nodes: payload.nodes, source: "admin_api" };
      }
    } catch {}
  }

  const db = new Database(OMNI_DB, { readonly: true });
  const rows = db.prepare(`
    SELECT id, type, name, prefix, api_type AS apiType, base_url AS baseUrl,
           models_path AS modelsPath, created_at AS createdAt, updated_at AS updatedAt
    FROM provider_nodes ORDER BY name COLLATE NOCASE
  `).all() as OmniNode[];
  db.close();
  return { nodes: rows, source: "sqlite" };
}

function normalizeNodes(nodes: OmniNode[]): OmniNode[] {
  const seen = new Set<string>();
  return nodes.filter((node) => {
    const prefix = String(node.prefix || "").trim().toLowerCase();
    if (node.type !== "openai-compatible" || !prefix || !node.baseUrl || seen.has(prefix)) return false;
    seen.add(prefix);
    return true;
  });
}

function previewRows(nodes: OmniNode[], existing: Provider[]) {
  const byPrefix = new Map(existing.map((provider) => [provider.prefix, provider]));
  return nodes.map((node) => {
    const prefix = String(node.prefix).toLowerCase();
    const current = byPrefix.get(prefix);
    const candidates = secretCandidates(node, current);
    return {
      omni_id: node.id,
      name: node.name,
      prefix,
      base_url: String(node.baseUrl).replace(/\/$/, ""),
      models_path: node.modelsPath || null,
      api_type: node.apiType || "chat",
      existing_provider_id: current?.id || null,
      action: current ? "update" : "create",
      current_secret_name: current?.secret_name || "",
      secret_candidates: candidates,
      suggested_secret_name: candidates.length === 1 ? candidates[0] : "",
      secret_status: candidates.length === 1 ? "matched" : candidates.length > 1 ? "needs_selection" : "missing",
      importable: true,
    };
  });
}

export default async (c: Context) => {
  if (!validateSession(c)) return c.json({ error: "Unauthorized" }, 401);
  if (!process.env.OMNIROUTE_ADMIN_API && !Bun.file(OMNI_DB).size) return c.json({ error: "OmniRoute source is unavailable" }, 503);

  const modelDb = new Database(MODEL_DB);
  const existing = modelDb.prepare("SELECT * FROM providers ORDER BY name COLLATE NOCASE").all() as Provider[];
  const { nodes: rawNodes, source } = await readOmniNodes();
  const nodes = normalizeNodes(rawNodes);
  const rows = previewRows(nodes, existing);

  if (c.req.method === "GET") {
    modelDb.close();
    return c.json({ source, dry_run: true, providers: rows, unsupported_count: rawNodes.length - nodes.length });
  }
  if (c.req.method !== "POST") {
    modelDb.close();
    return c.json({ error: "Method not allowed" }, 405);
  }

  const body = await c.req.json().catch(() => ({})) as {
    mode?: "providers_only" | "providers_and_models";
    selections?: Record<string, string>;
    prefixes?: string[];
  };
  const mode = body.mode === "providers_and_models" ? "providers_and_models" : "providers_only";
  const requested = new Set(Array.isArray(body.prefixes) ? body.prefixes.map(String) : rows.map((row) => row.prefix));
  const selectedRows = rows.filter((row) => requested.has(row.prefix));
  const results: Array<Record<string, unknown>> = [];

  const upsert = modelDb.prepare(`
    INSERT INTO providers (name, prefix, base_url, secret_name, sync_status)
    VALUES (?, ?, ?, ?, 'never')
    ON CONFLICT(prefix) DO UPDATE SET
      name = excluded.name,
      base_url = excluded.base_url,
      secret_name = CASE WHEN excluded.secret_name <> '' THEN excluded.secret_name ELSE providers.secret_name END
  `);

  for (const row of selectedRows) {
    const selectedSecret = String(body.selections?.[row.prefix] || row.suggested_secret_name || row.current_secret_name || "").trim();
    if (selectedSecret && !/^[A-Z][A-Z0-9_]*$/.test(selectedSecret)) {
      results.push({ prefix: row.prefix, status: "error", error: "Invalid Zo Secret API name" });
      continue;
    }
    upsert.run(row.name, row.prefix, row.base_url, selectedSecret);
    const provider = modelDb.prepare("SELECT * FROM providers WHERE prefix = ?").get(row.prefix) as Provider;
    results.push({ prefix: row.prefix, status: row.action === "create" ? "created" : "updated", provider, secret_configured: Boolean(selectedSecret && process.env[selectedSecret]) });
  }
  modelDb.close();

  if (mode === "providers_and_models") {
    for (const result of results) {
      if (result.status === "error") continue;
      const prefix = String(result.prefix);
      const provider = result.provider as Provider;
      if (!provider.secret_name || !process.env[provider.secret_name]) {
        result.sync = { status: "skipped", error: "Zo Secret is not configured" };
        continue;
      }
      const proc = Bun.spawn(["bun", "run", SYNC_SCRIPT, "--provider", prefix], { cwd: "/home/workspace/Projects/model-explorer", stdout: "pipe", stderr: "pipe" });
      const [stdout, stderr, code] = await Promise.all([new Response(proc.stdout).text(), new Response(proc.stderr).text(), proc.exited]);
      result.sync = { status: code === 0 ? "success" : "error", code, output: (code === 0 ? stdout : stderr || stdout).slice(-1200) };
    }
  }

  return c.json({ source, dry_run: false, mode, results });
};
