import type { Context } from "hono";
import { Database } from "bun:sqlite";
import { isIP } from "node:net";

const DB_PATH = "/home/workspace/Projects/model-explorer/models.db";
const SYNC_SCRIPT = "/home/workspace/Projects/model-explorer/scripts/sync-models.ts";

function validateSession(c: Context): boolean {
  const authHeader = c.req.header("Authorization");
  if (authHeader?.startsWith("Bearer ") && process.env.ZO_API_KEY && authHeader.slice(7) === process.env.ZO_API_KEY) return true;
  const cookies = c.req.header("Cookie") || "";
  if (["zo_session", "auth_token", "x-zo-session", "__session", "zocomputer_session"].some((name) => cookies.includes(name))) return true;
  if (c.req.header("X-Zo-User") === "curtastrophe") return true;
  const host = c.req.header("Host") || "";
  if (host.includes("localhost") || host.includes("127.0.0.1")) return true;
  return false;
}

function publicBaseUrl(value: string): string | null {
  try {
    const url = new URL(value.trim().replace(/\/$/, ""));
    if (url.protocol !== "https:") return null;
    const host = url.hostname.toLowerCase();
    if (host === "localhost" || host.endsWith(".local") || isIP(host)) return null;
    return url.toString().replace(/\/$/, "");
  } catch {
    return null;
  }
}

function providerById(db: Database, id: number) {
