import type { Context } from "hono";
import { Database } from "bun:sqlite";

const DB_PATH = "/home/workspace/Projects/model-explorer/models.db";

async function validateSession(c: Context): Promise<boolean> {
  const authHeader = c.req.header("Authorization");
  if (authHeader?.startsWith("Bearer ")) {
    const token = authHeader.slice(7);
    if (process.env.ZO_API_KEY && token === process.env.ZO_API_KEY) return true;
  }
  const cookieHeader = c.req.header("Cookie") || "";
  const hasSession =
    cookieHeader.includes("zo_session") ||
    cookieHeader.includes("auth_token") ||
    cookieHeader.includes("x-zo-session") ||
    cookieHeader.includes("__session");
  const zoUser = c.req.header("X-Zo-User");
  if (zoUser === "curtastrophe") return true;
  const host = c.req.header("Host") || "";
  if (host.includes("localhost") || host.includes("127.0.0.1")) return true;
  return false;
}

export default async (c: Context) => {
  if (!await validateSession(c)) return c.json({ error: "Unauthorized" }, 401);

  const params = c.req.query();
  const conditions: string[] = [];
  const bindings: (string | number)[] = [];
  const splitValues = (value?: string) => value?.split(",").map((item) => item.trim()).filter(Boolean) || [];

  const providerIds = splitValues(params.provider_id).map(Number).filter(Number.isFinite);
  if (providerIds.length) {
    conditions.push(`m.provider_id IN (${providerIds.map(() => "?").join(", ")})`);
    bindings.push(...providerIds);
  }
  const baseUrls = splitValues(params.base_url);
  if (baseUrls.length) {
    conditions.push(`p.base_url IN (${baseUrls.map(() => "?").join(", ")})`);
    bindings.push(...baseUrls);
  }
  const secretNames = splitValues(params.secret_name);
  if (secretNames.length) {
    conditions.push(`p.secret_name IN (${secretNames.map(() => "?").join(", ")})`);
    bindings.push(...secretNames);
  }
  const owners = splitValues(params.owned_by);
  if (owners.length) {
    conditions.push(`LOWER(m.owned_by) IN (${owners.map(() => "LOWER(?)").join(", ")})`);
    bindings.push(...owners);
  }
  if (params.search) {
    conditions.push("(LOWER(m.model_id) LIKE LOWER(?) OR LOWER(COALESCE(m.friendly_name, '')) LIKE LOWER(?))");
    const term = `%${params.search}%`;
    bindings.push(term, term);
  }
  const inputModalities = splitValues(params.input_modality);
  if (inputModalities.length) {
    conditions.push(`(${inputModalities.map(() => "LOWER(m.input_modalities) LIKE LOWER(?)").join(" OR ")})`);
    bindings.push(...inputModalities.map((modality) => `%${modality}%`));
  }
  const outputModalities = splitValues(params.output_modality);
  if (outputModalities.length) {
    conditions.push(`(${outputModalities.map(() => "LOWER(m.output_modalities) LIKE LOWER(?)").join(" OR ")})`);
    bindings.push(...outputModalities.map((modality) => `%${modality}%`));
  }
  if (params.reasoning === "true") {
    conditions.push("m.reasoning IS NOT NULL AND m.reasoning != '' AND m.reasoning != 'null'");
  }
  if (params.min_context) {
    conditions.push("m.context_window >= ?");
    bindings.push(Number(params.min_context));
  }
  if (params.max_context) {
    conditions.push("m.context_window <= ?");
    bindings.push(Number(params.max_context));
  }

  const where = conditions.length > 0 ? "WHERE " + conditions.join(" AND ") : "";
  const limit = Math.min(Number(params.limit) || 500, 1000);
  const offset = Number(params.offset) || 0;
  const sortBy = ["model_id", "friendly_name", "context_window", "max_completion_tokens", "owned_by", "provider_id", "provider_name", "released_at"]
    .includes(params.sort_by || "") ? params.sort_by! : "provider_id";
  const sortDir = params.sort_dir === "desc" ? "DESC" : "ASC";

  const db = new Database(DB_PATH, { readonly: true });
  const models = db.prepare(`
    SELECT m.*, p.name as provider_name, p.prefix as provider_prefix, p.base_url as provider_base_url, p.secret_name as provider_secret_name
    FROM models m
    JOIN providers p ON m.provider_id = p.id
    ${where}
    ORDER BY ${sortBy} ${sortDir}
    LIMIT ? OFFSET ?
  `).all(...bindings, limit, offset);

  const total = db.prepare(`SELECT COUNT(*) as count FROM models m JOIN providers p ON m.provider_id = p.id ${where}`).get(...bindings) as { count: number };
  db.close();

  return c.json({ models, total: total.count, limit, offset });
};
