import type { Context } from "hono";
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const DATA_FILE = "/home/workspace/Data/zo-project-ops/projects.json";

export interface Project {
  name: string;
  desc: string;
  status: "backlog" | "in-progress" | "completed" | "archived";
  tags: string[];
  link: string | null;
  priority?: "high" | "medium" | "low" | "none";
  order?: number;
}

function readProjects(): Project[] {
  try {
    const raw = readFileSync(DATA_FILE, "utf-8");
    return JSON.parse(raw) as Project[];
  } catch {
    return [];
  }
}

function writeProjects(projects: Project[]): void {
  writeFileSync(DATA_FILE, JSON.stringify(projects, null, 2), "utf-8");
}

export default async (c: Context) => {
  const method = c.req.method;

  if (method === "GET") {
    return c.json(readProjects());
  }

  if (method === "PUT") {
    let body: any;
    try {
      body = await c.req.json();
    } catch {
      return c.json({ error: "Invalid JSON body" }, 400);
    }
    const { name, desc, status, tags, link, priority } = body as { name?: string; desc?: string; status?: string; tags?: string[]; link?: string | null; priority?: string };
    if (!name) return c.json({ error: "Missing 'name' in body" }, 400);
    const validStatuses = ["backlog", "in-progress", "completed", "archived"];
    if (status && !validStatuses.includes(status)) {
      return c.json({ error: `Invalid status. Must be one of: ${validStatuses.join(", ")}` }, 400);
    }
    const projects = readProjects();
    const idx = projects.findIndex((p) => p.name === name);
    if (idx === -1) return c.json({ error: `Project '${name}' not found` }, 404);
    if (desc !== undefined) projects[idx].desc = desc;
    if (status !== undefined) projects[idx].status = status as Project["status"];
    if (tags !== undefined) projects[idx].tags = tags;
    if (link !== undefined) projects[idx].link = link;
    if (priority !== undefined) projects[idx].priority = priority as Project["priority"];
    writeProjects(projects);
    return c.json({ ok: true, project: projects[idx] });
  }

  if (method === "PATCH") {
    const body = c.req.query();
    const { name, status, newOrder, newStatus, newPriority } = body as { name?: string; status?: string; newOrder?: string; newStatus?: string; newPriority?: string };

    // Reorder: move a project to a new position within its column (and optionally change status)
    if (newOrder !== undefined) {
      if (!name) return c.json({ error: "name is required for reorder" }, 400);
      const projects = readProjects();
      const idx = projects.findIndex((p: Project) => p.name === name);
      if (idx === -1) return c.json({ error: "Project not found" }, 404);
      projects[idx].order = parseInt(newOrder);
      if (newStatus) projects[idx].status = newStatus as Project["status"];
      if (newPriority) projects[idx].priority = newPriority as Project["priority"];
      writeProjects(projects);
      return c.json({ ok: true, project: projects[idx] });
    }

    if (!name || !status) {
      return c.json({ error: "Missing 'name' or 'status' query params" }, 400);
    }

    const validStatuses = ["backlog", "in-progress", "completed", "archived"];
    if (!validStatuses.includes(status)) {
      return c.json({ error: `Invalid status. Must be one of: ${validStatuses.join(", ")}` }, 400);
    }

    const projects = readProjects();
    const idx = projects.findIndex((p) => p.name === name);
    if (idx === -1) {
      return c.json({ error: `Project '${name}' not found` }, 404);
    }

    projects[idx].status = status as Project["status"];
    writeProjects(projects);

    return c.json({ ok: true, project: projects[idx] });
  }

  return c.json({ error: "Method not allowed" }, 405);
};
' public=True source='custom'

