import type { Context } from "hono";
import { Database } from "bun:sqlite";

const DB_PATH = "/home/workspace/Projects/model-explorer/models.db";

async function validateSession(c: Context): Promise<boolean> {
  const authHeader = c.req.header("Authorization");
  if (authHeader?.startsWith("Bearer ")) {
    const token = authHeader.slice(7);
    if (process.env.ZO_API_KEY && token === process.env.ZO_API_KEY) return true;
  }
  const cookieHeader = c.req.header("Cookie") || "";
  const hasSession =
    cookieHeader.includes("zo_session") ||
    cookieHeader.includes("auth_token") ||
    cookieHeader.includes("x-zo-session") ||
    cookieHeader.includes("__session");
  const zoUser = c.req.header("X-Zo-User");
  if (zoUser === "curtastrophe") return true;
  const host = c.req.header("Host") || "";
  if (host.includes("localhost") || host.includes("127.0.0.1")) return true;
  return false;
}

export default async (c: Context) => {
  if (!await validateSession(c)) return c.json({ error: "Unauthorized" }, 401);
  if (c.req.method !== "POST") return c.json({ error: "Method not allowed" }, 405);

  const body = await c.req.json().catch(() => null);
  if (!body) return c.json({ error: "Invalid JSON body" }, 400);

  let baseUrl: string;
  let apiKey: string;
  const model: string = body.model;
  const messages: any[] = body.messages || [];
  const temperature: number | undefined = body.temperature;
  const maxTokens: number | undefined = body.max_tokens;
  const stream: boolean = body.stream || false;

  if (!model) return c.json({ error: "model is required" }, 400);
  if (messages.length === 0) return c.json({ error: "messages array is required" }, 400);

  // Mode 1: Use a stored provider (by provider_id) — look up secret from env
  if (body.provider_id) {
    const db = new Database(DB_PATH, { readonly: true });
    const provider = db.prepare("SELECT base_url, secret_name FROM providers WHERE id = ?").get(body.provider_id) as
      | { base_url: string; secret_name: string } | null;
    db.close();

    if (!provider) return c.json({ error: "Provider not found" }, 404);
    baseUrl = provider.base_url;
    const secretVal = process.env[provider.secret_name];
    if (!secretVal) return c.json({ error: `Secret ${provider.secret_name} not configured in Zo` }, 400);
    apiKey = secretVal;
  } else {
    // Mode 2: Custom entry — user provides base_url and api_key directly
    if (!body.base_url) return c.json({ error: "base_url or provider_id is required" }, 400);
    if (!body.api_key) return c.json({ error: "api_key or provider_id is required" }, 400);
    baseUrl = body.base_url.replace(/\/$/, "");
    apiKey = body.api_key;
  }

  const chatUrl = baseUrl.endsWith("/chat/completions")
    ? baseUrl
    : `${baseUrl}/chat/completions`;

  const payload: Record<string, any> = { model, messages };
  if (temperature !== undefined) payload.temperature = temperature;
  if (maxTokens !== undefined) payload.max_tokens = maxTokens;
  if (stream) payload.stream = true;

  const startTime = Date.now();
  try {
    const resp = await fetch(chatUrl, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Authorization": `Bearer ${apiKey}`,
      },
      body: JSON.stringify(payload),
    });

    const elapsed = Date.now() - startTime;

    if (!resp.ok) {
      const errText = await resp.text();
      return c.json({
        error: `HTTP ${resp.status}`,
        detail: errText.slice(0, 1000),
        elapsed_ms: elapsed,
        endpoint: chatUrl,
      }, resp.status);
    }

    if (stream) {
      return new Response(resp.body, {
        headers: { "Content-Type": "text/event-stream", "X-Elapsed-Ms": String(elapsed) },
      });
    }

    const data = await resp.json();
    return c.json({
      response: data,
      elapsed_ms: elapsed,
      endpoint: chatUrl,
      model,
    });
  } catch (err: any) {
    const elapsed = Date.now() - startTime;
    return c.json({
      error: "Fetch failed",
      detail: err.message,
      elapsed_ms: elapsed,
      endpoint: chatUrl,
    }, 500);
  }
};
