import { promises as fs } from 'node:fs';
import path from 'node:path';
import { exec } from 'node:child_process';
import { promisify } from 'node:util';
import { timingSafeEqual } from 'node:crypto';
import type { Context } from 'hono';

const execAsync = promisify(exec);
const IMAGES_DIR = '/home/workspace/Data/ReceiptTracker/Images';

// Teable configuration
const TEABLE_BASE_URL = 'https://app.teable.io/api';
const TEABLE_TABLE_ID = 'tbllrSKj0Wh8b3rLPe4';
const TEABLE_API_KEY = process.env.TEABLE_API_KEY || '';

async function teableRequest(method: string, endpoint: string, body?: any) {
  const url = `${TEABLE_BASE_URL}${endpoint}`;
  const headers: Record<string, string> = {
    'Authorization': `Bearer ${TEABLE_API_KEY}`,
  };
  if (body) {
    headers['Content-Type'] = 'application/json';
  }

  const response = await fetch(url, {
    method,
    headers,
    body: body ? JSON.stringify(body) : undefined,
  });

  if (!response.ok) {
    const text = await response.text();
    throw new Error(`Teable API error: ${response.status} ${text}`);
  }

  return response.json();
}

async function getAllReceipts() {
  const result = await teableRequest('GET', `/table/${TEABLE_TABLE_ID}/record?take=200`);
  return result.records || [];
}

async function createReceipt(fields: any) {
  const result = await teableRequest('POST', `/table/${TEABLE_TABLE_ID}/record`, {
    records: [{ fields }]
  });
  return result.records?.[0];
}

async function updateReceipt(recordId: string, fields: any) {
  return teableRequest('PATCH', `/table/${TEABLE_TABLE_ID}/record/${recordId}`, {
    record: { fields }
  });
}

function checkAuth(c: Context) {
  const secret = process.env.RECEIPT_TRACKER_PASSCODE || process.env.COSTCO_APP_PASSCODE;
  if (!secret) return { result: false, reason: 'no_secret' };
  const authHeader = c.req.header('x-passcode') || c.req.header('X-Passcode');
  if (!authHeader) return { result: false, reason: 'no_header' };
  const token = authHeader.trim();
  const cleanSecret = secret.trim();
  try {
    const aBytes = Buffer.from(token);
    const bBytes = Buffer.from(cleanSecret);
    if (aBytes.length !== bBytes.length) return { result: false, reason: 'length_mismatch' };
    return { result: timingSafeEqual(aBytes, bBytes), reason: 'checked' };
  } catch(e) {
    return { result: false, reason: 'error' };
  }
}

async function extractItemsFromText(rawText: string): Promise<{ items: any[], total: number, date: string, store_name: string }> {
  const prompt = `You are a receipt parser. Extract all purchased items from this retail receipt OCR text (Costco, Winners, Marshalls, etc.).\n\nIMPORTANT: \n- Identify the store name from the top of the receipt (e.g. "Costco", "Winners", "Marshalls", "Walmart").\n- Only extract actual purchased ITEMS (products), ignore: SUBTOTAL, TAX, TOTAL, payment info, store info, "APPROVED", card numbers, dates without items\n- Item codes might be alphanumeric depending on the store (e.g., 7 digits for Costco, others vary). If there is no item code, use an empty string or the most likely identifier.\n- Return ONLY valid JSON, no markdown\n\nReturn JSON in this exact format:\n{\n  "store_name": "Costco",\n  "items": [\n    {"item_code": "1851427", "description": "MTG MARVEL", "price": 49.99},\n    {"item_code": "1748763", "description": "BAC&EGG SAND", "price": 24.99}\n  ],\n  "total": 186.98,\n  "date": "2026-03-16"\n}\n\nReceipt text:\n${rawText}`;

  try {
    const zoRes = await fetch('https://api.zo.computer/zo/ask', {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${process.env.ZO_API_KEY}`,
        'Content-Type': 'application/json',
        'Accept': 'application/json',
      },
      body: JSON.stringify({ input: prompt, model_name: 'kimi-k2.5' }),
    });

    if (!zoRes.ok) {
      console.error('Zo API error:', await zoRes.text());
      return { items: [], total: 0, date: '', store_name: 'Unknown' };
    }

    const zoData = await zoRes.json();
    let output = zoData.output;
    if (typeof output === 'string') {
      const jsonMatch = output.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        output = JSON.parse(jsonMatch[0]);
      } else {
        console.error('No JSON found in response:', output);
        return { items: [], total: 0, date: '', store_name: 'Unknown' };
      }
    }
    return {
      items: Array.isArray(output?.items) ? output.items : [],
      total: typeof output?.total === 'number' ? output.total : 0,
      date: typeof output?.date === 'string' ? output.date : '',
      store_name: typeof output?.store_name === 'string' ? output.store_name : 'Unknown'
    };
  } catch (e) {
    console.error('Extraction error:', e);
    return { items: [], total: 0, date: '', store_name: 'Unknown' };
  }
}

async function processReceipt(receipt: any): Promise<any> {
  if (!receipt.fields?.raw_text) return receipt;
  const extracted = await extractItemsFromText(receipt.fields.raw_text);
  return {
    ...receipt,
    fields: {
      ...receipt.fields,
      items_json: JSON.stringify(extracted.items),
      total: extracted.total,
      receipt_date: extracted.date,
      store_name: extracted.store_name,
      status: 'processed'
    }
  };
}

function formatReceipt(record: any) {
  const f = record.fields || {};
  return {
    id: f.id || record.id,
    date_uploaded: f.date_uploaded || '',
    image_url: f.image_path ? `/api/receipt-images?id=${f.image_path}` : '',
    items: f.items_json ? JSON.parse(f.items_json) : [],
    total: f.total || 0,
    receipt_date: f.receipt_date || '',
    store_name: f.store_name || 'Unknown',
    raw_text: f.raw_text || '',
    status: f.status || 'pending'
  };
}

export default async (c: Context) => {
  const auth = checkAuth(c);
  if (!auth.result) return c.json({ error: 'Unauthorized' }, 401);

  if (c.req.method === 'GET') {
    try {
      const records = await getAllReceipts();
      // Filter out empty records and format
      const receipts = records
        .filter((r: any) => r.fields?.id)
        .map(formatReceipt)
        .sort((a: any, b: any) => new Date(b.date_uploaded).getTime() - new Date(a.date_uploaded).getTime());
      return c.json(receipts);
    } catch (e) {
      console.error('Failed to fetch receipts:', e);
      return c.json({ error: 'Failed to fetch receipts' }, 500);
    }
  }

  const url = new URL(c.req.url);
  const action = url.searchParams.get('action');

  if (action === 'reprocess') {
    try {
      const records = await getAllReceipts();
      let processed = 0;
      for (const record of records) {
        const items = record.fields?.items_json ? JSON.parse(record.fields.items_json) : [];
        if (items.length === 0 && record.fields?.raw_text && record.fields?.status !== 'processed') {
          const processedRecord = await processReceipt(record);
          await updateReceipt(record.id, processedRecord.fields);
          processed++;
        }
      }
      return c.json({ success: true, message: `Reprocessed ${processed} receipts`, processed });
    } catch (e) {
      console.error('Reprocess error:', e);
      return c.json({ error: 'Failed to reprocess', message: String(e) }, 500);
    }
  }

  if (action === 'upload') {
    try {
      const formData = await c.req.formData();
      const files = formData.getAll('images');
      if (!files || files.length === 0) return c.json({ error: 'No image files provided' }, 400);

      await fs.mkdir(IMAGES_DIR, { recursive: true }).catch(() => {});

      const uploaded = [];
      for (let i = 0; i < files.length; i++) {
        const file = files[i];
        if (!(file instanceof File)) continue;
        const id = Date.now().toString() + '-' + i;
        const ext = path.extname(file.name) || '.jpg';
        const filename = `${id}${ext}`;
        const filepath = path.join(IMAGES_DIR, filename);
        const buffer = await file.arrayBuffer();
        await fs.writeFile(filepath, Buffer.from(buffer));
        const { stdout: text } = await execAsync(`tesseract "${filepath}" stdout 2>/dev/null`);

        // Create record in Teable
        const fields = {
          id,
          date_uploaded: new Date().toISOString(),
          image_path: filename,
          items_json: '[]',
          total: 0,
          receipt_date: '',
          store_name: '',
          raw_text: text,
          status: 'pending'
        };
        await createReceipt(fields);
        uploaded.push({ file: file.name, id });
      }
      return c.json({ success: true, message: `Uploaded ${uploaded.length} images. Processing...`, uploaded, needsProcessing: true });
    } catch (error) {
      console.error('Upload error:', error);
      return c.json({ success: false, error: String(error) }, 500);
    }
  }

  if (action === 'process') {
    try {
      const records = await getAllReceipts();
      let processed = 0;
      for (const record of records) {
        if (record.fields?.status === 'pending' && record.fields?.raw_text) {
          const processedRecord = await processReceipt(record);
          await updateReceipt(record.id, processedRecord.fields);
          processed++;
        }
      }
      return c.json({ success: true, message: `Processed ${processed} receipts`, processed });
    } catch (e) {
      console.error('Process error:', e);
      return c.json({ error: 'Failed to process', message: String(e) }, 500);
    }
  }

  return c.json({ error: 'Unknown action' }, 400);
};' public=True source='custom'

