import type { Context } from "hono";
import { readFileSync, existsSync } from "fs";

const SKILL_LOG = "/home/workspace/Data/skill-execution-logs/skill_executions.jsonl";
const WSS_LOG = "/dev/shm/wss.log";
const AGENT_META = "/home/workspace/Data/breadcrumb-telemetry/agent-metadata.json";
const TRACES_LOG = "/home/workspace/Data/breadcrumb-telemetry/traces.jsonl";

function readJsonl(path: string): any[] {
  if (!existsSync(path)) return [];
  const raw = readFileSync(path, "utf-8").trim();
  if (!raw) return [];
  return raw.split("\n").map(line => { try { return JSON.parse(line); } catch { return null; } }).filter(Boolean);
}

export default async (c: Context) => {
  const daysParam = parseInt(c.req.query("days") || "30");
  const cutoff = new Date(Date.now() - daysParam * 86400000).toISOString();

  const skillLogs = readJsonl(SKILL_LOG).filter((e: any) => e.timestamp >= cutoff);
  const traces = readJsonl(TRACES_LOG).filter((e: any) => e.timestamp >= cutoff);

  const skillStats: Record<string, {runs:number;success:number;fail:number;totalMs:number;errors:string[]}> = {};
  for (const entry of skillLogs) {
    const name = entry.skill_name || "unknown";
    if (!skillStats[name]) skillStats[name] = {runs:0,success:0,fail:0,totalMs:0,errors:[]};
    skillStats[name].runs++;
    if (entry.success) skillStats[name].success++; else {
      skillStats[name].fail++;
      if (entry.error_message) skillStats[name].errors.push(entry.error_message);
    }
    skillStats[name].totalMs += (entry.duration_ms || 0);
  }
  const skillList = Object.entries(skillStats).map(([name, s]) => ({
    name, runs: s.runs, success: s.success, fail: s.fail,
    successRate: s.runs > 0 ? Math.round((s.success / s.runs) * 100) : 0,
    avgDurationMs: s.runs > 0 ? Math.round(s.totalMs / s.runs) : 0,
    recentErrors: s.errors.slice(-3),
  })).sort((a, b) => b.runs - a.runs);

  const completions = traces.filter((t: any) => t.type === "completion");
  const modelUsage: Record<string, number> = {};
  let totalTokens = 0;
  let totalCost = 0;

  for (const t of completions) {
    const model = t.model || "unknown";
    modelUsage[model] = (modelUsage[model] || 0) + 1;
    totalTokens += (t.totalTokens || 0);
    totalCost += (t.estimatedCost || 0);
  }

  let agents: any[] = [];
  if (existsSync(AGENT_META)) {
    try { agents = JSON.parse(readFileSync(AGENT_META, "utf-8")).agents || []; } catch {}
  }

  let sessionActivity: {date:string;sessions:number}[] = [];
  let totalSessions = 0;
  if (existsSync(WSS_LOG)) {
    try {
      const wssContent = readFileSync(WSS_LOG, "utf-8");
      const sessionIds = new Set<string>();
      const dateSessions: Record<string, Set<string>> = {};
      const sessionMatches = wssContent.match(/"sessionId":\s*"([a-f0-9-]+)"/g) || [];
      for (const m of sessionMatches) {
        const sid = m.match(/"sessionId":\s*"([a-f0-9-]+)"/)?.[1];
        if (sid && !sessionIds.has(sid)) {
          sessionIds.add(sid);
          const idx = wssContent.indexOf(m);
          const before = wssContent.substring(Math.max(0, idx - 100), idx);
          const dateMatch = before.match(/(\d{4}-\d{2}-\d{2})/);
          const date = dateMatch ? dateMatch[1] : new Date().toISOString().split("T")[0];
          if (!dateSessions[date]) dateSessions[date] = new Set();
          dateSessions[date].add(sid);
        }
      }
      totalSessions = sessionIds.size;
      sessionActivity = Object.entries(dateSessions)
        .sort(([a], [b]) => b.localeCompare(a))
        .slice(0, 30)
        .map(([date, sids]) => ({ date, sessions: sids.size }));
    } catch {}
  }

  const totalSkillRuns = skillLogs.length;
  const totalSuccess = skillLogs.filter((e: any) => e.success).length;
  const overallSuccessRate = totalSkillRuns > 0 ? Math.round((totalSuccess / totalSkillRuns) * 100) : 0;

  return c.json({
    skills: skillList,
    agents,
    sessionActivity,
    totalSessions,
    modelUsage,
    summary: { 
      totalSkillRuns, 
      overallSuccessRate, 
      totalSessions, 
      topSkill: skillList[0]?.name || "none", 
      activeModels: Object.keys(modelUsage).length,
      totalTokens,
      totalCost: parseFloat(totalCost.toFixed(4))
    }
  });
};' public=True source='custom'

/api/speech-game-data.code:
import type { Context } from "hono";
import { timingSafeEqual } from "node:crypto";

// Teable configuration
const TEABLE_BASE_URL = "https://app.teable.io/api";
const TEABLE_API_KEY = process.env.TEABLE_API_KEY;
const ATTEMPTS_TABLE = "tblpGWk0Womh812kwMA";
const STICKERS_TABLE = "tbl2y2Enec28jLbEceL";

interface Attempt {
  id: string;
  word: string;
  phrase: string;
  position: "first" | "second";
  round: number;
  tries: number;
  date: string;
  time: string;
  timestamp: number;
}

interface Store {
  attempts: Attempt[];
  stickers: Record<string, string>;
}

// Helper: make Teable API request
async function teableRequest(method: string, endpoint: string, body?: unknown) {
  const url = `${TEABLE_BASE_URL}${endpoint}`;
  const response = await fetch(url, {
    method,
    headers: {
      "Authorization": `Bearer ${TEABLE_API_KEY}`,
      "Content-Type": "application/json",
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  if (!response.ok) {
    const text = await response.text();
    throw new Error(`Teable API Error ${response.status}: ${text}`);
  }
  return response.json();
}

// Load attempts from Teable
async function loadAttempts(): Promise<Attempt[]> {
  const data = await teableRequest("GET", `/table/${ATTEMPTS_TABLE}/record?take=1000`);
  const records = ((data as any).records || []).filter((r: any) => r.fields.Name);
  return records.map((r: any) => ({
    id: `${r.fields.timestamp}-${r.id.slice(-6)}`,
    word: r.fields.Name,
    phrase: r.fields.phrase || "",
    position: r.fields.position || "first",
    round: r.fields.round || 1,
    tries: r.fields.tries || 1,
    date: r.fields.date ? r.fields.date.split("T")[0] : new Date().toISOString().split("T")[0],
    time: r.fields.time || "00:00:00",
    timestamp: r.fields.timestamp || Date.now(),
  }));
}

// Load stickers from Teable
async function loadStickerRecords() {
  const data = await teableRequest("GET", `/table/${STICKERS_TABLE}/record?take=1000`);
  return (data as any).records || [];
}

async function loadStickers(): Promise<Record<string, string>> {
  const records = await loadStickerRecords();
  const stickers: Record<string, string> = {};
  for (const r of records) {
    const date = r.fields.date ? r.fields.date.split("T")[0] : "";
    if (date && r.fields.emoji) {
      stickers[date] = r.fields.emoji;
    }
  }
  return stickers;
}

// Save attempt to Teable
async function saveAttempt(attempt: Attempt) {
  await teableRequest("POST", `/table/${ATTEMPTS_TABLE}/record`, {
    records: [{
      fields: {
        Name: attempt.word,
        phrase: attempt.phrase,
        position: attempt.position,
        round: attempt.round,
        tries: attempt.tries,
        date: attempt.date,
        timestamp: attempt.timestamp,
      }
    }],
    typecast: true
  });
}

// Save stickers to Teable
async function syncStickers(stickers: Record<string, string>) {
  const existing = await loadStickerRecords();
  const existingByDate = new Map<string, any>();
  for (const record of existing) {
    const date = record.fields.date ? record.fields.date.split("T")[0] : "";
    if (date) existingByDate.set(date, record);
  }

  for (const [date, emoji] of Object.entries(stickers)) {
    const record = existingByDate.get(date);
    if (!record) {
      await teableRequest("POST", `/table/${STICKERS_TABLE}/record`, {
        records: [{
          fields: {
            date,
            emoji,
          }
        }],
        typecast: true
      });
      continue;
    }

    if (record.fields.emoji !== emoji) {
      await teableRequest("PATCH", `/table/${STICKERS_TABLE}/record`, {
        records: [{
          id: record.id,
          fields: { emoji }
        }],
        typecast: true
      });
    }
  }

  for (const [date, record] of existingByDate.entries()) {
    if (!(date in stickers)) {
      await teableRequest("DELETE", `/table/${STICKERS_TABLE}/record`, {
        recordIds: [record.id]
      });
    }
  }
}

function checkAuth(c: Context): boolean {
  const secret = process.env.SPEECH_GAME_PASSCODE;
  if (!secret) return false;

  const auth = c.req.header("authorization");
  if (auth?.startsWith("Bearer ")) {
    const token = auth.slice(7);
    const aBuf = Buffer.from(token);
    const bBuf = Buffer.from(secret);
    if (aBuf.length === bBuf.length && timingSafeEqual(aBuf, bBuf)) return true;
  }

  const passcode = c.req.header("X-Passcode");
  if (passcode) {
    const aBuf = Buffer.from(passcode);
    const bBuf = Buffer.from(secret);
    if (aBuf.length === bBuf.length && timingSafeEqual(aBuf, bBuf)) return true;
  }

  return false;
}

export default async (c: Context) => {
  const method = c.req.method;

  if (method === "GET") {
    if (!checkAuth(c)) return c.json({ error: "Unauthorized" }, 401);
    try {
      const [attempts, stickers] = await Promise.all([loadAttempts(), loadStickers()]);
      return c.json({ attempts, stickers });
    } catch (e: any) {
      return c.json({ error: "Failed to load data", message: e.message }, 500);
    }
  }

  if (method === "POST") {
    if (!checkAuth(c)) return c.json({ error: "Unauthorized" }, 401);
    const body = await c.req.json();

    if (body?.type === "attempt" || body?.word) {
      const attempt: Attempt = {
        id: body.id || crypto.randomUUID(),
        word: body.word,
        phrase: body.phrase || "",
        position: body.position || "first",
        round: body.round || 1,
        tries: body.tries || 1,
        date: body.date || new Date().toISOString().split("T")[0],
        time: body.time || new Date().toLocaleTimeString("en-CA", { hour12: false }),
        timestamp: body.timestamp || Date.now(),
      };
      try {
        await saveAttempt(attempt);
        const attempts = await loadAttempts();
        return c.json({ ok: true, totalAttempts: attempts.length });
      } catch (e: any) {
        return c.json({ error: "Failed to save attempt", message: e.message }, 500);
      }
    }

    if (body?.action === "saveStickers" && body.stickers) {
      try {
        await syncStickers(body.stickers);
        const stickers = await loadStickers();
        return c.json({ ok: true, stickerCount: Object.keys(stickers).length });
      } catch (e: any) {
        return c.json({ error: "Failed to save stickers", message: e.message }, 500);
      }
    }

    return c.json({ error: "Unknown action" }, 400);
  }

  if (method === "DELETE") {
    if (!checkAuth(c)) return c.json({ error: "Unauthorized" }, 401);
    // Clear operations - Teable doesn't have a bulk delete through API easily
    // Return success but log that manual cleanup may be needed
    return c.json({ ok: true, note: "Data cleared in local state. Teable records preserved." });
  }

  return c.json({ error: "Method not allowed" }, 405);
};
