export default async (c: Context) => {
  // Check X-Zo-User header (set by Zo for authenticated requests)
  const zoUser = c.req.header("X-Zo-User");
  if (zoUser === "curtastrophe") {
    return c.json({ authenticated: true, method: "zo_user" });
