import type { Context } from "hono";
import { Database } from "bun:sqlite";

const DB_PATH = "/home/workspace/Projects/zo-trivia/trivia.db";

function getTodayMST(): string {
  return new Date().toLocaleDateString("en-CA", { timeZone: "America/Edmonton" });
}

async function validateSession(c: Context): Promise<string | null> {
  // 1. Check X-Zo-User header (set by Zo for authenticated requests)
  const zoUser = c.req.header("X-Zo-User") || c.req.header("x-zo-user");
  if (zoUser && zoUser.length > 0) return zoUser;

  // 2. Allow Zo API key for automation (Bearer token)
  const authHeader = c.req.header("Authorization");
  if (authHeader?.startsWith("Bearer ")) {
    const token = authHeader.slice(7);
    if (process.env.ZO_API_KEY && token === process.env.ZO_API_KEY) {
      return "curtastrophe"; // Admin handle
    }
  }

  // 3. Check for Zo session cookie
  const cookieHeader = c.req.header("Cookie") || "";
  const hasSession = cookieHeader.includes("zo_session") || 
                     cookieHeader.includes("auth_token") ||
                     cookieHeader.includes("x-zo-session");

  if (hasSession) return "curtastrophe"; // Assume owner if session exists

  // 4. Check Referer - if from authenticated page, allow
  const referer = c.req.header("Referer") || "";
  if (referer.includes("curtastrophe.zo.space") || referer.includes("localhost")) {
    // We don't have the handle here, but we know they are coming from a trusted origin
    // For trivia, we might want to still require a handle for leaderboard
  }

  return null;
}

export default async (c: Context) => {
  const method = c.req.method;
  const userHandle = await validateSession(c);
  const today = getTodayMST();

  const db = new Database(DB_PATH);

  try {
    if (method === "GET") {
      // Fetch today's question
      const question = db.query(`
        SELECT id, play_date, question, options, explanation
        FROM questions
        WHERE play_date = ?
      `).get(today) as any;

      if (!question) {
        return c.json({ error: "No question available for today" }, 404);
      }

      // Check if user already answered
      let alreadyAnswered = false;
      let previousAnswer = null;

      if (userHandle) {
        const existing = db.query(`
          SELECT selected_index, is_correct, score, streak 
          FROM leaderboard 
          WHERE user_handle = ? AND play_date = ?
        `).get(userHandle, today) as any;

        if (existing) {
          alreadyAnswered = true;
          previousAnswer = {
            selected_index: existing.selected_index,
            is_correct: !!existing.is_correct,
            correct_index: question.correct_index, // Note: only returned if already answered
            explanation: question.explanation,
            score: existing.score,
            streak: existing.streak
          };
        }
      }

      return c.json({
        id: question.id,
        play_date: question.play_date,
        question: question.question,
        options: JSON.parse(question.options),
        already_answered: alreadyAnswered,
        previous_answer: previousAnswer,
        user_handle: userHandle
      });
    }

    if (method === "POST") {
      const { selected_index, user_handle } = await c.req.json();
      const finalHandle = userHandle || userHandle || "anonymous";

      const question = db.query(`
        SELECT id, play_date, question, options, correct_index, explanation
        FROM questions
        WHERE play_date = ?
      `).get(today) as any;

      if (!question) {
        return c.json({ error: "No question found for today" }, 404);
      }

      const isCorrect = selected_index === question.correct_index;

      // Check for existing answer
      const existing = db.query(`
        SELECT id FROM leaderboard WHERE user_handle = ? AND play_date = ?
      `).get(finalHandle, today);

      if (existing) {
        return c.json({ error: "Already answered today" }, 400);
      }

      // Calculate streak
      const yesterday = new Date(new Date().getTime() - 86400000).toLocaleDateString("en-CA", { timeZone: "America/Edmonton" });
      const prevRow = db.query(`
        SELECT streak FROM leaderboard WHERE user_handle = ? AND play_date = ? AND is_correct = 1
      `).get(finalHandle, yesterday) as any;

      const streak = isCorrect ? (prevRow ? prevRow.streak + 1 : 1) : 0;
      const score = isCorrect ? 10 : 0;

      // Record answer
      db.query(`
        INSERT INTO leaderboard (user_handle, play_date, is_correct, score, streak, selected_index)
        VALUES (?, ?, ?, ?, ?, ?)
      `).run(finalHandle, today, isCorrect ? 1 : 0, score, streak, selected_index);

      // Calculate global stats for today
      const stats = db.query(`
        SELECT 
          COUNT(*) as total_players,
          SUM(is_correct) as correct_count
        FROM leaderboard
        WHERE play_date = ?
      `).get(today) as any;

      const totalPlayers = stats.total_players || 1;
      const correctCount = stats.correct_count || 0;
      const correctPercentage = Math.round((correctCount / totalPlayers) * 100);

      // Calculate percentile for this user's score if correct
      let rankPhrase = "";
      if (isCorrect) {
        const betterThan = db.query(`
          SELECT COUNT(*) as count FROM leaderboard 
          WHERE play_date = ? AND is_correct = 0
        `).get(today) as any;
        const percentile = Math.round((betterThan.count / totalPlayers) * 100);
        rankPhrase = percentile > 0 ? `You're in the top ${100 - percentile}% of players!` : "Great job!";
      } else {
        rankPhrase = `${correctCount} out of ${totalPlayers} players got this right.`;
      }

      return c.json({
        is_correct: isCorrect,
        correct_index: question.correct_index,
        explanation: question.explanation,
        user_streak: streak,
        stats: {
          total_players: totalPlayers,
          correct_count: correctCount,
          correct_percentage: correctPercentage,
          rank_phrase: rankPhrase
        }
      });
    }

    return c.json({ error: "Method not allowed" }, 405);
  } catch (error) {
    console.error("Trivia API error:", error);
    return c.json({ error: "Internal server error" }, 500);
  } finally {
    db.close();
  }
};
