import type { Context } from "hono";

const TEABLE_BASE = "https://app.teable.io/api";
const SUBSCRIBERS_TABLE = "tblUhUiUmvKbaxA2cx4";
const API_KEY = process.env.TEABLE_API_KEY;

async function teableReq(method: string, endpoint: string, body?: any): Promise<any> {
  const opts: any = {
    method,
    headers: { Authorization: `Bearer ${API_KEY}` }
  };
  if (body) {
    opts.headers["Content-Type"] = "application/json";
    opts.body = JSON.stringify(body);
  }
  const res = await fetch(`${TEABLE_BASE}${endpoint}`, opts);
  if (!res.ok) {
    const text = await res.text();
    throw new Error(`${method} ${endpoint}: ${res.status} ${text}`);
  }
  return res.json();
}

const SENDFOX_BASE = "https://api.sendfox.com";

async function sendfoxReq(method: string, path: string, body?: any): Promise<any> {
  const token = process.env.SENDFOX_ACCESS_TOKEN;
  const opts: any = { method, headers: { Authorization: `Bearer ${token}`, Accept: "application/json" } };
  if (body) {
    opts.headers["Content-Type"] = "application/json";
    opts.body = JSON.stringify(body);
  }
  const res = await fetch(`${SENDFOX_BASE}${path}`, opts);
  const text = await res.text();
  if (!res.ok) throw new Error(`${method} ${path}: ${res.status} ${text}`);
  return text ? JSON.parse(text) : null;
}

async function ensureSendfoxSubscriber(email: string): Promise<void> {
  const token = process.env.SENDFOX_ACCESS_TOKEN;
  if (!token) { console.log("SENDFOX_ACCESS_TOKEN not set; skipping SendFox sync"); return; }
  const lists = await sendfoxReq("GET", "/lists?per_page=100");
  let list = lists.data?.find((l: any) => l.name === "Zo Trivia");
  if (!list) list = await sendfoxReq("POST", "/lists", { name: "Zo Trivia" });
  const listId: number = list.id;
  const search = await sendfoxReq("GET", `/contacts?search=${encodeURIComponent(email)}`);
  const found = search.data?.find((c: any) => c.email?.toLowerCase() === email.toLowerCase());
  if (found) {
    const detail = await sendfoxReq("GET", `/contacts/${found.id}`);
    const current: number[] = Array.isArray(detail.lists) ? detail.lists.map((l: any) => l.id) : [];
    const merged = Array.from(new Set([...current, listId]));
    await sendfoxReq("PATCH", `/contacts/${found.id}`, { lists: merged });
  } else {
    await sendfoxReq("POST", "/contacts", { email, lists: [listId] });
  }
}

export default async (c: Context) => {
  try {
    const { email } = await c.req.json();

    if (!email || !email.includes("@")) {
      return c.json({ error: "Valid email required" }, 400);
    }

    // 1. Sync to Teable
    // Get all subscribers
    const existing = await teableReq("GET", `/table/${SUBSCRIBERS_TABLE}/record?take=200`);

    // Check if already subscribed
    const alreadySubscribed = existing.records?.find((r: any) => 
      r.fields.email === email
    );

    if (!alreadySubscribed) {
      // Add new subscriber to Teable
      await teableReq("POST", `/table/${SUBSCRIBERS_TABLE}/record`, {
        records: [{
          fields: {
            email: email,
            subscribed_at: new Date().toISOString()
          }
        }],
        typecast: true
      });
    }

    // 2. Sync to local databases (for email agent consistency)
    try {
      const { Database } = await import("bun:sqlite");

      // Update trivia.db (sqlite fallback)
      const triviaDb = new Database("/home/workspace/Projects/zo-trivia/trivia.db");
      triviaDb.run(
        "INSERT OR REPLACE INTO subscribers (email) VALUES (?)",
        [email]
      );
      triviaDb.close();

      console.log(`Synced ${email} to local databases`);
    } catch (dbErr) {
      console.error("Local DB sync error:", dbErr);
    }
    try {
      await ensureSendfoxSubscriber(email);
    } catch (sendfoxErr) {
      console.error("SendFox sync error:", sendfoxErr);
    }

    return c.json({ success: true, message: alreadySubscribed ? "Already subscribed" : "Subscribed successfully" });

  } catch (error) {
    console.error("Subscribe error:", error);
    return c.json({ 
      error: "Subscription failed", 
      message: error instanceof Error ? error.message : "Unknown error" 
    }, 500);
  }
};
