import type { Context } from "hono";
import { Database } from "bun:sqlite";

const DB_PATH = "/home/workspace/Projects/zo-trivia/trivia.db";

function getMSTDate(): string {
  const now = new Date();
  const mstOffset = -7 * 60;
  const localOffset = now.getTimezoneOffset();
  const mstDate = new Date(now.getTime() + (localOffset + mstOffset) * 60 * 1000);
  return mstDate.toISOString().split("T")[0];
}

function getWeekBounds(dateStr: string): { start: string; end: string } {
  const date = new Date(dateStr + "T00:00:00");
  const day = date.getDay();
  const mondayOffset = day === 0 ? -6 : 1 - day;
  const monday = new Date(date.getTime() + mondayOffset * 86400000);
  const sunday = new Date(monday.getTime() + 6 * 86400000);
  return {
    start: monday.toISOString().split("T")[0],
    end: sunday.toISOString().split("T")[0]
  };
}

function getMonthBounds(dateStr: string): { start: string; end: string } {
  const year = dateStr.substring(0, 4);
  const month = dateStr.substring(5, 7);
  return {
    start: `${year}-${month}-01`,
    end: `${year}-${month}-31`
  };
}

export default async (c: Context) => {
  const db = new Database(DB_PATH);

  try {
    const today = getMSTDate();
    const { start: weekStart, end: weekEnd } = getWeekBounds(today);
    const { start: monthStart, end: monthEnd } = getMonthBounds(today);

    const periods = {
      today: { start: today, end: today },
      week: { start: weekStart, end: weekEnd },
      month: { start: monthStart, end: monthEnd },
      alltime: { start: "1970-01-01", end: "2099-12-31" }
    };

    const result: Record<string, Array<{ rank: number; user_handle: string; score: number; streak: number }>> = {};

    for (const [period, bounds] of Object.entries(periods)) {
      const rows = db.query(`
        SELECT 
          user_handle,
          SUM(is_correct) as total_correct,
          MAX(streak) as best_streak
        FROM leaderboard
        WHERE play_date >= ? AND play_date <= ?
        GROUP BY user_handle
        ORDER BY total_correct DESC, best_streak DESC
        LIMIT 10
      `).all(bounds.start, bounds.end) as Array<{ user_handle: string; total_correct: number; best_streak: number }>;

      result[period] = rows.map((row, idx) => ({
        rank: idx + 1,
        user_handle: row.user_handle,
        score: row.total_correct,
        streak: row.best_streak
      }));
    }

    return c.json(result);
  } catch (error) {
    console.error("Leaderboard API error:", error);
    return c.json({ error: "Internal server error" }, 500);
  } finally {
    db.close();
  }
};
