const DB_PATH = "/home/workspace/Projects/zo-trivia/trivia.db";

function getTodayMST(): string {
  const date = new Date();
  const options = { timeZone: "America/Edmonton", year: "numeric", month: "2-digit", day: "2-digit" } as const;
  const formatter = new Intl.DateTimeFormat("en-CA", options);
  const parts = formatter.formatToParts(date);
  const year = parts.find(p => p.type === "year")?.value;
  const month = parts.find(p => p.type === "month")?.value;
  const day = parts.find(p => p.type === "day")?.value;
  return `${year}-${month}-${day}`;
}

export default async (c: Context) => {
  try {
    const db = new Database(DB_PATH);
    const count = parseInt(c.req.query("count") || "10", 10);
    const limit = Math.min(count, 50);
    const userHandle = c.req.header("X-Zo-User");
    const today = getTodayMST();
    const isZoUser = userHandle && !userHandle.startsWith("anon_");

    let availableQuery = `
      SELECT id, play_date, question, options, correct_index, explanation
      FROM questions
      WHERE play_date <= $today
    `;

    let query: ReturnType<typeof db.query>;

    if (userHandle) {
      // Exclude questions this user has already answered
      query = db.query(`
        SELECT q.play_date, q.question, q.options, q.correct_index, q.explanation
        FROM questions q
        WHERE q.play_date <= ?
          AND q.play_date NOT IN (
            SELECT play_date FROM leaderboard WHERE user_handle = ?
          )
        ORDER BY RANDOM()
        LIMIT ?
      `);
      const rows = query.all(today, userHandle, limit) as any[];
      const questions = rows.map(row => ({
        play_date: row.play_date,
        question: row.question,
        options: JSON.parse(row.options),
        correct_index: row.correct_index,
        explanation: row.explanation
      }));
      db.close();
      return c.json({ questions, count: questions.length, filtered: true });
    } else {
      // Anonymous users: exclude already-answered via localStorage (handled on client)
      query = db.query(`
        SELECT play_date, question, options, correct_index, explanation
        FROM questions
        WHERE play_date <= ?
        ORDER BY RANDOM()
        LIMIT ?
      `);
      const rows = query.all(today, limit) as any[];
      const questions = rows.map(row => ({
        play_date: row.play_date,
        question: row.question,
        options: JSON.parse(row.options),
        correct_index: row.correct_index,
        explanation: row.explanation
      }));
      db.close();
      return c.json({ questions, count: questions.length, filtered: false });
    }
  } catch (error) {
    console.error("Random trivia API error:", error);
    return c.json({ error: "Internal server error" }, 500);
  }
};' public=True source='custom'

