import type { Context } from "hono";

const VOI_LOCKDOWN = (process.env.VOI_LOCKDOWN ?? "true") !== "false";
const ZO_TOKEN = process.env.ZO_CLIENT_IDENTITY_TOKEN || "";
const MODEL = "vercel:minimax/minimax-m2.7";

const HOMEPAGE_KB: Record<string, string> = {
  identity:
    "This site is ZOS, also called ZenOS, by Zenlyte. It is presented as a personal site rebuilt as an operating system and built entirely on Zo Computer for the Zo Computer Challenge.",
  about:
    "The site presents Zenlyte as a Data & Analytics professional and AI builder working with Zo Computer.",
  focus:
    "The homepage highlights work across data, AI, automation, building, and community.",
  play:
    "Interactive homepage features include Daily Zo Trivia and a Zo Icon Configurator.",
  blog:
    "The homepage links to a blog and previews recent posts.",
  social:
    "Public social links include GitHub, X, and Instagram.",
  contact:
    "The homepage includes a contact form and the public email info@zenlytics.net.",
  cta:
    "Calls to action include viewing projects, reading the blog, and sending a contact message.",
  positioning:
    "The homepage positions the project as ZOS or ZenOS, a personal operating-system-style site built on Zo Computer.",
};

const KB_TEXT = Object.entries(HOMEPAGE_KB)
  .map(([k, v]) => `[${k}] ${v}`)
  .join("\n");

const REFUSAL = "I can only answer based on information publicly shown on the homepage.";

const INJECTION_PATTERNS = [
  /ignore (all |the |your |previous |prior )?(instructions|rules|prompt)/i,
  /disregard (all |the |your )?(instructions|rules|prompt)/i,
  /system prompt/i,
  /reveal (the |your |any )?(system|hidden|secret|private|internal)/i,
  /\b(jailbreak|dan mode|developer mode|unrestricted|uncensored)\b/i,
  /\b(password|api[- ]?key|token|credentials?)\b/i,
  /\b(secret|hidden)\s+(route|page|path|url|link|endpoint)/i,
  /\b\/secret\b|\babout-the-build\b|\btrivia\b.*\b(answer|solution)/i,
  /override.*\b(safety|rules|guard|policy)/i,
];

const RATE_MAX = 10;
const RATE_WINDOW_MS = 60_000;
const rate = new Map<string, number[]>();

const CACHE_MAX = 100;
const CACHE_TTL_MS = 24 * 60 * 60 * 1000;
type Confidence = "high" | "medium" | "low";
interface VoiResponse {
  allowed: boolean;
  answer: string;
  confidence: Confidence;
  source_keys: string[];
  cached?: boolean;
}

type CacheVal = { at: number; payload: VoiResponse };
const cache = new Map<string, CacheVal>();
const VALID_KEYS = new Set(Object.keys(HOMEPAGE_KB));

function isLikelyInjection(s: string): boolean {
  return INJECTION_PATTERNS.some((re) => re.test(s));
}

function rateLimited(ip: string): boolean {
  const now = Date.now();
  const arr = (rate.get(ip) || []).filter((t) => now - t < RATE_WINDOW_MS);
  if (arr.length >= RATE_MAX) {
    rate.set(ip, arr);
    return true;
  }
  arr.push(now);
  rate.set(ip, arr);
  return false;
}

function normKey(q: string): string {
  return q.toLowerCase().replace(/\s+/g, " ").replace(/[^a-z0-9 ]/g, "").trim();
}

function cacheGet(k: string): VoiResponse | null {
  const v = cache.get(k);
  if (!v) return null;
  if (Date.now() - v.at > CACHE_TTL_MS) {
    cache.delete(k);
    return null;
  }
  cache.delete(k);
  cache.set(k, v);
  return v.payload;
}

function cacheSet(k: string, payload: VoiResponse) {
  cache.set(k, { at: Date.now(), payload });
  if (cache.size > CACHE_MAX) {
    const first = cache.keys().next().value;
    if (first !== undefined) cache.delete(first);
  }
}

function refusal(): VoiResponse {
  return {
    allowed: false,
    answer: REFUSAL,
    confidence: "low",
    source_keys: [],
  };
}

function localAnswer(question: string): VoiResponse | null {
  const q = question.toLowerCase();

  if (/(who|what).*(zenlyte|zenos|zos)|what is zos|what is zenos|about (this|the) (site|homepage|page)|what is this (site|page)/.test(q)) {
