  byokId: string;
  contextWindow: number | null;
  priority: number | null;
};

type ProviderGroup = {
  provider: string;
  models: ByokModel[];
};

type ApiResponse = {
  fetchedAt: string;
  source: string;
  totalUpstream: number;
  totalByok: number;
  groups: ProviderGroup[];
  servedFrom: "live" | "cache" | string;
  cacheAgeMs: number;
};

const theme = {
  background: "#0b0b0d",
  foreground: "#f5f5f4",
  card: "#161618",
  cardHover: "#1c1c1f",
  border: "#27272a",
  muted: "#a1a1aa",
  faint: "#71717a",
  accent: "#3b82f6",
  accentFg: "#ffffff",
  byokColor: "#a855f7",
};

function fmtContext(n: number | null): string {
  if (n == null) return "—";
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`;
  if (n >= 1_000) return `${(n / 1_000).toFixed(0)}K`;
  return String(n);
}

function fmtAge(ms: number): string {
  if (ms < 60_000) return `${Math.round(ms / 1000)}s ago`;
  if (ms < 3_600_000) return `${Math.round(ms / 60_000)}m ago`;
  return `${Math.round(ms / 3_600_000)}h ago`;
}

function CopyButton({ value }: { value: string }) {
  const [copied, setCopied] = useState(false);
  return (
    <button
      onClick={() => {
        navigator.clipboard.writeText(value).then(() => {
          setCopied(true);
          setTimeout(() => setCopied(false), 1200);
        });
      }}
      className="opacity-0 group-hover:opacity-100 transition-opacity p-1 rounded hover:bg-zinc-700 text-zinc-400 hover:text-white"
      title={`Copy: ${value}`}
    >
      {copied ? <Check className="w-3.5 h-3.5 text-emerald-400" /> : <Copy className="w-3.5 h-3.5" />}
    </button>
  );
}

export default function ByokReference() {
  const [data, setData] = useState<ApiResponse | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [filter, setFilter] = useState("");
  const [onlyByok, setOnlyByok] = useState(false);
  const [refreshTick, setRefreshTick] = useState(0);
  const [now, setNow] = useState(Date.now());

  const load = async () => {
    setLoading(true);
    setError(null);
    try {
      const resp = await fetch("/api/byok-reference", { cache: "no-store" });
      if (!resp.ok) throw new Error(`API ${resp.status}`);
      const json = (await resp.json()) as ApiResponse;
      setData(json);
    } catch (e) {
      setError(String(e));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
  }, [refreshTick]);

  // Tick once a minute so the "freshness" badge updates without manual reload
  useEffect(() => {
    const t = setInterval(() => setNow(Date.now()), 30_000);
    return () => clearInterval(t);
  }, []);

  const filtered = useMemo(() => {
    if (!data) return [];
    const q = filter.trim().toLowerCase();
    return data.groups
      .map((g) => ({
        ...g,
        models: g.models.filter((m) => {
          if (onlyByok && !m.byokId.startsWith("byok:")) return false;
          if (!q) return true;
          return (
            m.friendlyName.toLowerCase().includes(q) ||
            m.byokId.toLowerCase().includes(q) ||
            g.provider.toLowerCase().includes(q)
          );
        }),
      }))
      .filter((g) => g.models.length > 0);
  }, [data, filter, onlyByok]);

  const totalShown = filtered.reduce((n, g) => n + g.models.length, 0);
  const cacheAgeSec = data ? Math.round((now - new Date(data.fetchedAt).getTime()) / 1000) : 0;
  const isStale = cacheAgeSec > 600; // >10 min old

  return (
    <main
      style={
        {
          "--page-bg": theme.background,
          "--page-fg": theme.foreground,
          "--page-card": theme.card,
          "--page-border": theme.border,
          "--page-muted": theme.muted,
        } as React.CSSProperties
      }
      className="min-h-screen bg-[var(--page-bg)] text-[var(--page-fg)]"
    >
      {/* Header */}
      <div
        className="sticky top-0 z-30 border-b backdrop-blur"
        style={{ backgroundColor: "rgba(11,11,13,0.85)", borderColor: theme.border }}
      >
        <div className="max-w-6xl mx-auto px-6 py-4 flex flex-wrap items-center gap-4">
          <div className="flex items-center gap-3">
            <div
              className="w-10 h-10 rounded-xl flex items-center justify-center"
              style={{ background: `linear-gradient(135deg, ${theme.accent}, ${theme.byokColor})` }}
            >
              <Database className="w-5 h-5 text-white" />
            </div>
            <div>
              <h1 className="text-xl font-bold">BYOK Models Reference</h1>
              <p className="text-xs" style={{ color: theme.faint }}>
                {data ? `${data.totalByok} BYOK models across ${data.groups.filter((g) => g.models.length).length} providers` : "Loading…"}
              </p>
            </div>
          </div>

          <div className="flex-1" />

          {data && (
            <div
              className="flex items-center gap-2 px-3 py-1.5 rounded-lg border text-xs"
              style={{
                borderColor: isStale ? "#b91c1c" : theme.border,
                backgroundColor: theme.card,
                color: isStale ? "#fca5a5" : theme.muted,
              }}
              title={`Source: ${data.source}\nFetched: ${data.fetchedAt}`}
            >
              {isStale ? <AlertCircle className="w-3.5 h-3.5" /> : <Clock className="w-3.5 h-3.5" />}
              <span className="font-mono">{fmtAge(now - new Date(data.fetchedAt).getTime())}</span>
              <span className="text-zinc-600">·</span>
              <span style={{ color: data.servedFrom === "live" ? "#86efac" : theme.faint }}>
                {data.servedFrom}
              </span>
            </div>
          )}

          <button
            onClick={() => setRefreshTick((n) => n + 1)}
            disabled={loading}
            className="flex items-center gap-2 px-3 py-1.5 rounded-lg border text-sm font-medium transition-colors hover:bg-zinc-800 disabled:opacity-50"
            style={{ borderColor: theme.border, color: theme.foreground }}
          >
            <RefreshCw className={`w-4 h-4 ${loading ? "animate-spin" : ""}`} />
            Refresh
          </button>
        </div>

        {/* Search row */}
        <div className="max-w-6xl mx-auto px-6 pb-4 flex flex-wrap items-center gap-3">
          <div className="relative flex-1 min-w-[240px]">
            <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2" style={{ color: theme.muted }} />
            <input
              type="text"
              value={filter}
              onChange={(e) => setFilter(e.target.value)}
              placeholder="Search model, ID, or provider…"
              className="w-full pl-9 pr-4 py-2 rounded-lg border text-sm outline-none focus:border-blue-500"
              style={{ backgroundColor: theme.card, borderColor: theme.border, color: theme.foreground }}
            />
          </div>
          <label className="flex items-center gap-2 text-xs cursor-pointer select-none" style={{ color: theme.muted }}>
            <input
              type="checkbox"
              checked={onlyByok}
              onChange={(e) => setOnlyByok(e.target.checked)}
              className="rounded border-zinc-600 bg-zinc-800"
            />
            Only show byok: IDs
          </label>
          <div className="text-xs" style={{ color: theme.faint }}>
            {filter && `${totalShown} match${totalShown === 1 ? "" : "es"}`}
          </div>
        </div>
      </div>

      {/* Body */}
      <div className="max-w-6xl mx-auto px-6 py-6">
        {error && (
          <div className="border rounded-lg p-4 mb-6 flex items-start gap-3" style={{ borderColor: "#7f1d1d", backgroundColor: "#1c0a0a" }}>
            <AlertCircle className="w-5 h-5 text-red-400 flex-shrink-0 mt-0.5" />
            <div>
              <div className="font-semibold text-red-300">Failed to load</div>
              <div className="text-sm text-red-400/80 font-mono mt-1">{error}</div>
            </div>
          </div>
        )}

        {loading && !data && (
          <div className="flex items-center justify-center py-20" style={{ color: theme.muted }}>
            <RefreshCw className="w-6 h-6 animate-spin" />
          </div>
        )}

        {data && filtered.length === 0 && (
          <div className="text-center py-20" style={{ color: theme.muted }}>
            No matches for "<span className="font-mono">{filter}</span>".
          </div>
        )}

        {filtered.map((group) => (
          <section key={group.provider} className="mb-8">
            <div className="flex items-baseline gap-3 mb-3">
              <h2 className="text-lg font-bold tracking-tight">{group.provider}</h2>
              <span className="text-xs font-mono" style={{ color: theme.faint }}>
                {group.models.length} model{group.models.length === 1 ? "" : "s"}
              </span>
              <div className="flex-1 h-px" style={{ backgroundColor: theme.border }} />
            </div>

            <div
              className="rounded-xl border overflow-hidden"
              style={{ borderColor: theme.border, backgroundColor: theme.card }}
            >
              <table className="w-full text-sm">
                <thead>
                  <tr style={{ backgroundColor: "rgba(255,255,255,0.02)" }}>
                    <th
                      className="text-left px-4 py-2.5 text-xs font-semibold uppercase tracking-wider"
                      style={{ color: theme.muted }}
                    >
                      Friendly name
                    </th>
                    <th
                      className="text-left px-4 py-2.5 text-xs font-semibold uppercase tracking-wider"
                      style={{ color: theme.muted }}
                    >
                      BYOK ID
                    </th>
                    <th
                      className="text-right px-4 py-2.5 text-xs font-semibold uppercase tracking-wider"
                      style={{ color: theme.muted }}
                    >
                      Context
                    </th>
                    <th
                      className="text-right px-4 py-2.5 text-xs font-semibold uppercase tracking-wider"
                      style={{ color: theme.muted }}
                    >
                      Priority
                    </th>
                  </tr>
                </thead>
                <tbody>
                  {group.models.map((m) => (
                    <tr
                      key={m.byokId}
                      className="group border-t transition-colors hover:bg-zinc-800/40"
                      style={{ borderColor: theme.border }}
                    >
                      <td className="px-4 py-2.5 font-medium">
                        <div className="flex items-center gap-2">
                          <span className="font-mono text-[13px]">{m.friendlyName}</span>
                        </div>
                      </td>
                      <td className="px-4 py-2.5">
                        <div className="flex items-center gap-2">
                          <code
                            className="font-mono text-[12px] truncate max-w-[28rem]"
                            style={{ color: "#d4d4d8" }}
                          >
                            {m.byokId}
                          </code>
                          <CopyButton value={m.byokId} />
                        </div>
                      </td>
                      <td
                        className="px-4 py-2.5 text-right font-mono text-xs"
                        style={{ color: theme.muted }}
                      >
                        {fmtContext(m.contextWindow)}
                      </td>
                      <td
                        className="px-4 py-2.5 text-right font-mono text-xs"
                        style={{ color: theme.muted }}
                      >
                        {m.priority != null ? m.priority.toFixed(1) : "—"}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </section>
        ))}

        {/* Footer */}
        <footer
          className="mt-12 pt-6 border-t text-xs flex flex-wrap items-center gap-x-4 gap-y-1"
          style={{ borderColor: theme.border, color: theme.faint }}
        >
          <span>
            Source: <span className="font-mono">{data?.source ?? "…"}</span>
          </span>
          <span>·</span>
          <span>
            Cached on server: 5 min
          </span>
          <span>·</span>
          <span>
            Verified: never (visual check only — copy with care)
          </span>
          <span className="flex-1" />
          <a
            href="/model-advisor"
            className="flex items-center gap-1 hover:underline"
            style={{ color: theme.muted }}
          >
            Open Model Advisor <ExternalLink className="w-3 h-3" />
          </a>
        </footer>
      </div>
    </main>
  );
}
