import { useState, useEffect } from "react";

export default function BuildinAuth() {
  const [status, setStatus] = useState<"checking" | "connected" | "disconnected">("checking");
  const [spaces, setSpaces] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    checkStatus();
  }, []);

  const checkStatus = async () => {
    try {
      const res = await fetch("/api/buildin/status");
      const data = await res.json();
      if (data.connected) {
        setStatus("connected");
        setSpaces(data.spaces || []);
      } else {
        setStatus("disconnected");
      }
    } catch {
      setStatus("disconnected");
    }
  };

  const handleAuthorize = () => {
    const clientId = process.env.BUILDIN_CLIENT_ID || "";
    const redirectUri = encodeURIComponent("https://curtastrophe.zo.space/api/buildin/callback");
    const state = Math.random().toString(36).substring(7);
    const authUrl = `https://api.buildin.ai/oauth/authorize?client_id=${clientId}&response_type=code&redirect_uri=${redirectUri}&scope=all&state=${state}`;
    window.open(authUrl, "_blank");
  };

  const handleDisconnect = async () => {
    setLoading(true);
    await fetch("/api/buildin/disconnect", { method: "POST" });
    setStatus("disconnected");
    setSpaces([]);
    setLoading(false);
  };

  if (status === "checking") {
    return (
      <div className="min-h-screen bg-zinc-950 text-white p-8 flex items-center justify-center">
        <div className="animate-pulse">Checking connection status...</div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-zinc-950 text-white p-8">
      <div className="max-w-2xl mx-auto">
        <div className="flex items-center gap-4 mb-8">
          <div className="w-12 h-12 bg-gradient-to-br from-purple-500 to-pink-500 rounded-xl flex items-center justify-center text-2xl">
            📝
          </div>
          <div>
            <h1 className="text-2xl font-bold">Buildin.ai Integration</h1>
            <p className="text-zinc-400">Connect your knowledge workspace</p>
          </div>
        </div>

        {status === "disconnected" ? (
          <div className="bg-zinc-900 rounded-2xl p-8 border border-zinc-800">
            <div className="text-center mb-6">
              <div className="w-16 h-16 bg-zinc-800 rounded-full flex items-center justify-center mx-auto mb-4">
                <span className="text-3xl">🔗</span>
              </div>
              <h2 className="text-xl font-semibold mb-2">Connect to Buildin</h2>
              <p className="text-zinc-400 text-sm">
                Authorize Zo to access your Buildin pages and content.
                You'll select which pages to share during authorization.
              </p>
            </div>
            <button
              onClick={handleAuthorize}
              className="w-full py-3 px-4 bg-gradient-to-r from-purple-600 to-pink-600 hover:from-purple-500 hover:to-pink-500 rounded-xl font-medium transition-all"
            >
              Authorize Buildin
            </button>
          </div>
        ) : (
          <div className="space-y-6">
            <div className="bg-zinc-900 rounded-2xl p-6 border border-green-500/30">
              <div className="flex items-center gap-3 mb-4">
                <div className="w-3 h-3 bg-green-500 rounded-full animate-pulse" />
                <span className="text-green-400 font-medium">Connected to Buildin</span>
              </div>
              <p className="text-zinc-400 text-sm mb-4">
                Your connection is active. To access new pages, re-authorize and select additional pages.
              </p>
              <div className="flex gap-3">
                <button
                  onClick={handleAuthorize}
                  className="flex-1 py-2 px-4 bg-zinc-800 hover:bg-zinc-700 rounded-xl font-medium transition-all"
                >
                  Add More Pages
                </button>
                <button
                  onClick={handleDisconnect}
                  disabled={loading}
                  className="py-2 px-4 bg-red-500/20 hover:bg-red-500/30 text-red-400 rounded-xl font-medium transition-all"
                >
                  {loading ? "Disconnecting..." : "Disconnect"}
                </button>
              </div>
            </div>

            {spaces.length > 0 && (
              <div className="bg-zinc-900 rounded-2xl p-6 border border-zinc-800">
                <h3 className="font-semibold mb-4">Accessible Spaces</h3>
                <div className="space-y-2">
                  {spaces.map((space: any) => (
                    <div key={space.id} className="flex items-center gap-3 p-3 bg-zinc-800/50 rounded-xl">
                      <span className="text-lg">{space.icon || "📄"}</span>
                      <span>{space.name}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}

            <div className="bg-amber-500/10 border border-amber-500/30 rounded-2xl p-4">
              <p className="text-amber-200 text-sm">
                <strong>Note:</strong> If you create new pages, click "Add More Pages" to re-authorize and select them.
              </p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
