import { useState, useEffect, useCallback } from "react";
import {
  Briefcase, FileText, TrendingUp, BarChart3, Plus,
  Search, RefreshCw, ExternalLink, ChevronDown, ChevronUp,
  Filter, Download, Eye, CheckCircle2, XCircle, Clock,
  ArrowUpRight, ArrowDownRight, Minus, Loader2, Send,
  Target, Zap, Brain, Shield, Radar, Link2, PlayCircle
} from "lucide-react";

const API_BASE = "/api/career-ops";

const toNumber = (value: unknown): number => {
  if (typeof value === "number") return Number.isFinite(value) ? value : 0;
  if (typeof value === "string") {
    const parsed = parseFloat(value);
    return Number.isFinite(parsed) ? parsed : 0;
  }
  return 0;
};

type PipelineEntry = {
  url: string;
  company: string;
  title: string;
  source: string;
  added_at: string;
};

type Application = {
  id: number | string;
  date: string;
  company: string;
  role: string;
  score: number | string;
  status: string;
  pdf: boolean;
  report: string;
  url?: string;
  notes?: string;
};

type Overview = {
  total: number;
  applied: number;
  interview: number;
  offer: number;
  avgScore: number;
  pdfRate: number;
  scoreDistribution: { green: number; yellow: number; red: number };
  statusBreakdown: Record<string, number>;
  pipelineFunnel?: Array<{ stage: string; count: number }>;
  pendingUrls?: number;
  lastUpdated?: string;
};

type ScanHistory = { entries: any[]; last_scan?: string | null };

type BatchState = { running: boolean; lastRun?: string | null; log?: string };

function ScorePill({ score }: { score: number | string }) {
  const numericScore = toNumber(score);
  const color = numericScore >= 4 ? "bg-emerald-500/15 text-emerald-300 border-emerald-500/30" : numericScore >= 3 ? "bg-amber-500/15 text-amber-300 border-amber-500/30" : "bg-rose-500/15 text-rose-300 border-rose-500/30";
  return <span className={`inline-flex items-center rounded-full border px-2 py-0.5 text-xs font-medium ${color}`}>{numericScore.toFixed(1)}/5</span>;
}

export default function CareerOpsDashboard() {
  const [overview, setOverview] = useState<Overview | null>(null);
  const [applications, setApplications] = useState<Application[]>([]);
  const [pipeline, setPipeline] = useState<PipelineEntry[]>([]);
  const [scanHistory, setScanHistory] = useState<ScanHistory>({ entries: [] });
  const [batchState, setBatchState] = useState<BatchState>({ running: false });
  const [loading, setLoading] = useState(true);
  const [busyAction, setBusyAction] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [expandedApp, setExpandedApp] = useState<string | number | null>(null);
  const [filter, setFilter] = useState<string>("all");
  const [showPipeline, setShowPipeline] = useState(true);

  const loadAll = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const [overviewRes, appsRes, pipelineRes, historyRes] = await Promise.all([
        fetch(API_BASE, { headers: { Accept: "application/json" } }),
        fetch(`${API_BASE}/applications`, { headers: { Accept: "application/json" } }),
        fetch(`${API_BASE}/pipeline`, { headers: { Accept: "application/json" } }),
        fetch(`${API_BASE}/scan-history`, { headers: { Accept: "application/json" } }),
      ]);

      if (!overviewRes.ok || !appsRes.ok || !pipelineRes.ok || !historyRes.ok) throw new Error("Failed to load dashboard data");

      const overviewData = await overviewRes.json();
      const appsData = await appsRes.json();
      const pipelineData = await pipelineRes.json();
      const historyData = await historyRes.json();

      const normalizedApps = (appsData.applications || []).map((app: Application) => ({ ...app, score: toNumber(app.score) }));
      setOverview({ ...overviewData, avgScore: toNumber(overviewData.avgScore) });
      setApplications(normalizedApps);
      setPipeline(pipelineData.pending || []);
      setScanHistory(historyData || { entries: [] });
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load data");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { loadAll(); }, [loadAll]);

  const runScan = async () => {
    setBusyAction("scan");
    try {
      const res = await fetch(`${API_BASE}/scan`, { method: "POST", headers: { "Content-Type": "application/json", Accept: "application/json" }, body: JSON.stringify({ mode: "apply" }) });
      if (!res.ok) throw new Error("Scan failed");
      await loadAll();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Scan failed");
    } finally {
      setBusyAction(null);
    }
  };

  const runBatch = async () => {
    setBusyAction("batch");
    try {
      const res = await fetch(`${API_BASE}/batch`, { method: "POST", headers: { "Content-Type": "application/json", Accept: "application/json" }, body: JSON.stringify({ limit: 5 }) });
      if (!res.ok) throw new Error("Batch failed");
      const data = await res.json();
      setBatchState({ running: true, lastRun: new Date().toISOString(), log: data.log });
      setTimeout(() => loadAll(), 3000);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Batch failed");
    } finally {
      setBusyAction(null);
    }
  };

  const filteredApplications = applications.filter((app) => filter === "all" ? true : app.status.toLowerCase() === filter.toLowerCase());

  if (loading) {
    return <div className="min-h-screen bg-zinc-950 text-zinc-100 flex items-center justify-center"><div className="flex items-center gap-3 text-zinc-400"><Loader2 className="h-5 w-5 animate-spin" /> Loading Career-Ops…</div></div>;
  }

  return (
    <div className="min-h-screen bg-zinc-950 text-zinc-100">
      <header className="border-b border-zinc-800 bg-zinc-950/95 backdrop-blur sticky top-0 z-20">
        <div className="mx-auto max-w-7xl px-6 py-5 flex items-center justify-between gap-4">
          <div>
            <div className="flex items-center gap-3">
              <div className="h-10 w-10 rounded-xl bg-gradient-to-br from-cyan-500 to-violet-600 flex items-center justify-center shadow-lg shadow-cyan-950/40"><Briefcase className="h-5 w-5" /></div>
              <div>
                <h1 className="text-2xl font-semibold tracking-tight">Career-Ops</h1>
                <p className="text-sm text-zinc-400">BI, Data Analytics, Workflow Automation, AI Productivity</p>
              </div>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <button onClick={loadAll} className="inline-flex items-center gap-2 rounded-lg border border-zinc-700 px-3 py-2 text-sm text-zinc-200 hover:bg-zinc-900"><RefreshCw className="h-4 w-4" /> Refresh</button>
            <button onClick={runScan} disabled={busyAction === "scan"} className="inline-flex items-center gap-2 rounded-lg bg-zinc-100 text-zinc-950 px-3 py-2 text-sm font-medium hover:bg-white disabled:opacity-60">{busyAction === "scan" ? <Loader2 className="h-4 w-4 animate-spin" /> : <Radar className="h-4 w-4" />} Scan</button>
            <button onClick={runBatch} disabled={busyAction === "batch"} className="inline-flex items-center gap-2 rounded-lg bg-cyan-500/90 text-zinc-950 px-3 py-2 text-sm font-medium hover:bg-cyan-400 disabled:opacity-60">{busyAction === "batch" ? <Loader2 className="h-4 w-4 animate-spin" /> : <PlayCircle className="h-4 w-4" />} Batch</button>
          </div>
        </div>
      </header>

      <main className="mx-auto max-w-7xl px-6 py-6 space-y-6">
        {error && <div className="rounded-xl border border-rose-800 bg-rose-950/40 px-4 py-3 text-sm text-rose-200">{error}</div>}

        <section className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-5 gap-4">
          {[
            { label: "Evaluations", value: overview?.total ?? 0, icon: FileText, color: "text-blue-400" },
            { label: "Applied", value: overview?.applied ?? 0, icon: Send, color: "text-emerald-400" },
            { label: "Interviews", value: overview?.interview ?? 0, icon: Target, color: "text-violet-400" },
            { label: "Offers", value: overview?.offer ?? 0, icon: CheckCircle2, color: "text-amber-400" },
            { label: "Pipeline Queue", value: overview?.pendingUrls ?? pipeline.length ?? 0, icon: Link2, color: "text-cyan-400" },
          ].map((card) => (
