import React, { useEffect, useState } from "react";
import { 
  Bar, 
  BarChart, 
  CartesianGrid, 
  XAxis, 
  YAxis, 
  Pie, 
  PieChart, 
  Cell, 
  ResponsiveContainer,
  Line,
  LineChart,
  Tooltip as RechartsTooltip
} from "recharts";
import { 
  Card, 
  CardContent, 
  CardDescription, 
  CardHeader, 
  CardTitle,
  CardFooter
} from "@/components/ui/card";
import { 
  ChartConfig, 
  ChartContainer, 
  ChartTooltip, 
  ChartTooltipContent,
  ChartLegend, 
  ChartLegendContent
} from "@/components/ui/chart";
import { 
  Trophy, 
  Users, 
  QuestionMark, 
  Target, 
  TrendingUp, 
  Calendar,
  Activity
} from "lucide-react";

const chartConfig = {
  plays: {
    label: "Total Plays",
    color: "var(--chart-1)",
  },
  correct: {
    label: "Correct Answers",
    color: "var(--chart-2)",
  },
  count: {
    label: "Questions",
    color: "var(--chart-3)",
  },
  status: {
    label: "Status",
  },
  is_correct: {
    label: "Correct",
    color: "var(--chart-2)",
  },
  is_incorrect: {
    label: "Incorrect",
    color: "var(--chart-5)",
  }
} satisfies ChartConfig;

export default function ZoTriviaDashboard() {
  const [stats, setStats] = useState<any>(null);
  const [playsData, setPlaysData] = useState<any[]>([]);
  const [correctnessData, setCorrectnessData] = useState<any[]>([]);
  const [leaderboard, setLeaderboard] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function fetchData() {
      try {
        const [s, p, c, l] = await Promise.all([
          fetch("/data/zo-trivia/api/query?q=stats").then(r => r.json()),
          fetch("/data/zo-trivia/api/query?q=plays-by-date").then(r => r.json()),
          fetch("/data/zo-trivia/api/query?q=correctness-dist").then(r => r.json()),
          fetch("/data/zo-trivia/api/query?q=leaderboard").then(r => r.json())
        ]);
        setStats(s);
        setPlaysData(p);

        // Format correctness for pie chart
        setCorrectnessData(c.map((item: any) => ({
          status: item.status === 1 ? "Correct" : "Incorrect",
          count: item.count,
          fill: item.status === 1 ? "var(--chart-2)" : "var(--chart-5)"
        })));

        setLeaderboard(l);
      } catch (err) {
        console.error("Failed to fetch dashboard data:", err);
      } finally {
        setLoading(false);
      }
    }
    fetchData();
  }, []);

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen bg-zinc-950 text-zinc-400">
        <div className="flex flex-col items-center gap-4">
          <Activity className="w-12 h-12 animate-pulse text-blue-500" />
          <p className="text-lg font-medium tracking-tight">Loading Zo Trivia Insights...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-zinc-950 text-zinc-100 p-6 lg:p-10 space-y-8 font-sans selection:bg-blue-500/30">
      <header className="flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold tracking-tight text-white flex items-center gap-2">
            <Trophy className="text-yellow-500 w-8 h-8" />
            Zo Trivia Insights
          </h1>
          <p className="text-zinc-400 mt-1 max-w-lg">
            Analyzing {stats?.totalQuestions} questions from {stats?.dateRange?.start} to {stats?.dateRange?.end}.
          </p>
        </div>
        <div className="flex gap-2 text-[10px] font-mono uppercase tracking-widest text-zinc-500 bg-zinc-900/50 px-3 py-1.5 rounded-full border border-zinc-800">
          <Calendar className="w-3 h-3" />
          Last Updated: {new Date().toLocaleDateString()}
        </div>
      </header>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard title="Total Plays" value={stats?.totalPlays} icon={<Activity className="w-4 h-4" />} color="text-blue-500" />
        <StatCard title="Avg Accuracy" value={`${stats?.accuracy}%`} icon={<Target className="w-4 h-4" />} color="text-green-500" />
        <StatCard title="Unique Players" value={stats?.uniquePlayers} icon={<Users className="w-4 h-4" />} color="text-purple-500" />
        <StatCard title="Max Streak" value={stats?.maxStreak} icon={<TrendingUp className="w-4 h-4" />} color="text-orange-500" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Plays Over Time */}
        <Card className="lg:col-span-2 bg-zinc-900 border-zinc-800 shadow-xl overflow-hidden">
          <CardHeader className="border-b border-zinc-800">
            <CardTitle className="text-zinc-100 flex items-center gap-2">
              <TrendingUp className="w-5 h-5 text-blue-500" />
              Game Activity
            </CardTitle>
            <CardDescription className="text-zinc-500">Total plays and correctness by date</CardDescription>
          </CardHeader>
          <CardContent className="pt-6">
            <ChartContainer config={chartConfig} className="min-h-[300px] w-full">
              <BarChart accessibilityLayer data={playsData}>
                <CartesianGrid vertical={false} strokeDasharray="3 3" stroke="#27272a" />
                <XAxis
                  dataKey="date"
                  tickLine={false}
                  tickMargin={10}
                  axisLine={false}
                  tickFormatter={(value) => value.split("-").slice(1).join("/")}
                  stroke="#71717a"
                />
                <ChartTooltip content={<ChartTooltipContent />} />
                <ChartLegend content={<ChartLegendContent />} />
                <Bar 
                  dataKey="plays" 
                  fill="var(--color-plays)" 
                  radius={[4, 4, 0, 0]} 
                  name="Total Plays"
                />
                <Bar 
                  dataKey="correct" 
                  fill="var(--color-correct)" 
                  radius={[4, 4, 0, 0]} 
                  name="Correct Answers"
                />
              </BarChart>
            </ChartContainer>
          </CardContent>
        </Card>

        {/* Accuracy Distribution */}
        <Card className="bg-zinc-900 border-zinc-800 shadow-xl overflow-hidden">
          <CardHeader className="border-b border-zinc-800">
            <CardTitle className="text-zinc-100">Accuracy Split</CardTitle>
            <CardDescription className="text-zinc-500">Global correct vs incorrect answers</CardDescription>
          </CardHeader>
          <CardContent className="flex flex-col items-center justify-center min-h-[300px]">
            <ChartContainer config={chartConfig} className="mx-auto aspect-square w-full max-w-[250px]">
              <PieChart>
                <ChartTooltip content={<ChartTooltipContent hideLabel nameKey="status" />} />
                <Pie
                  data={correctnessData}
                  dataKey="count"
                  nameKey="status"
                  innerRadius={60}
                  strokeWidth={5}
                  stroke="transparent"
                />
              </PieChart>
            </ChartContainer>
            <div className="flex justify-center gap-6 mt-4 text-sm">
              <div className="flex items-center gap-2">
                <div className="w-3 h-3 rounded-full bg-[var(--chart-2)]" />
                <span className="text-zinc-400">Correct</span>
              </div>
              <div className="flex items-center gap-2">
                <div className="w-3 h-3 rounded-full bg-[var(--chart-5)]" />
                <span className="text-zinc-400">Incorrect</span>
              </div>
            </div>
          </CardContent>
          <CardFooter className="flex-col border-t border-zinc-800 p-4">
            <div className="text-2xl font-bold text-center w-full">{stats?.accuracy}%</div>
            <div className="text-xs text-zinc-500 text-center w-full uppercase tracking-tighter">Global Accuracy Rating</div>
          </CardFooter>
        </Card>
      </div>

      {/* Leaderboard Table */}
      <Card className="bg-zinc-900 border-zinc-800 shadow-xl overflow-hidden">
        <CardHeader className="border-b border-zinc-800 bg-zinc-900/50">
          <div className="flex items-center justify-between">
            <div>
              <CardTitle className="text-zinc-100 flex items-center gap-2">
                <Trophy className="w-5 h-5 text-yellow-500" />
                Top Players
              </CardTitle>
              <CardDescription className="text-zinc-500">Ranked by total score and streak</CardDescription>
            </div>
          </div>
        </CardHeader>
        <CardContent className="p-0">
          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="border-b border-zinc-800 text-xs uppercase tracking-wider text-zinc-500">
                  <th className="px-6 py-4 font-medium">Player</th>
                  <th className="px-6 py-4 font-medium text-right">Max Score</th>
                  <th className="px-6 py-4 font-medium text-right">Best Streak</th>
                  <th className="px-6 py-4 font-medium text-right">Accuracy</th>
                  <th className="px-6 py-4 font-medium text-right">Games</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-zinc-800/50">
                {leaderboard.map((player, i) => (
                  <tr key={player.user_handle} className="hover:bg-zinc-800/30 transition-colors group">
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-3">
                        <span className={`flex items-center justify-center w-6 h-6 rounded-full text-[10px] font-bold ${
                          i === 0 ? "bg-yellow-500/20 text-yellow-500" : 
                          i === 1 ? "bg-zinc-400/20 text-zinc-400" : 
                          i === 2 ? "bg-orange-500/20 text-orange-500" : "bg-zinc-800 text-zinc-500"
                        }`}>
                          {i + 1}
                        </span>
                        <span className="font-semibold text-zinc-200 group-hover:text-white transition-colors">
                          {player.user_handle}
                        </span>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-right font-mono text-blue-400">{player.max_score}</td>
                    <td className="px-6 py-4 text-right">
                      <span className="inline-flex items-center gap-1 text-orange-400">
                        {player.max_streak}
                        <TrendingUp className="w-3 h-3" />
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <div className="flex flex-col items-end gap-1">
                        <span className="text-zinc-200">
                          {Math.round((player.correct_answers / player.games_played) * 100)}%
                        </span>
                        <div className="w-16 h-1 bg-zinc-800 rounded-full overflow-hidden">
                          <div 
                            className="h-full bg-green-500" 
                            style={{ width: `${(player.correct_answers / player.games_played) * 100}%` }}
                          />
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-right text-zinc-400">{player.games_played}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>

      <footer className="pt-8 text-center text-zinc-600 text-xs">
        <p>Zo Computer Trivia Dataset Visualization &bull; Zenlyte</p>
      </footer>
    </div>
  );
}

function StatCard({ title, value, icon, color }: { title: string, value: any, icon: React.ReactNode, color: string }) {
  return (
    <Card className="bg-zinc-900 border-zinc-800 shadow-lg group hover:border-zinc-700 transition-all">
      <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
        <CardTitle className="text-sm font-medium text-zinc-400 uppercase tracking-tight">{title}</CardTitle>
        <div className={`${color} bg-zinc-800/50 p-2 rounded-lg`}>{icon}</div>
      </CardHeader>
      <CardContent>
        <div className="text-2xl font-bold text-white tracking-tight">{value}</div>
      </CardContent>
    </Card>
  );
}
