export default function KnowledgeGraph() {
  const [stats, setStats] = useState<Stats | null>(null);
  const [browseData, setBrowseData] = useState<BrowseData | null>(null);
  const [query, setQuery] = useState("");
  const [results, setResults] = useState<SearchResult[]>([]);
  const [loading, setLoading] = useState(false);
  const [searching, setSearching] = useState(false);
  const [activeTab, setActiveTab] = useState<"overview" | "visualize" | "browse" | "search" | "recall">("overview");
  const [selectedType, setSelectedType] = useState<string | null>(null);
  const [error, setError] = useState("");

  useEffect(() => {
    fetchStats();
  }, []);

  async function fetchStats() {
    setLoading(true);
    setError("");
    try {
      const res = await fetch("/kg-stats", {
        credentials: "include",
        headers: { "Accept": "application/json" },
      });
      if (!res.ok) throw new Error("Unauthorized or unreachable");
      const data = await res.json();
      setStats(data);
    } catch (e: unknown) {
      setError(String(e));
    } finally {
      setLoading(false);
    }
  }

  async function fetchBrowse() {
    setLoading(true);
    setError("");
    try {
      const res = await fetch("/kg-browse", {
        credentials: "include",
        headers: { "Accept": "application/json" },
      });
      if (!res.ok) throw new Error("Failed to load browse data");
      const data = await res.json();
      setBrowseData(data);
    } catch (e: unknown) {
      setError(String(e));
    } finally {
      setLoading(false);
    }
  }

  async function handleSearch(e: React.FormEvent) {
    e.preventDefault();
    if (!query.trim()) return;
    setSearching(true);
    setError("");
    try {
      const res = await fetch("/kg-search", {
        method: "POST",
        credentials: "include",
        headers: { "Content-Type": "application/json", "Accept": "application/json" },
        body: JSON.stringify({ query, top_k: 10 }),
      });
      if (!res.ok) throw new Error("Search failed");
      const data = await res.json();
      setResults(data.results || []);
      setActiveTab("search");
    } catch (e: unknown) {
      setError(String(e));
    } finally {
      setSearching(false);
    }
  }

  async function handleRecall(e: React.FormEvent) {
    e.preventDefault();
    if (!query.trim()) return;
    setSearching(true);
    setError("");
    try {
      const res = await fetch("/kg-recall", {
        method: "POST",
        credentials: "include",
        headers: { "Content-Type": "application/json", "Accept": "application/json" },
        body: JSON.stringify({ query, top_k: 5 }),
      });
      if (!res.ok) throw new Error("Recall failed");
      const data = await res.json();
      if (data.context) {
        setResults([{ entity: "Context", type: "result", facts: [data.context], relations: [], score: 1 }]);
      } else {
        setResults([]);
