interface ModelEntry { id: string; name: string; provider: string; origin: string; context: number; inputCost: number; outputCost: number; intelligence: number; coding: number; speed: number; throughput: number; isYourModel: boolean; }

const TASKS = [
  { id: "coding", label: "Coding", icon: Code },
  { id: "reasoning", label: "Reasoning", icon: Brain },
  { id: "general", label: "General", icon: Scale },
