  { id: "lowcost", label: "Budget", icon: DollarSign },
];

const BUDGETS = [
  { id: "tight", label: "Tight", desc: "< $1/M" }, { id: "moderate", label: "Moderate", desc: "$1-5/M" },
  { id: "flexible", label: "Flexible", desc: "$5-15/M" }, { id: "unlimited", label: "Unlimited", desc: "Best" },
];

const SPEEDS = [
  { id: "any", label: "Any" }, { id: "fast", label: "Fast" }, { id: "medium", label: "Medium+" },
];

const CONTEXTS = [
  { id: "any", label: "Any" }, { id: "small", label: "<200K" }, { id: "medium", label: "200K-500K" }, { id: "large", label: ">500K" },
];

// Percentile-based scoring using actual AA benchmark data
// Computes relative ranking across all models, then applies task-weighted preferences
function scoreModels(models: ModelEntry[], task: string, budget: string, speed: string, context: string): (ModelEntry & { score: number })[] {
  if (models.length === 0) return [];

  // Collect non-zero values for percentile computation
  const vals = { intelligence: [] as number[], coding: [] as number[], speed: [] as number[], throughput: [] as number[], cost: [] as number[], context: [] as number[] };
  for (const m of models) {
    if (m.intelligence > 0) vals.intelligence.push(m.intelligence);
    if (m.coding > 0) vals.coding.push(m.coding);
    if (m.speed > 0) vals.speed.push(m.speed);
    if (m.throughput > 0) vals.throughput.push(m.throughput);
    const blended = (m.inputCost + m.outputCost) / 2;
    if (blended > 0) vals.cost.push(blended);
    if (m.context > 0) vals.context.push(m.context);
  }
  // Sort each dimension
  for (const k of Object.keys(vals) as (keyof typeof vals)[]) vals[k].sort((a, b) => a - b);

  // Percentile rank: 0-100, where 100 = best in that dimension
  function pctRank(sorted: number[], value: number, higherIsBetter: boolean): number {
    if (sorted.length === 0 || value <= 0) return 50; // neutral for missing data
    let below = 0;
    for (const v of sorted) { if (v < value) below++; else break; }
    const raw = (below / sorted.length) * 100;
    return higherIsBetter ? raw : 100 - raw;
  }

  // Task-based weight profiles: [intelligence, coding, speed, throughput, costEfficiency]
  const weights: Record<string, [number, number, number, number, number]> = {
    coding:    [0.10, 0.45, 0.15, 0.10, 0.20],
    reasoning: [0.70, 0.00, 0.05, 0.05, 0.20],
    general:   [0.40, 0.05, 0.15, 0.15, 0.25],
    longdocs:  [0.50, 0.00, 0.10, 0.15, 0.25],
    lowcost:   [0.20, 0.05, 0.10, 0.15, 0.50],
  };
  let [wIntel, wCoding, wSpeed, wTput, wCost] = weights[task] || weights.general;

  // Reduce attribute weight based on user "Any/Unlimited" preferences
  if (speed === "any") {
    // If coding matters, shift speed weight there, else to intel
    if (wCoding > 0) wCoding += wSpeed;
    else wIntel += wSpeed;
    wSpeed = 0;

    // Throughput matters less if speed doesn't matter
    if (wCoding > 0) wCoding += wTput * 0.5;
    else wIntel += wTput * 0.5; 
    wTput *= 0.5;
  }
  if (budget === "unlimited") {
    if (wCoding > wIntel) wCoding += wCost;
    else wIntel += wCost;
    wCost = 0;
  }

  return models.map(m => {
    const blended = (m.inputCost + m.outputCost) / 2;
    // Core percentile scores (higher = better)
    const pIntel = pctRank(vals.intelligence, m.intelligence, true);
    const pCoding = pctRank(vals.coding, m.coding, true);
    const pSpeed = pctRank(vals.speed, m.speed, false); // lower TTFT = better
    const pTput = pctRank(vals.throughput, m.throughput, true);
    const pCost = pctRank(vals.cost, blended, false); // lower cost = better

    // Weighted base score
    let score = pIntel * wIntel + pCoding * wCoding + pSpeed * wSpeed + pTput * wTput + pCost * wCost;

    // Budget preference modifier (up to +/- 12 points)
    if (budget === "tight") {
      if (blended > 0 && blended < 0.5) score += 12;
      else if (blended > 0 && blended < 1) score += 6;
      else if (blended > 3) score -= 10;
    } else if (budget === "moderate") {
      if (blended >= 0.5 && blended <= 3) score += 8;
      else if (blended > 5) score -= 8;
    } else if (budget === "flexible") {
      if (blended >= 1 && blended <= 5) score += 6;
    }
    // "unlimited" = no budget adjustment

    // Speed preference modifier (up to +/- 10 points)
    if (speed === "fast") {
      if (m.speed > 0 && m.speed < 1) score += 10;
      else if (m.speed > 5) score -= 12;
    } else if (speed === "medium") {
      if (m.speed > 0 && m.speed < 3) score += 5;
      else if (m.speed > 10) score -= 8;
    }

    // Context preference modifier (up to +/- 10 points)
    if (context === "small" && m.context > 0 && m.context < 200000) score += 5;
    if (context === "medium" && m.context >= 200000 && m.context <= 500000) score += 8;
    if (context === "large") {
      if (m.context > 500000) score += 10;
      else if (m.context > 0 && m.context <= 128000) score -= 10;
    }

    return { ...m, score: Math.max(0, Math.min(100, Math.round(score))) };
  });
}

