  "deepseek-v3": "deepseek-v3-2",
};

// Normalize model IDs for matching AA benchmarks
function normalizeModelId(raw: string): string {
  if (!raw) return "";
  const re = new RegExp("[._\\s\\/]", "g");
  const s = raw.toLowerCase().replace(re, "-").replace(/-+/g, "-");
  return s.endsWith("-") ? s.slice(0, -1) : s;
}

// Multi-strategy AA matcher: tries several approaches to find a match
function findAaMatch(modelName: string, label: string, aaByNorm: Record<string, any>): any {
  const candidates: string[] = [];

  // Collect all candidate strings to try
  candidates.push(label);
  if (modelName && !modelName.startsWith("byok:")) candidates.push(modelName);

  // Strip provider prefix (e.g. "Aether_gpt-5-mini" -> "gpt-5-mini")
  if (label.includes("_")) {
    const afterProvider = label.split("_").slice(1).join("_");
    candidates.push(afterProvider);
    candidates.push(normalizeModelId(afterProvider));
  }

  // Try exact normalized match for each candidate
  for (const c of candidates) {
    const norm = normalizeModelId(c);
    if (norm && aaByNorm[norm]) return aaByNorm[norm];
  }

  // Try alias map
  for (const c of candidates) {
    const norm = normalizeModelId(c);
    if (MODEL_ALIASES[norm] && aaByNorm[MODEL_ALIASES[norm]]) return aaByNorm[MODEL_ALIASES[norm]];
  }

  // Try prefix matching: if normalized candidate starts with an AA key (or vice versa)
  for (const c of candidates) {
    const norm = normalizeModelId(c);
    if (!norm || norm.length < 4) continue;
    for (const aaKey of Object.keys(aaByNorm)) {
      if (aaKey.startsWith(norm) || norm.startsWith(aaKey)) return aaByNorm[aaKey];
    }
  }

  // Try substring matching for key model family names
  const families = ["opus", "sonnet", "haiku", "gpt-5", "gemini-3", "deepseek", "minimax", "kimi", "glm", "codex"];
  for (const c of candidates) {
    const lower = c.toLowerCase();
    for (const family of families) {
      if (!lower.includes(family)) continue;
      let bestKey = "";
      let bestLen = 0;
      for (const aaKey of Object.keys(aaByNorm)) {
        if (!aaKey.includes(family)) continue;
        const cNorm = normalizeModelId(lower);
        const cParts = new Set(cNorm.split("-").filter(Boolean));
        const aParts = new Set(aaKey.split("-").filter(Boolean));
        let overlap = 0;
        for (const p of cParts) { if (aParts.has(p)) overlap++; }
        if (overlap > bestLen) { bestLen = overlap; bestKey = aaKey; }
      }
      if (bestKey && bestLen >= 2) return aaByNorm[bestKey];
    }
  }

  return null;
}
