        speed: d.ttft || d.speed || 0,
        throughput: d.tokensPerSecond || d.tokens_per_second || 0,
        isYourModel: false, aa: d, _aaKey: id,
      };
    });

    // Process your Zo models - merge with AA data when available
    const matchedAaKeys = new Set<string>();
    const myEntries = myModels.map((m: any) => {
      const label = m.label || "";
      const modelName = m.modelName || "";
      const aaMatch = findAaMatch(modelName, label, aaByNorm);
      if (aaMatch?._aaKey) matchedAaKeys.add(aaMatch._aaKey);
      // Strip provider prefix from label for display name (e.g. "Aether_gpt-5-mini" -> "gpt-5-mini")
      const displayName = label.includes("_") ? label.split("_").slice(1).join("_") : label || modelName;
      const normId = normalizeModelId(displayName);
      const labelProvider = label.includes("_") ? label.split("_")[0] : null;

      let spd = aaMatch?.speed ?? aaMatch?.ttft ?? 0;
      // Override AA dataset outlier/error for Gemini 3.1 Pro Preview
      if (normId.includes("gemini-3-1-pro-preview") && spd > 30) spd = 1.1;

      // Include provider in ID to avoid key collisions between providers
      const providerPrefix = labelProvider ? labelProvider.toLowerCase() + "-" : "";
      const isByok = !!m.isByok;

      return {
        id: providerPrefix + (normId || modelName),
        rawId: modelName,
        name: displayName || modelName,
        provider: labelProvider || aaMatch?.creator || aaMatch?.provider || "Zo",
        origin: isByok ? "BYOK" : "Native",
        context: aaMatch?.context ?? aaMatch?.context_window ?? 0,
        inputCost: aaMatch?.inputCost ?? aaMatch?.input_cost ?? 0,
        outputCost: aaMatch?.outputCost ?? aaMatch?.output_cost ?? 0,
        intelligence: aaMatch?.intelligence ?? aaMatch?.mmlu_pro ?? 0,
        coding: aaMatch?.coding ?? aaMatch?.artificial_analysis_coding_index ?? 0,
        speed: spd,
        throughput: aaMatch?.throughput ?? aaMatch?.tokensPerSecond ?? aaMatch?.tokens_per_second ?? 0,
        isYourModel: true,
        aa: aaMatch,
      };
    });

    // Deduplicate: remove AA entries that were already matched to your models
    const unmatchedAaEntries = aaEntries.filter(m => !matchedAaKeys.has(m._aaKey));

    const all = [...myEntries, ...unmatchedAaEntries];
    // Apply show filter
    let filtered = all;
    if (showFilter === "yours") filtered = all.filter(m => m.isYourModel);
    else if (showFilter === "native") filtered = all.filter(m => m.origin === "Native");
    else if (showFilter === "byok") filtered = all.filter(m => m.origin === "BYOK");
    else if (showFilter === "other") filtered = all.filter(m => !m.isYourModel);
    // Apply global search
    if (filter) filtered = filtered.filter(m => m.name.toLowerCase().includes(filter.toLowerCase()) || m.id.toLowerCase().includes(filter.toLowerCase()));
    // Apply per-column filters
    for (const [col, val] of Object.entries(colFilters)) {
      if (!val) continue;
      const v = val.toLowerCase();
      filtered = filtered.filter(m => {
        const cell = (m as any)[col];
        if (cell == null) return false;
        return String(cell).toLowerCase().includes(v);
      });
    }
    return scoreModels(filtered, task, budget, speed, context)
      .sort((a,b) => { const av = (a as any)[sortCol] || 0, bv = (b as any)[sortCol] || 0; return sortDir === "desc" ? bv - av : av - bv; });
  }, [aaData, myModels, task, budget, speed, context, sortCol, sortDir, filter, showFilter, colFilters]);

  // Top pick is always the highest-scored model, regardless of current sort column
  const top = useMemo(() => {
    if (scored.length === 0) return null;
    return scored.reduce((best, m) => m.score > best.score ? m : best, scored[0]);
  }, [scored]);

  const bg = dark ? "bg-zinc-950" : "bg-zinc-50";
  const text = dark ? "text-white" : "text-zinc-900";
  const card = dark ? "bg-zinc-900 border-zinc-800" : "bg-white border-zinc-200 shadow-sm";
  const inputBg = dark ? "bg-zinc-800 border-zinc-700 text-white" : "bg-white border-zinc-300 text-zinc-900";
  const muted = dark ? "text-zinc-400" : "text-zinc-500";
  const faint = dark ? "text-zinc-500" : "text-zinc-400";
  const border = dark ? "border-zinc-800" : "border-zinc-200";
  const hdrBg = dark ? "bg-zinc-950/80 border-zinc-800/80" : "bg-white/90 border-zinc-200";
  const btn = dark ? "bg-zinc-800 hover:bg-zinc-700 text-zinc-300 border-zinc-700" : "bg-zinc-100 hover:bg-zinc-200 text-zinc-700 border-zinc-300";
  const active = dark ? "bg-blue-500/20 text-blue-400 border-blue-500/40" : "bg-blue-50 text-blue-700 border-blue-300";
  const rowHov = dark ? "hover:bg-zinc-800/40" : "hover:bg-zinc-50";

  if (loading) return <div className="min-h-screen bg-zinc-950 text-white flex items-center justify-center"><div className="animate-spin w-8 h-8 border-4 border-blue-500 border-t-transparent rounded-full"/></div>;

  return (
    <div className={"min-h-screen "+bg+" "+text+" transition-colors duration-200"}>
      {/* Header */}
      <div className={"border-b sticky top-0 z-40 "+hdrBg}>
        <div className="max-w-7xl mx-auto px-4 py-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-blue-500 to-purple-600 flex items-center justify-center">
              <Cpu className="w-5 h-5 text-white"/>
            </div>
            <div>
              <h1 className="text-xl font-bold">Model Advisor</h1>
              <p className={"text-xs "+faint}>{scored.length} models — AA benchmarks + your Zo models</p>
            </div>
          </div>
          <button onClick={()=>setDark(d=>!d)} className={"p-2 rounded-lg border transition-colors "+(dark?"bg-zinc-800 border-zinc-700 text-amber-400":"bg-white border-zinc-200 text-indigo-600")}>
            {dark ? <Sun className="w-4 h-4"/> : <Moon className="w-4 h-4"/>}
          </button>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 py-6">
        {/* Controls */}
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-4 mb-6">
          {/* Task */}
          <div className={"border rounded-xl p-4 "+card}>
            <label className={"text-sm font-semibold mb-3 block "+muted}><Target className="w-4 h-4 inline mr-1"/>Task</label>
            <div className="space-y-1">
              {TASKS.map(t => { const Icon=t.icon; return (
                <button key={t.id} onClick={()=>setTask(t.id)} className={"w-full flex items-center gap-2 px-3 py-2 rounded-lg text-sm transition-all "+(task===t.id?active:btn)}>
                  <Icon className="w-4 h-4"/>{t.label}
                </button>
              );})}
            </div>
          </div>
          {/* Budget */}
          <div className={"border rounded-xl p-4 "+card}>
            <label className={"text-sm font-semibold mb-3 block "+muted}><DollarSign className="w-4 h-4 inline mr-1"/>Budget</label>
            <div className="space-y-1">
              {BUDGETS.map(b => (
                <button key={b.id} onClick={()=>setBudget(b.id)} className={"w-full text-left px-3 py-2 rounded-lg text-sm transition-all "+(budget===b.id?active:btn)}>
                  <span>{b.label}</span> <span className={"text-xs "+faint}>{b.desc}</span>
                </button>
              ))}
            </div>
          </div>
          {/* Speed */}
          <div className={"border rounded-xl p-4 "+card}>
            <label className={"text-sm font-semibold mb-3 block "+muted}><Zap className="w-4 h-4 inline mr-1"/>Speed</label>
            <div className="space-y-1">
              {SPEEDS.map(s => (
                <button key={s.id} onClick={()=>setSpeed(s.id)} className={"w-full text-left px-3 py-2 rounded-lg text-sm transition-all "+(speed===s.id?active:btn)}>{s.label}</button>
              ))}
            </div>
          </div>
          {/* Context */}
          <div className={"border rounded-xl p-4 "+card}>
            <label className={"text-sm font-semibold mb-3 block "+muted}><BookOpen className="w-4 h-4 inline mr-1"/>Context</label>
            <div className="space-y-1">
              {CONTEXTS.map(c => (
                <button key={c.id} onClick={()=>setContext(c.id)} className={"w-full text-left px-3 py-2 rounded-lg text-sm transition-all "+(context===c.id?active:btn)}>{c.label}</button>
              ))}
            </div>
          </div>
        </div>

        {/* Token Inputs + Search */}
        <div className="flex flex-wrap gap-4 mb-6 items-end">
          <div>
            <label className={"text-xs mb-1 block "+muted}>Input tokens</label>
            <input type="number" value={intTokens} onChange={e=>setIntTokens(Number(e.target.value))} className={"w-28 px-3 py-2 rounded-lg border text-sm "+inputBg}/>
          </div>
          <div>
            <label className={"text-xs mb-1 block "+muted}>Output tokens</label>
            <input type="number" value={outTokens} onChange={e=>setOutTokens(Number(e.target.value))} className={"w-28 px-3 py-2 rounded-lg border text-sm "+inputBg}/>
          </div>
          <div>
            <label className={"text-xs mb-1 block "+muted}>Search models</label>
            <div className="relative">
              <Search className={"w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 "+muted}/>
              <input type="text" value={filter} onChange={e=>setFilter(e.target.value)} placeholder="Filter..." className={"pl-9 pr-4 py-2 rounded-lg border text-sm w-48 "+inputBg}/>
              {filter && <button onClick={()=>setFilter("")} className={"absolute right-2 top-1/2 -translate-y-1/2 "+muted}><X className="w-3 h-3"/></button>}
            </div>
          </div>
          <div>
            <label className={"text-xs mb-1 block "+muted}>Show</label>
            <div className="flex gap-1.5 flex-wrap">
              <button onClick={()=>setShowFilter("all")} className={"px-3 py-2 rounded-lg text-sm border transition-all "+(showFilter==="all"?active:btn)}>All</button>
              <button onClick={()=>setShowFilter("yours")} className={"px-3 py-2 rounded-lg text-sm border transition-all "+(showFilter==="yours"?active:btn)}><Bot className="w-3 h-3 inline mr-1"/>Yours</button>
              <button onClick={()=>setShowFilter("native")} className={"px-3 py-2 rounded-lg text-sm border transition-all "+(showFilter==="native"?(dark?"bg-green-500/20 text-green-400 border border-green-500/30":"bg-green-50 text-green-700 border-green-300"):btn)}><Cpu className="w-3 h-3 inline mr-1"/>Native</button>
              <button onClick={()=>setShowFilter("byok")} className={"px-3 py-2 rounded-lg text-sm border transition-all "+(showFilter==="byok"?(dark?"bg-purple-500/20 text-purple-400 border border-purple-500/30":"bg-purple-50 text-purple-700 border-purple-300"):btn)}>BYOK</button>
              <button onClick={()=>setShowFilter("other")} className={"px-3 py-2 rounded-lg text-sm border transition-all "+(showFilter==="other"?active:btn)}>Other</button>
            </div>
          </div>
        </div>

        {/* Recommendation */}
        {top && (
          <div className={"border rounded-xl p-6 mb-6 "+card}>
            <div className="flex items-center gap-3 mb-4">
              <Trophy className="w-6 h-6 text-amber-400"/>
              <h2 className="text-lg font-bold">Top Pick</h2>
              {top.isYourModel && <span className="px-2 py-0.5 rounded-full text-xs bg-blue-500/20 text-blue-400 border border-blue-500/30">Your Model</span>}
              {top.origin !== "AA" && <span className={"px-2 py-0.5 rounded-full text-xs "+(top.origin==="BYOK"?"bg-purple-500/20 text-purple-400 border border-purple-500/30":"bg-green-500/20 text-green-400 border border-green-500/30")}>{top.origin}</span>}
            </div>
            <div className="flex flex-col md:flex-row md:items-center gap-4 mb-4">
              <div className="flex-1">
                <h3 className="text-2xl font-bold mb-1">{top.name}</h3>
                <p className={"text-sm "+muted}>{top.provider} &middot; {fmtK(top.context)} context &middot; Intelligence {top.intelligence.toFixed(1)}</p>
              </div>
              <div className="flex items-center gap-6">
                <div className="text-center">
                  <div className="text-3xl font-bold text-blue-400">{top.score}</div>
                  <div className={"text-xs "+muted}>Match score</div>
                </div>
                <div className="text-center">
                  <div className="text-2xl font-bold font-mono text-emerald-400">${((top.inputCost/1e6*intTokens + top.outputCost/1e6*outTokens)).toFixed(4)}</div>
                  <div className={"text-xs "+muted}>est. per request</div>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Table */}
        <div className={"border rounded-xl overflow-hidden "+card}>
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead>
                <tr className={dark?"bg-zinc-900/80 border-b border-zinc-800":"bg-zinc-50 border-b border-zinc-200"}>
                  <th className="px-3 py-3 text-left text-xs font-semibold uppercase tracking-wider cursor-pointer hover:bg-zinc-700/30 select-none" onClick={()=>toggleSort("name")}>Model {sortCol==="name"?(sortDir==="desc"?String.fromCodePoint(0x25BC):String.fromCodePoint(0x25B2)):""}</th>
                  <th className="px-3 py-3 text-left text-xs font-semibold uppercase tracking-wider cursor-pointer hover:bg-zinc-700/30 select-none" onClick={()=>toggleSort("score")}>Score {sortCol==="score"?(sortDir==="desc"?String.fromCodePoint(0x25BC):String.fromCodePoint(0x25B2)):""}</th>
                  <th className="px-3 py-3 text-left text-xs font-semibold uppercase tracking-wider cursor-pointer hover:bg-zinc-700/30 select-none" onClick={()=>toggleSort("intelligence")}>Intelligence {sortCol==="intelligence"?(sortDir==="desc"?String.fromCodePoint(0x25BC):String.fromCodePoint(0x25B2)):""}</th>
                  <th className="px-3 py-3 text-left text-xs font-semibold uppercase tracking-wider cursor-pointer hover:bg-zinc-700/30 select-none" onClick={()=>toggleSort("coding")}>Coding {sortCol==="coding"?(sortDir==="desc"?String.fromCodePoint(0x25BC):String.fromCodePoint(0x25B2)):""}</th>
                  <th className="px-3 py-3 text-left text-xs font-semibold uppercase tracking-wider cursor-pointer hover:bg-zinc-700/30 select-none" onClick={()=>toggleSort("speed")}>Speed {sortCol==="speed"?(sortDir==="desc"?String.fromCodePoint(0x25BC):String.fromCodePoint(0x25B2)):""}</th>
                  <th className="px-3 py-3 text-left text-xs font-semibold uppercase tracking-wider cursor-pointer hover:bg-zinc-700/30 select-none" onClick={()=>toggleSort("throughput")}>Throughput {sortCol==="throughput"?(sortDir==="desc"?String.fromCodePoint(0x25BC):String.fromCodePoint(0x25B2)):""}</th>
                  <th className="px-3 py-3 text-left text-xs font-semibold uppercase tracking-wider cursor-pointer hover:bg-zinc-700/30 select-none" onClick={()=>toggleSort("context")}>Context {sortCol==="context"?(sortDir==="desc"?String.fromCodePoint(0x25BC):String.fromCodePoint(0x25B2)):""}</th>
                  <th className="px-3 py-3 text-left text-xs font-semibold uppercase tracking-wider cursor-pointer hover:bg-zinc-700/30 select-none" onClick={()=>toggleSort("inputCost")}>Input {sortCol==="inputCost"?(sortDir==="desc"?String.fromCodePoint(0x25BC):String.fromCodePoint(0x25B2)):""}</th>
                  <th className="px-3 py-3 text-left text-xs font-semibold uppercase tracking-wider cursor-pointer hover:bg-zinc-700/30 select-none" onClick={()=>toggleSort("outputCost")}>Output {sortCol==="outputCost"?(sortDir==="desc"?String.fromCodePoint(0x25BC):String.fromCodePoint(0x25B2)):""}</th>
                  <th className="px-3 py-3 text-left text-xs font-semibold uppercase tracking-wider">Provider</th>
                </tr>
              </thead>
              <tbody>
                <tr className={dark?"bg-zinc-900/40 border-b border-zinc-800":"bg-zinc-50/50 border-b border-zinc-200"}>
                  <td className="px-2 py-1.5"><input type="text" placeholder="Filter..." value={colFilters.name||""} onChange={e=>setColFilters(f=>({...f,name:e.target.value}))} className={"w-full px-2 py-1 rounded text-xs border "+inputBg}/></td>
                  <td className="px-2 py-1.5"></td>
                  <td className="px-2 py-1.5"><input type="text" placeholder="Min..." value={colFilters.intelligence||""} onChange={e=>setColFilters(f=>({...f,intelligence:e.target.value}))} className={"w-16 px-2 py-1 rounded text-xs border "+inputBg}/></td>
                  <td className="px-2 py-1.5"><input type="text" placeholder="Min..." value={colFilters.coding||""} onChange={e=>setColFilters(f=>({...f,coding:e.target.value}))} className={"w-16 px-2 py-1 rounded text-xs border "+inputBg}/></td>
                  <td className="px-2 py-1.5"><input type="text" placeholder="Filter..." value={colFilters.speed||""} onChange={e=>setColFilters(f=>({...f,speed:e.target.value}))} className={"w-16 px-2 py-1 rounded text-xs border "+inputBg}/></td>
                  <td className="px-2 py-1.5"><input type="text" placeholder="Filter..." value={colFilters.throughput||""} onChange={e=>setColFilters(f=>({...f,throughput:e.target.value}))} className={"w-16 px-2 py-1 rounded text-xs border "+inputBg}/></td>
                  <td className="px-2 py-1.5"><input type="text" placeholder="Filter..." value={colFilters.context||""} onChange={e=>setColFilters(f=>({...f,context:e.target.value}))} className={"w-16 px-2 py-1 rounded text-xs border "+inputBg}/></td>
                  <td className="px-2 py-1.5"><input type="text" placeholder="Filter..." value={colFilters.inputCost||""} onChange={e=>setColFilters(f=>({...f,inputCost:e.target.value}))} className={"w-16 px-2 py-1 rounded text-xs border "+inputBg}/></td>
                  <td className="px-2 py-1.5"><input type="text" placeholder="Filter..." value={colFilters.outputCost||""} onChange={e=>setColFilters(f=>({...f,outputCost:e.target.value}))} className={"w-16 px-2 py-1 rounded text-xs border "+inputBg}/></td>
                  <td className="px-2 py-1.5"><input type="text" placeholder="Filter..." value={colFilters.provider||""} onChange={e=>setColFilters(f=>({...f,provider:e.target.value}))} className={"w-16 px-2 py-1 rounded text-xs border "+inputBg}/></td>
                </tr>
                {scored.slice(0, showFilter !== "all" ? 9999 : 200).map((m, i)=>{
                  const rowCls = "border-b "+border+(m.isYourModel?(dark?"bg-blue-500/5":"bg-blue-50/50"):(dark?"hover:bg-zinc-800/30":"hover:bg-zinc-50"));
                  return (
                  <tr key={m.id + "-" + i} className={rowCls}>
                    <td className="px-3 py-3"><div className={"font-medium text-sm "+(m.isYourModel?"text-blue-400":"")}>{m.name}</div>{m.origin!=="AA"&&<span className={"ml-1 text-xs px-1.5 py-0.5 rounded "+(m.origin==="BYOK"?"bg-purple-500/20 text-purple-400":"bg-green-500/20 text-green-400")}>{m.origin}</span>}</td>
                    <td className="px-3 py-3"><span className={"font-mono font-bold "+(m.score>=80?"text-emerald-400":m.score>=60?"text-blue-400":"text-zinc-400")}>{m.score}</span></td>
                    <td className="px-3 py-3 text-sm font-mono">{m.intelligence>0?m.intelligence.toFixed(1):"--"}</td>
                    <td className="px-3 py-3 text-sm font-mono">{m.coding>0?m.coding.toFixed(1):"--"}</td>
                    <td className="px-3 py-3 text-sm font-mono">{m.speed>0?m.speed.toFixed(2)+"s":"--"}</td>
                    <td className="px-3 py-3 text-sm font-mono">{m.throughput>0?m.throughput.toFixed(0)+" t/s":"--"}</td>
                    <td className="px-3 py-3 text-sm font-mono">{m.context>0?fmtK(m.context):"--"}</td>
                    <td className="px-3 py-3 text-sm font-mono text-emerald-400">{m.inputCost>0?fmt(m.inputCost):"--"}</td>
                    <td className="px-3 py-3 text-sm font-mono text-emerald-400">{m.outputCost>0?fmt(m.outputCost):"--"}</td>
                    <td className="px-3 py-3 text-xs text-zinc-500">{m.provider}</td>
                  </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
          {showFilter==="all"&&scored.length>200&&<div className={"px-4 py-3 text-sm text-center "+muted}>Showing 200 of {scored.length} models</div>}
        </div>
        <div className={"text-center py-6 text-xs "+faint+" border-t "+border+" mt-6"}>Benchmarks from Artificial Analysis. Your models shown as Native/BYOK. Intelligence = MMLU-Pro.</div>
      </div>
    </div>
  );
