        >
          {navOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
        </button>
      </div>
    </>
  );
}

export default function RetailReceiptTracker() {
  const [passcode, setPasscode] = useState('');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [authError, setAuthError] = useState('');
  const [receipts, setReceipts] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [processing, setProcessing] = useState(false);
  const [uploadStatus, setUploadStatus] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [search, setSearch] = useState('');
  const [sortConfig, setSortConfig] = useState({ key: 'date', direction: 'desc' });
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [zoom, setZoom] = useState(1);
  const [rotation, setRotation] = useState(0);
  const [fitToScreen, setFitToScreen] = useState(true);

  const pendingCount = useMemo(() => receipts.filter(r => r.status === 'pending' || (!r.items || r.items.length === 0)).length, [receipts]);
  const hasItems = useMemo(() => receipts.some(r => r.items && r.items.length > 0), [receipts]);

  useEffect(() => {
    const saved = localStorage.getItem('receipt_passcode');
    if (saved) {
      setPasscode(saved);
      fetchReceipts(saved);
    }
  }, []);

  useEffect(() => {
    if (isAuthenticated && pendingCount > 0 && !processing) {
      processPending();
    }
  }, [isAuthenticated, pendingCount]);

  const fetchReceipts = async (currentPasscode: string) => {
    try {
      setLoading(true);
      const res = await fetch('/api/receipts', {
        headers: { 'X-Passcode': currentPasscode }
      });
      if (res.status === 401) {
        setIsAuthenticated(false);
        if (passcode) setAuthError('Invalid passcode.');
        localStorage.removeItem('receipt_passcode');
        return;
      }
      const data = await res.json();
      if (Array.isArray(data)) {
        setReceipts(data);
        setIsAuthenticated(true);
        setAuthError('');
        localStorage.setItem('receipt_passcode', currentPasscode);
      }
    } catch (e) {
      setAuthError('Failed to connect to the server.');
    } finally {
      setLoading(false);
    }
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (!passcode) return;
    fetchReceipts(passcode);
  };

  const processPending = async () => {
    if (processing) return;
    setProcessing(true);
    try {
      const res = await fetch('/api/receipts?action=process', {
        method: 'POST',
        headers: { 'X-Passcode': passcode }
      });
      const data = await res.json();
      if (data.success) {
        await fetchReceipts(passcode);
      }
    } catch (e) {
      console.error('Processing error:', e);
    } finally {
      setProcessing(false);
    }
  };

  const reprocessAll = async () => {
    if (processing) return;
    setProcessing(true);
    setUploadStatus('Reprocessing all receipts...');
    try {
      const res = await fetch('/api/receipts?action=reprocess', {
        method: 'POST',
        headers: { 'X-Passcode': passcode }
      });
      const data = await res.json();
      if (data.success) {
        await fetchReceipts(passcode);
        setUploadStatus(`Reprocessed ${data.processed} receipts`);
        setTimeout(() => setUploadStatus(''), 3000);
      }
    } catch (e) {
      setUploadStatus('Reprocess failed');
    } finally {
      setProcessing(false);
    }
  };

  const handleUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;
    setUploading(true);
    setUploadStatus(`Uploading ${files.length} receipt${files.length > 1 ? 's' : ''}...`);
    const formData = new FormData();
    for (let i = 0; i < files.length; i++) {
      formData.append('images', files[i]);
    }
    try {
      const res = await fetch('/api/receipts?action=upload', {
        method: 'POST',
        headers: { 'X-Passcode': passcode },
        body: formData,
      });
      if (res.status === 401) {
        alert('Session expired. Please log in again.');
        setIsAuthenticated(false);
        return;
      }
      const data = await res.json();
      if (data.success) {
        setUploadStatus(`Uploaded ${data.uploaded.length} images. Processing in background...`);
        await fetchReceipts(passcode);
      } else {
        setUploadStatus('Upload failed: ' + data.error);
      }
    } catch (e) {
      setUploadStatus('Error uploading files');
    } finally {
      setUploading(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const allItems = useMemo(() => {
    const items: any[] = [];
    receipts.forEach(r => {
      const rDate = r.receipt_date || r.date_uploaded;
      if (r.items && r.items.length > 0) {
        r.items.forEach((item: any, idx: number) => {
          items.push({
            id: `${r.id}-${idx}`,
            date: rDate,
            store_name: r.store_name || 'Unknown',
            item_code: item.item_code || '',
            description: item.description || '',
            price: item.price || 0,
            image_url: r.image_url,
            receipt_id: r.id
          });
        });
      }
    });
    return items;
  }, [receipts]);

  const filteredAndSortedItems = useMemo(() => {
    let result = [...allItems];
    if (search.trim()) {
      const lowerSearch = search.toLowerCase();
      result = result.filter(item => 
        item.description.toLowerCase().includes(lowerSearch) ||
        String(item.item_code).toLowerCase().includes(lowerSearch) ||
        item.store_name.toLowerCase().includes(lowerSearch) ||
        new Date(item.date).toLocaleDateString().includes(lowerSearch)
      );
    }
    result.sort((a, b) => {
      let aVal = a[sortConfig.key];
      let bVal = b[sortConfig.key];
      if (sortConfig.key === 'date') {
        aVal = new Date(aVal || 0).getTime();
        bVal = new Date(bVal || 0).getTime();
      } else if (sortConfig.key === 'price') {
        aVal = Number(aVal || 0);
        bVal = Number(bVal || 0);
      } else {
        aVal = String(aVal || '').toLowerCase();
        bVal = String(bVal || '').toLowerCase();
      }
      if (aVal < bVal) return sortConfig.direction === 'asc' ? -1 : 1;
      if (aVal > bVal) return sortConfig.direction === 'asc' ? 1 : -1;
      return 0;
    });
    return result;
  }, [allItems, search, sortConfig]);

  const handleSort = (key: string) => {
    setSortConfig(prev => ({
      key,
      direction: prev.key === key && prev.direction === 'asc' ? 'desc' : 'asc'
    }));
  };

  const SortIcon = ({ columnKey }: { columnKey: string }) => {
    if (sortConfig.key !== columnKey) return <ArrowUpDown className='w-4 h-4 text-zinc-600 opacity-50' />;
    return sortConfig.direction === 'asc' ? <ArrowUp className='w-4 h-4 text-cyan-400' /> : <ArrowDown className='w-4 h-4 text-cyan-400' />;
  };

  const handleZoomIn = () => setZoom(z => Math.min(z * 1.25, 5));
  const handleZoomOut = () => setZoom(z => Math.max(z / 1.25, 0.25));
  const handleRotate = () => setRotation(r => (r + 90) % 360);
  const handleReset = () => { setZoom(1); setRotation(0); setFitToScreen(true); };
  const handleToggleFit = () => { setFitToScreen(f => !f); setZoom(1); };
  const closeModal = () => { setSelectedImage(null); handleReset(); };

  if (!isAuthenticated) {
    return (
      <div className='min-h-screen flex items-center justify-center p-4 font-body relative text-white' style={{ background: COLORS.bg }}>
        {/* Decorative Grid */}
        <div className="absolute inset-0 bg-grid pointer-events-none" />
        <div className="absolute pointer-events-none" style={{ top: -200, left: "30%", width: 500, height: 500, background: COLORS.cyan, borderRadius: "50%", opacity: 0.04, filter: "blur(150px)" }} />

        <form onSubmit={handleLogin} className='relative z-10 p-8 rounded-2xl shadow-xl w-full max-w-sm space-y-6' style={{ background: COLORS.card, border: `1px solid ${COLORS.border}` }}>
          <div className='flex justify-center'>
            <div className='p-4 rounded-full shadow-inner' style={{ background: `${COLORS.cyan}15` }}>
              <Lock className='w-8 h-8' style={{ color: COLORS.cyan }} />
            </div>
          </div>
          <div>
            <h2 className='text-2xl font-bold font-heading text-center text-white'>Secure Access</h2>
            <p className='text-center text-sm mt-2' style={{ color: COLORS.muted }}>Enter the passcode to view and manage receipts.</p>
          </div>
          {authError && <p className='text-sm text-center p-3 rounded-lg border' style={{ color: "#ef4444", background: "rgba(239, 68, 68, 0.1)", borderColor: "rgba(239, 68, 68, 0.2)" }}>{authError}</p>}
          <div className='space-y-4'>
            <input type='password' value={passcode} onChange={(e) => setPasscode(e.target.value)} 
              className='w-full px-4 py-3 rounded-xl outline-none transition-all text-center text-lg tracking-widest' 
