            <button type='submit' disabled={loading || !passcode} 
              className='w-full py-3 bg-gradient-to-r from-cyan-500 to-indigo-600 hover:from-cyan-400 hover:to-indigo-500 text-white rounded-xl font-semibold shadow-md disabled:opacity-50 disabled:cursor-not-allowed flex justify-center items-center transition-all'>
              {loading ? <Loader2 className='w-5 h-5 animate-spin' /> : 'Unlock'}
            </button>
          </div>
        </form>
      </div>
    );
  }

  return (
    <div className='min-h-screen relative text-white font-body pb-20' style={{ background: COLORS.bg }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;600;700&family=Inter:wght@400;500;600&family=JetBrains+Mono:wght@400;500&display=swap');
        * { box-sizing: border-box; }
