import { Copy, Check, Lock, Sparkles, Globe, Clock3, Shield } from "lucide-react";
import { ArrowLeft, Check, Copy, Lock, Menu, Shield, Sparkles, X } from "lucide-react";

const COLORS = {
  bg: "#0a0a0f",
  card: "#0f1117",
  cardHover: "#141420",
  cyan: "#06b6d4",
