              </button>
            ))}
          </div>
        )}
      </div>

      {/* Detail Modal */}
      {selectedSkill && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm p-4" onClick={() => setSelectedSkill(null)}>
