import { useState, useEffect, useCallback } from "react";
import { Lock, Loader2 } from "lucide-react";

const STORAGE_KEY = "sblend-game-state";
const HISTORY_KEY = "sblend-game-history";
const AUTH_KEY = "sblend-auth";

interface WordDef {
  word: string;
  emoji: string;
  first: string[][];
  second: string[][];
}

const W: WordDef[] = [
  { word: "smell", emoji: "🌸", first: [["smell","flowers"],["smell","cookies"],["smell","roses"],["smell","dinner"],["smell","good"]], second: [["good","smell"],["nice","smell"],["sweet","smell"],["bad","smell"],["funny","smell"]] },
  { word: "sneeze", emoji: "🤧", first: [["sneeze","loud"],["sneeze","hard"],["sneeze","again"],["sneeze","big"],["sneeze","lots"]], second: [["big","sneeze"],["loud","sneeze"],["funny","sneeze"],["huge","sneeze"],["quick","sneeze"]] },
  { word: "swing", emoji: "🎠", first: [["swing","high"],["swing","fast"],["swing","low"],["swing","hard"],["swing","far"]], second: [["tree","swing"],["baby","swing"],["tire","swing"],["big","swing"],["fun","swing"]] },
  { word: "small", emoji: "🐜", first: [["small","dog"],["small","cat"],["small","ball"],["small","bug"],["small","fish"]], second: [["very","small"],["super","small"],["too","small"],["so","small"],["really","small"]] },
  { word: "stop", emoji: "🛑", first: [["stop","sign"],["stop","light"],["stop","running"],["stop","here"],["stop","now"]], second: [["bus","stop"],["full","stop"],["pit","stop"],["quick","stop"],["please","stop"]] },
  { word: "spoon", emoji: "🥄", first: [["spoon","feed"],["spoon","stir"],["spoon","scoop"],["spoon","mix"],["spoon","tap"]], second: [["big","spoon"],["little","spoon"],["silver","spoon"],["wooden","spoon"],["soup","spoon"]] },
  { word: "swim", emoji: "🏊", first: [["swim","fast"],["swim","far"],["swim","deep"],["swim","here"],["swim","now"]], second: [["morning","swim"],["fun","swim"],["good","swim"],["long","swim"],["quick","swim"]] },
  { word: "star", emoji: "⭐", first: [["star","bright"],["star","light"],["star","fish"],["star","shine"],["star","glow"]], second: [["gold","star"],["big","star"],["bright","star"],["rock","star"],["red","star"]] },
  { word: "smile", emoji: "😊", first: [["smile","big"],["smile","wide"],["smile","bright"],["smile","now"],["smile","lots"]], second: [["happy","smile"],["big","smile"],["warm","smile"],["nice","smile"],["sweet","smile"]] },
  { word: "snack", emoji: "🍪", first: [["snack","time"],["snack","box"],["snack","bar"],["snack","mix"],["snack","bag"]], second: [["yummy","snack"],["fruit","snack"],["quick","snack"],["good","snack"],["fun","snack"]] },
  { word: "snow", emoji: "❄️", first: [["snow","ball"],["snow","man"],["snow","flake"],["snow","fort"],["snow","fall"]], second: [["white","snow"],["cold","snow"],["deep","snow"],["fresh","snow"],["soft","snow"]] },
  { word: "space", emoji: "🚀", first: [["space","ship"],["space","suit"],["space","walk"],["space","man"],["space","rock"]], second: [["outer","space"],["big","space"],["deep","space"],["open","space"],["dark","space"]] },
];

function today() { return new Date().toLocaleDateString("en-CA"); }
function nowTime() { return new Date().toLocaleTimeString("en-CA", { hour12: false }); }
function pick<T>(arr: T[], exclude?: T[]): T {
  const pool = exclude ? arr.filter(a => !exclude.includes(a)) : arr;
  return pool[Math.floor(Math.random() * pool.length)] || arr[0];
}

interface Progress { [word: string]: { count: number; usedFirst: number[]; usedSecond: number[] } }
interface Attempt {
  id: string; word: string; phrase: string; position: "first" | "second";
  round: number; tries: number; time: string; date: string; timestamp?: number;
}
interface CardOptions {
  a: string[];
  b: string[];
  flipped: boolean;
}
interface CustomDraft {
  value: string;
  side: "first" | "second";
}

function getPasscode(): string { return localStorage.getItem(AUTH_KEY) || ""; }

async function syncToServer(attempt: Attempt) {
  const pc = getPasscode();
  if (!pc) return;
  try {
    await fetch("/api/speech-game-data", {
      method: "POST",
      headers: { "Content-Type": "application/json", "X-Passcode": pc },
      body: JSON.stringify({ type: "attempt", ...attempt }),
    });
  } catch {}
}

async function loadFromServer(pc: string): Promise<{ attempts: Attempt[]; stickers: Record<string, any> } | null> {
  try {
    const res = await fetch("/api/speech-game-data", {
      headers: { "X-Passcode": pc, "Accept": "application/json" },
    });
    if (!res.ok) return null;
    return await res.json();
  } catch { return null; }
}

function rebuildProgressFromAttempts(attempts: Attempt[]): Progress {
  const progress: Progress = {};
  W.forEach(w => { progress[w.word] = { count: 0, usedFirst: [], usedSecond: [] }; });
  const todayStr = today();
  const todayAttempts = attempts.filter(a => a.date === todayStr);
  for (const a of todayAttempts) {
    const prog = progress[a.word];
    if (!prog || prog.count >= 2) continue;
    prog.count = Math.min(a.round, 2);
  }
  return progress;
}

function mergeHistory(local: Attempt[], server: Attempt[]): Attempt[] {
  const seen = new Set(local.map(a => a.id));
  const merged = [...local];
  for (const a of server) {
    if (!seen.has(a.id)) { merged.push(a); seen.add(a.id); }
  }
  merged.sort((a, b) => (a.timestamp || 0) - (b.timestamp || 0));
  return merged;
}

function loadProgress(): { date: string; progress: Progress } {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) {
      const d = JSON.parse(raw);
      if (d.date === today()) return d;
    }
  } catch {}
  const progress: Progress = {};
  W.forEach(w => { progress[w.word] = { count: 0, usedFirst: [], usedSecond: [] }; });
  return { date: today(), progress };
}

function saveProgress(p: { date: string; progress: Progress }) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(p));
}

function loadHistory(): Attempt[] {
  try { return JSON.parse(localStorage.getItem(HISTORY_KEY) || "[]"); } catch { return []; }
}

function saveHistory(h: Attempt[]) {
  localStorage.setItem(HISTORY_KEY, JSON.stringify(h));
}

function Confetti() {
  const colors = ["#f43f5e","#8b5cf6","#3b82f6","#10b981","#f59e0b","#ec4899"];
  return (
    <div className="fixed inset-0 pointer-events-none z-50 overflow-hidden">
      {Array.from({ length: 40 }).map((_, i) => {
        const left = Math.random() * 100;
        const delay = Math.random() * 2;
        const dur = 2 + Math.random() * 2;
        const color = colors[i % colors.length];
        const size = 8 + Math.random() * 12;
        return (
          <div key={i} style={{
            position: "absolute", left: `${left}%`, top: -20,
            width: size, height: size, borderRadius: Math.random() > 0.5 ? "50%" : "2px",
            backgroundColor: color, opacity: 0.9,
            animation: `confettiFall ${dur}s ${delay}s ease-in forwards`,
          }} />
        );
      })}
      <style>{`
        @keyframes confettiFall {
          0% { transform: translateY(0) rotate(0deg); opacity: 1; }
          100% { transform: translateY(100vh) rotate(720deg); opacity: 0; }
        }
      `}</style>
    </div>
  );
}

export default function SpeechGame() {
  const [isAuth, setIsAuth] = useState(false);
  const [passcode, setPasscode] = useState("");
  const [authLoading, setAuthLoading] = useState(true);
  const [authError, setAuthError] = useState("");

  const [serverLoaded, setServerLoaded] = useState(false);
  const [state, setState] = useState(loadProgress);
  const [history, setHistory] = useState<Attempt[]>(loadHistory);
  const [active, setActive] = useState<number | null>(null);
  const [options, setOptions] = useState<CardOptions | null>(null);
  const [chosen, setChosen] = useState<string | null>(null);
  const [chosenPosition, setChosenPosition] = useState<"first" | "second">("first");
  const [showConfetti, setShowConfetti] = useState(false);
  const [justCompleted, setJustCompleted] = useState<string | null>(null);
  const [showHistory, setShowHistory] = useState(false);
  const [currentTries, setCurrentTries] = useState(0);
  const [customMode, setCustomMode] = useState<Record<string, boolean>>({});
  const [customDraft, setCustomDraft] = useState<CustomDraft>({ value: "", side: "first" });

  const allDone = Object.values(state.progress).every(p => p.count >= 2);

  useEffect(() => {
    if (!document.querySelector('link[rel="manifest"]')) {
      const link = document.createElement("link");
      link.rel = "manifest"; link.href = "/speech-game-manifest.json"; document.head.appendChild(link);
    }
    if (!document.querySelector('meta[name="apple-mobile-web-app-capable"]')) {
      const m1 = document.createElement("meta"); m1.name = "apple-mobile-web-app-capable"; m1.content = "yes"; document.head.appendChild(m1);
      const m2 = document.createElement("meta"); m2.name = "apple-mobile-web-app-status-bar-style"; m2.content = "black-translucent"; document.head.appendChild(m2);
      const m3 = document.createElement("meta"); m3.name = "theme-color"; m3.content = "#7c3aed"; document.head.appendChild(m3);
      const link = document.createElement("link"); link.rel = "apple-touch-icon"; link.href = "/icons/speech-game-180.png"; document.head.appendChild(link);
    }
    if ("serviceWorker" in navigator) {
      navigator.serviceWorker.register("/speech-game-sw.js", { scope: "/" }).catch(() => {});
    }
  }, []);

  useEffect(() => {
    const saved = localStorage.getItem(AUTH_KEY);
    if (saved) {
      fetch("/api/speech-game-auth", { headers: { "X-Passcode": saved } })
        .then(async r => {
          if (r.ok) {
            setIsAuth(true); setPasscode(saved);
            const serverData = await loadFromServer(saved);
            if (serverData?.attempts) {
              const merged = mergeHistory(loadHistory(), serverData.attempts);
              setHistory(merged);
              saveHistory(merged);
              const rebuilt = rebuildProgressFromAttempts(merged);
              const local = loadProgress();
              if (local.date === today()) {
                // Use whichever has more progress per word
                for (const w of W) {
                  if (rebuilt[w.word].count > local.progress[w.word].count) {
                    local.progress[w.word].count = rebuilt[w.word].count;
                  }
                }
                setState(local);
              } else {
                setState({ date: today(), progress: rebuilt });
              }
              setServerLoaded(true);
            }
          }
          else localStorage.removeItem(AUTH_KEY);
          setAuthLoading(false);
        })
        .catch(() => setAuthLoading(false));
    } else setAuthLoading(false);
  }, []);

  useEffect(() => { saveProgress(state); }, [state]);
  useEffect(() => { saveHistory(history); }, [history]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!passcode) return;
    setAuthLoading(true); setAuthError("");
    try {
      const res = await fetch("/api/speech-game-auth", { headers: { "X-Passcode": passcode } });
      if (res.ok) {
        localStorage.setItem(AUTH_KEY, passcode); setIsAuth(true);
        const serverData = await loadFromServer(passcode);
        if (serverData?.attempts) {
          const merged = mergeHistory(loadHistory(), serverData.attempts);
          setHistory(merged);
          saveHistory(merged);
          const rebuilt = rebuildProgressFromAttempts(merged);
          setState({ date: today(), progress: rebuilt });
          setServerLoaded(true);
        }
      }
      else setAuthError("Wrong passcode");
    } catch { setAuthError("Connection error"); }
    setAuthLoading(false);
  };

  const openCard = useCallback((idx: number) => {
    const wd = W[idx];
    const prog = state.progress[wd.word];
    if (prog.count >= 2) return;
    const fi = pick([0,1,2,3,4], prog.usedFirst);
    const si = pick([0,1,2,3,4], prog.usedSecond);
    const a = wd.first[fi];
    const b = wd.second[si];
    const flipped = Math.random() > 0.5;
    setActive(idx);
    setOptions({ a, b, flipped });
    setChosen(null);
    setCurrentTries(0);
    setCustomDraft({ value: "", side: "first" });
  }, [state]);

  const closeCard = () => {
    setActive(null);
    setOptions(null);
    setChosen(null);
    setCurrentTries(0);
    setCustomDraft({ value: "", side: "first" });
  };

  const choosePhrase = (pair: string[], position: "first" | "second") => {
    setChosen(pair.join(" "));
    setChosenPosition(position);
  };

  const submitCustomPhrase = () => {
    if (active === null) return;
    const wd = W[active];
    const custom = customDraft.value.trim();
    if (!custom) return;
    const phrase = customDraft.side === "first" ? `${custom} ${wd.word}` : `${wd.word} ${custom}`;
    setChosen(phrase);
    setChosenPosition(customDraft.side === "first" ? "first" : "second");
  };

  const markCorrect = () => {
    if (active === null || !options) return;
    const wd = W[active];
    const prog = { ...state.progress[wd.word] };
    const round = prog.count + 1;
    const fi = wd.first.indexOf(options.a);
    const si = wd.second.indexOf(options.b);
    if (fi >= 0 && !prog.usedFirst.includes(fi)) prog.usedFirst = [...prog.usedFirst, fi];
    if (si >= 0 && !prog.usedSecond.includes(si)) prog.usedSecond = [...prog.usedSecond, si];
    prog.count = round;
    const newProgress = { ...state.progress, [wd.word]: prog };
    setState({ ...state, progress: newProgress });

    const attempt: Attempt = {
      id: `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      word: wd.word, phrase: chosen || "", position: chosenPosition,
      round, tries: currentTries + 1, time: nowTime(), date: today(),
      timestamp: Date.now(),
    };
    setHistory(prev => [...prev, attempt]);
    syncToServer(attempt);

    if (round >= 2) {
      setJustCompleted(wd.word);
      setTimeout(() => setJustCompleted(null), 1500);
    }
    const done = Object.values(newProgress).every(p => p.count >= 2);
    if (done) {
      setShowConfetti(true);
      setTimeout(() => setShowConfetti(false), 5000);
    }
    closeCard();
  };

  const resetGame = () => {
    const progress: Progress = {};
    W.forEach(w => { progress[w.word] = { count: 0, usedFirst: [], usedSecond: [] }; });
    setState({ date: today(), progress });
  };

  const todayAttempts = history.filter(h => h.date === today());
  const todayTotalTries = todayAttempts.reduce((s, a) => s + (a.tries || 1), 0);
  const todayRetries = todayTotalTries - todayAttempts.length;
  const activeWord = active !== null ? W[active] : null;
  const isCustom = !!(activeWord && customMode[activeWord.word]);
  const renderedOptions = options ? (options.flipped ? [options.b, options.a] : [options.a, options.b]) : [];

  if (authLoading) {
    return (
      <div className="min-h-screen bg-gradient-to-b from-blue-100 via-purple-50 to-pink-100 flex items-center justify-center">
        <Loader2 className="w-8 h-8 animate-spin text-purple-500" />
      </div>
    );
  }

  if (!isAuth) {
    return (
      <div className="min-h-screen bg-gradient-to-b from-blue-100 via-purple-50 to-pink-100 flex items-center justify-center p-4">
        <form onSubmit={handleLogin} className="bg-white rounded-3xl p-8 shadow-xl w-full max-w-sm space-y-6">
          <div className="flex justify-center">
            <div className="w-16 h-16 bg-purple-100 rounded-full flex items-center justify-center">
              <Lock className="w-8 h-8 text-purple-600" />
            </div>
          </div>
          <div className="text-center">
            <h2 className="text-2xl font-black text-purple-700">S-Blend Game</h2>
            <p className="text-sm text-gray-500 mt-1">Enter the passcode to play</p>
          </div>
          {authError && <p className="text-sm text-center text-red-500 bg-red-50 p-2 rounded-lg">{authError}</p>}
          <input type="password" value={passcode} onChange={e => setPasscode(e.target.value)}
            className="w-full px-4 py-3 rounded-xl border-2 border-purple-200 text-center text-lg tracking-widest text-black placeholder:text-gray-400 focus:border-purple-500 focus:outline-none"
            placeholder="••••••" autoFocus />
          <button type="submit" disabled={authLoading || !passcode}
            className="w-full py-3 bg-gradient-to-r from-purple-500 to-indigo-500 text-white rounded-xl font-bold shadow disabled:opacity-50 flex items-center justify-center">
            {authLoading ? <Loader2 className="w-5 h-5 animate-spin" /> : "Unlock 🔓"}
          </button>
        </form>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-b from-blue-100 via-purple-50 to-pink-100 p-2 sm:p-4 pb-24">
      {showConfetti && <Confetti />}

      <div className="max-w-lg mx-auto landscape:max-w-2xl">
        <div className="text-center mb-3">
          <h1 className="text-2xl sm:text-3xl font-black text-purple-700 tracking-tight">S-Blend Speech Game</h1>
          <p className="text-xs sm:text-sm text-gray-500 mt-1">Tap a card, pick a phrase, say it out loud!</p>
          <div className="flex items-center justify-center gap-2 mt-2">
            <div className="h-3 flex-1 max-w-48 bg-gray-200 rounded-full overflow-hidden">
              <div className="h-full bg-gradient-to-r from-green-400 to-emerald-500 rounded-full transition-all duration-500"
                style={{ width: `${(Object.values(state.progress).reduce((s, p) => s + p.count, 0) / 24) * 100}%` }} />
            </div>
            <span className="text-xs font-bold text-gray-500">
              {Object.values(state.progress).reduce((s, p) => s + p.count, 0)}/24
            </span>
          </div>
        </div>

        {allDone && (
          <div className="bg-gradient-to-r from-yellow-300 via-pink-300 to-purple-300 rounded-2xl p-4 sm:p-6 mb-4 text-center shadow-lg animate-bounce">
            <div className="text-4xl sm:text-5xl mb-2">🎉🌟🏆</div>
            <h2 className="text-xl sm:text-2xl font-black text-white drop-shadow">Amazing Job!</h2>
            <p className="text-white font-semibold mt-1 text-sm sm:text-base">You finished all the words!</p>
            <div className="flex gap-3 justify-center mt-4 flex-wrap">
              <a href="/speech-game/stickers"
                className="bg-white text-purple-700 font-bold px-5 py-2.5 rounded-xl shadow hover:scale-105 transition-transform text-sm">
                Get Your Sticker! ⭐
              </a>
              <button onClick={resetGame}
                className="bg-white/50 text-purple-700 font-bold px-5 py-2.5 rounded-xl hover:bg-white/70 transition text-sm">
                Play Again 🔄
              </button>
            </div>
          </div>
        )}

        <div className="grid grid-cols-3 gap-2 sm:gap-3 landscape:grid-cols-4 landscape:gap-2">
          {W.map((wd, i) => {
            const prog = state.progress[wd.word];
            const done = prog.count >= 2;
            const half = prog.count === 1;
            const isJust = justCompleted === wd.word;
            return (
              <button key={wd.word} onClick={() => openCard(i)}
                disabled={done}
                className={`relative rounded-2xl p-2 sm:p-3 flex flex-col items-center justify-center aspect-square shadow-md transition-all duration-300
                  ${done ? "bg-green-100 border-2 border-green-400 scale-95 opacity-80" :
                    half ? "bg-yellow-50 border-2 border-yellow-400 hover:scale-105 hover:shadow-lg" :
                    "bg-white border-2 border-purple-200 hover:scale-105 hover:shadow-lg hover:border-purple-400"}
                  ${isJust ? "animate-pulse ring-4 ring-green-400" : ""}
                `}>
                <span className="text-3xl sm:text-4xl mb-1">{wd.emoji}</span>
                <span className={`text-sm sm:text-base font-black tracking-wide ${done ? "text-green-600" : "text-gray-800"}`}>
                  {wd.word}
                </span>
                {customMode[wd.word] && !done && (
                  <span className="mt-1 text-[10px] sm:text-xs font-bold text-indigo-500">Custom</span>
                )}
                <div className="absolute top-1.5 right-1.5">
                  {done ? (
                    <span className="text-green-500 text-lg sm:text-xl">✅</span>
                  ) : (
                    <div className="flex gap-0.5">
                      {[0, 1].map(j => (
                        <div key={j} className={`w-2 h-2 sm:w-2.5 sm:h-2.5 rounded-full border ${j < prog.count ? "bg-yellow-400 border-yellow-500" : "bg-gray-200 border-gray-300"}`} />
                      ))}
                    </div>
                  )}
                </div>
              </button>
            );
          })}
        </div>

        <div className="flex justify-between items-center mt-4 gap-2 flex-wrap">
          <button onClick={() => setShowHistory(!showHistory)}
            className="text-xs sm:text-sm text-purple-600 font-semibold underline">
            {showHistory ? "Hide" : "Show"} Log ({todayAttempts.length})
          </button>
          <div className="flex gap-3">
            <a href="/speech-game/stats" className="text-xs sm:text-sm text-purple-600 font-semibold underline">
              Stats 📊
            </a>
            <a href="/speech-game/stickers" className="text-xs sm:text-sm text-purple-600 font-semibold underline">
              Stickers ⭐
            </a>
          </div>
        </div>

        {showHistory && todayAttempts.length > 0 && (
          <div className="mt-3 bg-white rounded-xl p-2 sm:p-3 shadow-sm border border-purple-100">
            <div className="flex justify-between items-center mb-2 flex-wrap gap-1">
              <h3 className="font-bold text-gray-700 text-xs sm:text-sm">Today's Attempts</h3>
              <div className="flex gap-2 sm:gap-3 text-[10px] sm:text-xs text-gray-500">
                <span>{todayAttempts.length} correct</span>
                <span>{todayRetries} retries</span>
                <span>{todayTotalTries} tries</span>
              </div>
            </div>
            <div className="space-y-1 max-h-48 overflow-y-auto">
              {todayAttempts.map((a, i) => (
                <div key={i} className="flex items-center gap-1.5 sm:gap-2 text-[10px] sm:text-xs">
                  <span className="text-gray-400 w-10 sm:w-12 shrink-0">{a.time}</span>
                  <span className="font-bold text-purple-600 w-12 sm:w-14 shrink-0">{a.word}</span>
                  <span className="text-gray-600 flex-1 truncate">"{a.phrase}"</span>
                  <span className={`shrink-0 font-bold ${(a.tries || 1) > 1 ? "text-orange-500" : "text-green-500"}`}>
                    {a.tries > 1 ? `${a.tries}×` : "1×"}
                  </span>
                  <span className="text-[8px] sm:text-[10px] px-1 rounded bg-purple-100 text-purple-600 shrink-0">
                    {a.position === "first" ? "1st" : "2nd"}
                  </span>
                  <span className="text-green-500 shrink-0">R{a.round}</span>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {active !== null && options && activeWord && (
        <div className="fixed inset-0 bg-black/40 z-40 flex items-center justify-center p-3 sm:p-4"
          onClick={(e) => { if (e.target === e.currentTarget) closeCard(); }}>
          <div className="bg-white rounded-3xl p-5 sm:p-6 max-w-sm w-full shadow-2xl">
            <div className="text-center mb-4">
              <span className="text-5xl">{activeWord.emoji}</span>
              <h2 className="text-2xl font-black text-gray-800 mt-1">{activeWord.word}</h2>
              <p className="text-sm text-gray-400 mt-1">
                Round {(state.progress[activeWord.word].count || 0) + 1} of 2
              </p>
            </div>

            <div className="mb-4 flex items-center justify-center gap-2">
              <button
                onClick={() => {
                  setCustomMode(prev => ({ ...prev, [activeWord.word]: !prev[activeWord.word] }));
                  setChosen(null);
                  setCurrentTries(0);
                  setCustomDraft({ value: "", side: "first" });
                }}
                className={`px-4 py-2 rounded-full text-sm font-bold transition ${
                  isCustom ? "bg-indigo-500 text-white" : "bg-gray-100 text-gray-600 hover:bg-gray-200"
                }`}
              >
                {isCustom ? "Custom mode on" : "Switch to custom"}
              </button>
              {isCustom && (
                <button
                  onClick={() => {
                    setCustomMode(prev => ({ ...prev, [activeWord.word]: false }));
                    setChosen(null);
                    setCurrentTries(0);
                    setCustomDraft({ value: "", side: "first" });
                  }}
                  className="px-4 py-2 rounded-full text-sm font-bold bg-purple-100 text-purple-700 hover:bg-purple-200"
                >
                  Classic mode
                </button>
              )}
            </div>

            {!chosen ? (
              isCustom ? (
                <div className="space-y-3">
                  <p className="text-center text-sm font-semibold text-purple-600 mb-2">Type your own phrase for this round:</p>
                  {["first", "second"].map((side) => {
                    const isFirst = side === "first";
                    return (
                      <button
                        key={side}
                        onClick={() => setCustomDraft(prev => ({ ...prev, side: isFirst ? "first" : "second" }))}
                        className={`w-full py-3 px-4 rounded-2xl text-lg font-black text-center transition-all border-2 ${
                          customDraft.side === side
                            ? "border-indigo-500 bg-indigo-50 text-indigo-700"
                            : "border-purple-200 bg-white text-gray-700 hover:border-purple-400"
                        }`}
                      >
                        {isFirst ? "_____ + " : `${activeWord.word} + `}
                        <span className="opacity-80">{isFirst ? activeWord.word : "_____"}</span>
                      </button>
                    );
                  })}
                  <input
                    type="text"
                    value={customDraft.value}
                    onChange={(e) => setCustomDraft(prev => ({ ...prev, value: e.target.value }))}
                    placeholder="Type your custom word"
                    className="w-full px-4 py-3 rounded-2xl border-2 border-purple-200 text-center text-lg font-bold text-black placeholder:text-gray-400 focus:border-purple-500 focus:outline-none"
                    autoFocus
                  />
                  <button
                    onClick={submitCustomPhrase}
                    disabled={!customDraft.value.trim()}
                    className="w-full py-3 rounded-2xl text-lg font-black bg-gradient-to-r from-purple-500 to-indigo-500 text-white disabled:opacity-50"
                  >
                    Use this phrase
                  </button>
                </div>
              ) : (
                <div className="space-y-3">
                  <p className="text-center text-sm font-semibold text-purple-600 mb-2">Pick a phrase to practice:</p>
                  {renderedOptions.map((pair, i) => {
                    const isFirst = options.flipped ? (i === 1) : (i === 0);
                    return (
                      <button key={i} onClick={() => choosePhrase(pair, isFirst ? "first" : "second")}
                        className="w-full py-3 sm:py-4 px-4 sm:px-5 rounded-2xl text-lg sm:text-xl font-black text-center transition-all
                          bg-gradient-to-r from-purple-500 to-indigo-500 text-white hover:from-purple-600 hover:to-indigo-600
                          hover:scale-[1.02] active:scale-95 shadow-md">
                        {pair[0]} <span className="opacity-70">+</span> {pair[1]}
                      </button>
                    );
                  })}
                </div>
              )
            ) : (
              <div className="text-center">
                <div className="bg-gradient-to-r from-yellow-100 to-orange-100 rounded-2xl p-4 sm:p-5 mb-4">
                  <p className="text-sm text-orange-600 font-semibold mb-1">Say it out loud!</p>
                  <p className="text-2xl sm:text-3xl font-black text-gray-800">"{chosen}"</p>
                  {currentTries > 0 && (
                    <p className="text-xs text-orange-400 mt-2">Attempt #{currentTries + 1}</p>
                  )}
                </div>
                <div className="flex gap-3">
                  <button onClick={() => { setCurrentTries(t => t + 1); }}
                    className="flex-1 py-3 rounded-xl text-sm sm:text-base font-bold bg-gray-100 text-gray-600 hover:bg-gray-200 transition">
                    Try Again 🔄
                  </button>
                  <button onClick={markCorrect}
                    className="flex-1 py-3 rounded-xl text-sm sm:text-base font-bold bg-gradient-to-r from-green-400 to-emerald-500 text-white hover:from-green-500 hover:to-emerald-600 transition shadow-md hover:shadow-lg active:scale-95">
                    Correct ✅
                  </button>
                </div>
              </div>
            )}

            <button onClick={closeCard}
              className="mt-4 w-full text-center text-sm text-gray-400 hover:text-gray-600">
              Close
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
