                {MODE_OPTIONS.map(opt => (
                  <button
                    key={opt}
                    onClick={() => setMode(opt)}
                    className={`px-3 py-1.5 text-xs font-medium rounded-md transition-colors ${
                      mode === opt ? "bg-zinc-700 text-zinc-100" : "text-zinc-400 hover:text-zinc-200"
                    }`}
