  const [loading, setLoading] = useState(true);
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);
  const [bootTime, setBootTime] = useState<string | null>(null);
  const [diagnosing, setDiagnosing] = useState<Record<string, boolean>>({});
  const [diagnoseSuccess, setDiagnoseSuccess] = useState<Record<string, boolean>>({});
  const [claudeUsage, setClaudeUsage] = useState<ClaudeUsage | null>(null);
  const [geminiUsage, setGeminiUsage] = useState<GeminiUsage | null>(null);

  const fetchData = async () => {
    setLoading(true);
    try {
      const res = await fetch("/api/health-check", {
        headers: { "Accept": "application/json" }
      });
      const json = await res.json();

      if (Array.isArray(json)) {
        setData(json);
      } else {
        setData(json.services || []);
        if (json.bootTime) {
          try {
            const date = new Date(json.bootTime.replace(" ", "T") + "Z");
            setBootTime(date.toLocaleString());
          } catch (e) {
            setBootTime(json.bootTime);
          }
        }
        if (json.claudeUsage) setClaudeUsage(json.claudeUsage);
        if (json.geminiUsage) setGeminiUsage(json.geminiUsage);
      }
      setLastUpdated(new Date());
    } catch (e) {
      console.error(e);
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchData();
    const interval = setInterval(fetchData, 60000);
    return () => clearInterval(interval);
  }, []);

  const handleDiagnose = async (service: ServiceStatus) => {
    setDiagnosing(prev => ({ ...prev, [service.name]: true }));
    try {
      const res = await fetch("/api/diagnose", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(service)
      });
      if (res.ok) {
        setDiagnoseSuccess(prev => ({ ...prev, [service.name]: true }));
        setTimeout(() => setDiagnoseSuccess(prev => ({ ...prev, [service.name]: false })), 5000);
      } else {
        alert("Failed to trigger diagnosis. Make sure ZO_API_KEY is set in your secrets.");
      }
    } catch (e) {
      console.error(e);
      alert("Failed to trigger diagnosis.");
    }
    setDiagnosing(prev => ({ ...prev, [service.name]: false }));
  };

  const stats = {
    Operational: data.filter(d => d.status === "Operational").length,
    Degraded: data.filter(d => d.status === "Degraded").length,
    Outage: data.filter(d => d.status === "Outage").length,
  };

  const categories = Array.from(new Set(data.map(d => d.category)));

  const formatResetTime = (isoStr: string | null | undefined) => {
    if (!isoStr) return "N/A";
    const d = new Date(isoStr);
    return d.toLocaleString("en-CA", { timeZone: "America/Edmonton", month: "short", day: "numeric", hour: "numeric", minute: "2-digit", hour12: true });
  };

  const usageColor = (pct: number) => {
    if (pct >= 90) return "text-red-400";
    if (pct >= 70) return "text-yellow-400";
    return "text-emerald-400";
  };

  const usageBg = (pct: number) => {
    if (pct >= 90) return "rgba(248,113,113,0.15)";
    if (pct >= 70) return "rgba(250,204,21,0.15)";
    return "rgba(52,211,153,0.15)";
  };

  const usageBarColor = (pct: number) => {
    if (pct >= 90) return "bg-red-400";
    if (pct >= 70) return "bg-yellow-400";
    return "bg-emerald-400";
  };

  return (
    <>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;600;700&family=Inter:wght@400;500;600&family=JetBrains+Mono:wght@400;500&display=swap');
        * { box-sizing: border-box; }
        html { scroll-behavior: smooth; }
        .font-heading { font-family: 'Space Grotesk', sans-serif; }
        .font-body { font-family: 'Inter', sans-serif; }
        .font-mono { font-family: 'JetBrains Mono', monospace; }
        .bg-grid {
          background-size: 60px 60px;
          background-image:
            linear-gradient(to right, rgba(99,102,241,0.06) 1px, transparent 1px),
            linear-gradient(to bottom, rgba(6,182,212,0.06) 1px, transparent 1px);
        }
        .glass { background: rgba(15,17,23,0.7); backdrop-filter: blur(16px); border: 1px solid rgba(255,255,255,0.08); }
        .card-hover { transition: all 0.3s ease; }
        .card-hover:hover { border-color: rgba(6,182,212,0.4); box-shadow: 0 0 30px -10px rgba(6,182,212,0.15); transform: translateY(-2px); }
      `}</style>

      <div className="min-h-screen text-white font-body relative overflow-hidden" style={{ background: COLORS.bg }}>
        {/* Background effects */}
        <div className="absolute inset-0 bg-grid pointer-events-none" />
        <div className="absolute pointer-events-none" style={{ top: -200, left: "30%", width: 500, height: 500, background: COLORS.cyan, borderRadius: "50%", opacity: 0.04, filter: "blur(150px)" }} />
        <div className="absolute pointer-events-none" style={{ bottom: -200, right: "10%", width: 400, height: 400, background: COLORS.indigo, borderRadius: "50%", opacity: 0.05, filter: "blur(120px)" }} />

        <div className="relative z-10 max-w-4xl mx-auto px-6 py-12 md:py-20">
          <a href="/" className="inline-flex items-center gap-2 text-xs font-mono tracking-wider uppercase mb-12 transition-colors hover:text-white" style={{ color: COLORS.cyan }}>
            <ArrowLeft className="w-4 h-4" /> Back to Home
          </a>

          <div className="flex items-center gap-4 mb-2">
            <div className="w-12 h-12 rounded-xl flex items-center justify-center" style={{ background: `${COLORS.indigo}20`, border: `1px solid ${COLORS.indigo}40` }}>
              <Activity className="w-6 h-6" style={{ color: COLORS.indigoLight }} />
            </div>
            <h1 className="font-heading text-4xl md:text-5xl font-bold">
              Zo <span style={{
                background: `linear-gradient(135deg, ${COLORS.cyan}, ${COLORS.indigo})`,
                WebkitBackgroundClip: "text",
                WebkitTextFillColor: "transparent",
              }}>Status</span>
            </h1>
          </div>
          <p className="text-lg mb-12" style={{ color: COLORS.muted }}>Real-time service health and system overview</p>

          {/* Stats overview */}
          <div className="grid grid-cols-3 gap-4 mb-12">
            <div className="p-6 rounded-xl card-hover flex flex-col items-center justify-center text-center" style={{ background: COLORS.card, border: `1px solid ${COLORS.border}` }}>
              <span className="text-4xl font-heading font-bold text-emerald-400">{stats.Operational}</span>
              <span className="text-xs font-mono tracking-wider uppercase mt-2" style={{ color: COLORS.dimmed }}>Operational</span>
            </div>
            <div className="p-6 rounded-xl card-hover flex flex-col items-center justify-center text-center" style={{ background: COLORS.card, border: `1px solid ${COLORS.border}` }}>
              <span className="text-4xl font-heading font-bold text-yellow-400">{stats.Degraded}</span>
              <span className="text-xs font-mono tracking-wider uppercase mt-2" style={{ color: COLORS.dimmed }}>Degraded</span>
            </div>
            <div className="p-6 rounded-xl card-hover flex flex-col items-center justify-center text-center" style={{ background: COLORS.card, border: `1px solid ${COLORS.border}` }}>
              <span className="text-4xl font-heading font-bold text-red-400">{stats.Outage}</span>
              <span className="text-xs font-mono tracking-wider uppercase mt-2" style={{ color: COLORS.dimmed }}>Outage</span>
            </div>
          </div>

          {loading && data.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-20 rounded-xl" style={{ background: COLORS.card, border: `1px solid ${COLORS.border}` }}>
              <RefreshCw className="w-8 h-8 animate-spin mb-4" style={{ color: COLORS.cyan }} />
              <p className="font-mono text-sm tracking-wider uppercase" style={{ color: COLORS.muted }}>Checking Systems...</p>
            </div>
          ) : (
            <div className="space-y-10">
              {categories.map(cat => (
                <div key={cat}>
                  <div className="flex items-center gap-3 mb-5">
                    <h2 className="font-heading text-xl font-semibold">{cat}</h2>
                    <div className="h-px flex-1" style={{ background: `linear-gradient(to right, ${COLORS.border}, transparent)` }} />
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {data.filter(d => d.category === cat).map(service => (
                      <div key={service.name} className="p-5 rounded-xl card-hover flex flex-col md:flex-row md:items-center justify-between gap-4" style={{ background: COLORS.card, border: `1px solid ${COLORS.border}` }}>
                        <div>
                          <span className="font-medium">{service.name}</span>
                          {service.details && <p className="text-sm mt-1" style={{ color: COLORS.dimmed }}>{service.details}</p>}
                        </div>
                        <div className="flex items-center gap-3">
                          {service.status !== "Operational" && (
                            <button
                              onClick={() => handleDiagnose(service)}
                              disabled={diagnosing[service.name]}
                              className="px-3 py-1.5 rounded-lg text-xs font-medium transition-colors cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed"
                              style={{ 
                                background: diagnoseSuccess[service.name] ? "rgba(52,211,153,0.1)" : "rgba(255,255,255,0.05)",
                                color: diagnoseSuccess[service.name] ? COLORS.cyanLight : "white",
                                border: `1px solid ${diagnoseSuccess[service.name] ? "rgba(52,211,153,0.2)" : "rgba(255,255,255,0.1)"}`
                              }}
                            >
                              {diagnosing[service.name] ? (
                                <span className="flex items-center gap-2"><RefreshCw className="w-3.5 h-3.5 animate-spin" /> Asking Zo...</span>
                              ) : diagnoseSuccess[service.name] ? (
                                <span className="flex items-center gap-2"><CheckCircle2 className="w-3.5 h-3.5" /> Request Sent</span>
                              ) : (
                                "Ask Zo to Fix"
                              )}
                            </button>
                          )}
                          <div className="flex items-center gap-2.5 px-3 py-1.5 rounded-full" style={{ 
                            background: service.status === "Operational" ? "rgba(52,211,153,0.1)" :
                                        service.status === "Degraded" ? "rgba(250,204,21,0.1)" : "rgba(248,113,113,0.1)",
                            border: `1px solid ${service.status === "Operational" ? "rgba(52,211,153,0.2)" :
                                            service.status === "Degraded" ? "rgba(250,204,21,0.2)" : "rgba(248,113,113,0.2)"}`
                          }}>
                            {service.status === "Operational" && <CheckCircle2 className="w-4 h-4 text-emerald-400" />}
                            {service.status === "Degraded" && <AlertTriangle className="w-4 h-4 text-yellow-400" />}
                            {service.status === "Outage" && <XCircle className="w-4 h-4 text-red-400" />}
                            <span className={`text-xs font-mono tracking-wide uppercase ${
                              service.status === "Operational" ? "text-emerald-400" :
                              service.status === "Degraded" ? "text-yellow-400" : "text-red-400"
                            }`}>{service.status}</span>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* CLI Token Usage */}
          {(claudeUsage || geminiUsage) && (
            <div className="mt-14">
              <div className="flex items-center gap-3 mb-5">
                <h2 className="font-heading text-xl font-semibold">CLI Token Usage</h2>
                <div className="h-px flex-1" style={{ background: `linear-gradient(to right, ${COLORS.border}, transparent)` }} />
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {/* Claude Code Card */}
                {claudeUsage && (
                  <div className="p-5 rounded-xl card-hover" style={{ background: COLORS.card, border: `1px solid ${COLORS.border}` }}>
                    <div className="flex items-center justify-between mb-4">
                      <span className="font-heading font-semibold text-lg">Claude Code CLI</span>
                      <span className="px-2 py-0.5 rounded text-[10px] font-mono uppercase tracking-wider" style={{ background: `${COLORS.indigo}20`, color: COLORS.indigoLight }}>
                        {claudeUsage.plan || 'Pro'}
                      </span>
                    </div>

                    {claudeUsage.unavailable ? (
                      <div className="space-y-3">
                        <div className="flex items-center gap-2" style={{ color: COLORS.dimmed }}>
                          <AlertTriangle className="w-5 h-5" />
                          <span className="font-medium">Not detected</span>
                        </div>
                        <p className="text-sm" style={{ color: COLORS.dimmed }}>
                          Claude CLI not found on this system.
                        </p>
                      </div>
                    ) : claudeUsage.five_hour ? (
                      <>
                        <div className="mb-3">
                          <div className="flex items-center justify-between mb-1.5">
                            <span className="text-xs font-mono" style={{ color: COLORS.dimmed }}>5-Hour Window</span>
                            <span className={`text-xs font-mono font-medium ${usageColor(claudeUsage.five_hour.utilization)}`}>{claudeUsage.five_hour.utilization}%</span>
                          </div>
                          <div className="w-full h-2 rounded-full overflow-hidden" style={{ background: 'rgba(255,255,255,0.06)' }}>
                            <div className={`h-full rounded-full transition-all ${usageBarColor(claudeUsage.five_hour.utilization)}`} style={{ width: `${claudeUsage.five_hour.utilization}%` }} />
                          </div>
                          {claudeUsage.five_hour.resets_at && (
                            <div className="flex items-center gap-1 mt-1.5">
                              <Clock className="w-3 h-3" style={{ color: COLORS.dimmed }} />
                              <span className="text-[11px] font-mono" style={{ color: COLORS.dimmed }}>Resets {formatResetTime(claudeUsage.five_hour.resets_at)}</span>
                            </div>
                          )}
                        </div>
                        {claudeUsage.seven_day && (
                          <div className="mb-2">
                            <div className="flex items-center justify-between mb-1.5">
                              <span className="text-xs font-mono" style={{ color: COLORS.dimmed }}>7-Day Cycle</span>
                              <span className={`text-xs font-mono font-medium ${usageColor(claudeUsage.seven_day.utilization)}`}>{claudeUsage.seven_day.utilization}%</span>
                            </div>
                            <div className="w-full h-2 rounded-full overflow-hidden" style={{ background: 'rgba(255,255,255,0.06)' }}>
                              <div className={`h-full rounded-full transition-all ${usageBarColor(claudeUsage.seven_day.utilization)}`} style={{ width: `${claudeUsage.seven_day.utilization}%` }} />
                            </div>
                            {claudeUsage.seven_day.resets_at && (
                              <div className="flex items-center gap-1 mt-1.5">
                                <Clock className="w-3 h-3" style={{ color: COLORS.dimmed }} />
                                <span className="text-[11px] font-mono" style={{ color: COLORS.dimmed }}>Resets {formatResetTime(claudeUsage.seven_day.resets_at)}</span>
                              </div>
                            )}
                          </div>
                        )}
                        {claudeUsage.extra_usage && (
                          <div className="mt-3 pt-3" style={{ borderTop: `1px solid ${COLORS.border}` }}>
                            <span className="text-[11px] font-mono" style={{ color: COLORS.dimmed }}>
                              Extra usage: <span className={claudeUsage.extra_usage.is_enabled ? 'text-emerald-400' : 'text-zinc-500'}>{claudeUsage.extra_usage.is_enabled ? 'Enabled' : 'Disabled'}</span>
                            </span>
                          </div>
                        )}
                      </>
                    ) : (
                      <div className="space-y-4">
                        <div className="flex items-center gap-2 text-emerald-400">
                          <CheckCircle2 className="w-5 h-5" />
                          <span className="font-medium">CLI Detected</span>
                        </div>

                        <div className="grid grid-cols-3 gap-3">
                          <div className="text-center p-3 rounded-lg" style={{ background: 'rgba(255,255,255,0.03)' }}>
                            <span className="text-xl font-heading font-bold text-white">{claudeUsage.totalSessions || 0}</span>
                            <span className="text-[10px] font-mono block mt-1 uppercase tracking-wider" style={{ color: COLORS.dimmed }}>Sessions</span>
                          </div>
                          <div className="text-center p-3 rounded-lg" style={{ background: 'rgba(255,255,255,0.03)' }}>
                            <span className="text-xl font-heading font-bold text-white">{((claudeUsage.totalMessages || 0) / 1000).toFixed(1)}k</span>
                            <span className="text-[10px] font-mono block mt-1 uppercase tracking-wider" style={{ color: COLORS.dimmed }}>Messages</span>
                          </div>
                          <div className="text-center p-3 rounded-lg" style={{ background: 'rgba(255,255,255,0.03)' }}>
                            <span className="text-xl font-heading font-bold text-white">{claudeUsage.recentToolCalls || 0}</span>
                            <span className="text-[10px] font-mono block mt-1 uppercase tracking-wider" style={{ color: COLORS.dimmed }}>Tools (7d)</span>
                          </div>
                        </div>

                        {claudeUsage.models && (
                          <div className="space-y-2">
                            <span className="text-xs font-mono" style={{ color: COLORS.dimmed }}>Model Usage (direct tokens)</span>
                            {claudeUsage.models.opus.directTokens > 0 && (
                              <div className="flex items-center justify-between text-xs">
                                <span style={{ color: COLORS.muted }}>Opus 4.6</span>
                                <span className="font-mono" style={{ color: COLORS.indigoLight }}>{claudeUsage.models.opus.directTokens.toLocaleString()}</span>
                              </div>
                            )}
                            {claudeUsage.models.sonnet.directTokens > 0 && (
                              <div className="flex items-center justify-between text-xs">
                                <span style={{ color: COLORS.muted }}>Sonnet 4.5</span>
                                <span className="font-mono" style={{ color: COLORS.cyanLight }}>{claudeUsage.models.sonnet.directTokens.toLocaleString()}</span>
                              </div>
                            )}
                            {claudeUsage.models.haiku.directTokens > 0 && (
                              <div className="flex items-center justify-between text-xs">
                                <span style={{ color: COLORS.muted }}>Haiku 4.5</span>
                                <span className="font-mono" style={{ color: COLORS.dimmed }}>{claudeUsage.models.haiku.directTokens.toLocaleString()}</span>
                              </div>
                            )}
                          </div>
                        )}

                        {claudeUsage.note && (
                          <div className="mt-2 p-3 rounded-lg" style={{ background: 'rgba(99,102,241,0.08)', border: `1px solid ${COLORS.border}` }}>
                            <p className="text-[11px] font-mono" style={{ color: COLORS.dimmed }}>{claudeUsage.note}</p>
                          </div>
                        )}

                        {claudeUsage.statsDate && (
                          <span className="text-[10px] font-mono" style={{ color: COLORS.dimmed }}>
                            Stats as of {claudeUsage.statsDate}
                          </span>
                        )}
                      </div>
                    )}
                  </div>
                )}
                {/* Gemini CLI Card */}
                {geminiUsage && (
                  <div className="p-5 rounded-xl card-hover" style={{ background: COLORS.card, border: `1px solid ${COLORS.border}` }}>
                    <div className="flex items-center justify-between mb-4">
                      <span className="font-heading font-semibold text-lg">Gemini CLI</span>
                      <span className="px-2 py-0.5 rounded text-[10px] font-mono uppercase tracking-wider" style={{ 
                        background: geminiUsage.status === 'exhausted' ? 'rgba(248,113,113,0.2)' : `${COLORS.cyan}20`, 
                        color: geminiUsage.status === 'exhausted' ? '#f87171' : COLORS.cyanLight 
                      }}>
                        {geminiUsage.status === 'exhausted' ? 'QUOTA EXHAUSTED' : geminiUsage.status === 'no_data' ? 'NO DATA' : 'OAuth'}
                      </span>
                    </div>

                    {/* ALWAYS show progress bar */}
                    <div className="space-y-3">
                      <div className="flex items-center gap-2" style={{ 
                        color: geminiUsage.status === 'exhausted' ? '#f87171' : 
                               geminiUsage.percentage > 80 ? '#f87171' : 
                               geminiUsage.percentage > 50 ? '#facc15' : '#34d399'
                      }}>
                        {geminiUsage.status === 'exhausted' ? (
                          <><XCircle className="w-5 h-5" /><span className="font-medium">Quota exhausted</span></>
                        ) : geminiUsage.status === 'no_data' ? (
                          <><AlertTriangle className="w-5 h-5" /><span className="font-medium">No telemetry data</span></>
                        ) : geminiUsage.percentage > 80 ? (
                          <><AlertTriangle className="w-5 h-5" /><span className="font-medium">Quota running low</span></>
                        ) : (
                          <><CheckCircle2 className="w-5 h-5" /><span className="font-medium">Quota available</span></>
                        )}
                      </div>

                      {geminiUsage.used !== undefined && geminiUsage.limit !== undefined && (
                        <p className="text-sm" style={{ color: COLORS.dimmed }}>
                          {geminiUsage.used.toLocaleString()} / {geminiUsage.limit.toLocaleString()} requests
                        </p>
                      )}

                      {/* Progress bar - ALWAYS visible */}
                      <div className="mt-3">
                        <div className="flex items-center justify-between mb-1.5">
                          <span className="text-xs font-mono" style={{ color: COLORS.dimmed }}>
                            {geminiUsage.status === 'exhausted' ? 'Used' : 'Current Usage'}
                          </span>
                          <span className={`text-xs font-mono font-medium ${usageColor(geminiUsage.percentage || (geminiUsage.status === 'exhausted' ? 100 : 0))}`}>
                            {geminiUsage.status === 'exhausted' ? '100%' : `${geminiUsage.percentage || 0}%`}
                          </span>
                        </div>
                        <div className="w-full h-2 rounded-full overflow-hidden" style={{ background: 'rgba(255,255,255,0.06)' }}>
                          <div 
                            className={`h-full rounded-full transition-all ${usageBarColor(geminiUsage.percentage || (geminiUsage.status === 'exhausted' ? 100 : 0))}`} 
                            style={{ width: `${geminiUsage.status === 'exhausted' ? 100 : (geminiUsage.percentage || 0)}%` }} 
                          />
                        </div>
                      </div>

                      {geminiUsage.status === 'exhausted' && geminiUsage.resetTime && (
                        <div className="flex items-center gap-2 mt-3 p-3 rounded-lg" style={{ background: 'rgba(248,113,113,0.08)', border: `1px solid rgba(248,113,113,0.2)` }}>
                          <Clock className="w-4 h-4 text-red-400" />
                          <div>
                            <span className="text-xs font-mono block" style={{ color: COLORS.dimmed }}>Quota resets at</span>
                            <span className="text-sm font-medium text-red-400">
                              {formatResetTime(geminiUsage.resetTime)}
                            </span>
                          </div>
                        </div>
                      )}

                      {geminiUsage.status === 'no_data' && (
                        <div className="mt-3 p-3 rounded-lg" style={{ background: `rgba(6,182,212,0.08)`, border: `1px solid ${COLORS.border}` }}>
                          <p className="text-xs" style={{ color: COLORS.dimmed }}>
                            Enable Gemini telemetry for accurate tracking:
                          </p>
                          <code className="text-[10px] font-mono block mt-2 p-2 rounded" style={{ background: 'rgba(0,0,0,0.3)', color: COLORS.cyanLight }}>
                            GEMINI_TELEMETRY_ENABLED=true<br/>
                            GEMINI_TELEMETRY_TARGET=local<br/>
                            GEMINI_TELEMETRY_OUTFILE=/home/workspace/.zo/gemini-telemetry.jsonl
                          </code>
                        </div>
                      )}
                    </div>
                  </div>
                )}
              </div>
            </div>
          )}

          <div className="mt-16 pt-6 flex flex-col md:flex-row md:items-center justify-between gap-4" style={{ borderTop: `1px solid ${COLORS.border}` }}>
            <div className="flex flex-col gap-1">
              <span className="text-xs font-mono" style={{ color: COLORS.dimmed }}>
                Last updated: {lastUpdated ? lastUpdated.toLocaleTimeString() : '--:--:--'}
              </span>
              {bootTime && (
                <span className="text-xs font-mono" style={{ color: COLORS.dimmed }}>
                  System last restarted: {bootTime}
                </span>
              )}
            </div>
            <span className="flex items-center gap-2 text-xs font-mono" style={{ color: COLORS.dimmed }}>
