  const previewSrc = `/images/themes/${id}-preview.jpg`;

  useEffect(() => {
    const img = new Image();
    img.onload = () => setHasPreview(true);
    img.onerror = () => setHasPreview(false);
    img.src = previewSrc;
  }, [previewSrc]);

  useEffect(() => {
    fetch(`/api/zo-space-theme-gallery/${encodeURIComponent(id)}`, {
      headers: { Accept: "application/json" },
    })
      .then(async (r) => {
