import { useState, useEffect, useRef, useCallback } from "react";
import { useParams, Link } from "react-router-dom";
import {
  Layout,
  ArrowLeft,
  Plus,
  X,
  Save,
  Trash2,
  Loader2,
  AlertCircle,
  Tag,
  Activity as ActivityIcon,
  Search,
} from "lucide-react";

const defaultTheme = {
  background: "#0f0f0e",
  foreground: "#f5f1e8",
  card: "rgba(28, 26, 22, 0.82)",
  cardHover: "rgba(38, 35, 30, 0.92)",
  muted: "#7a746b",
  accent: "#d4a04a",
  border: "rgba(255,255,255,0.08)",
  columnBg: "rgba(20, 19, 17, 0.6)",
};

type Column = { id: string; title: string };
type Board = { slug: string; title: string; columns: Column[]; theme?: Partial<typeof defaultTheme> };
type Card = {
  id: string;
  title: string;
  body?: string;
  tags?: string[];
  column_id: string;
  order: number;
  status: string;
  updated_at: string;
  created_at?: string;
  mengram_id?: string;
};
type ActivityEntry = {
  timestamp: string;
  action: string;
  card_id: string;
  card_title: string;
  board_slug: string;
  origin: string;
};

function relTime(iso: string): string {
  const ms = Date.now() - new Date(iso).getTime();
  const s = Math.floor(ms / 1000);
  if (s < 60) return `${s}s ago`;
  const m = Math.floor(s / 60);
  if (m < 60) return `${m}m ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h ago`;
  const d = Math.floor(h / 24);
  return `${d}d ago`;
}

export default function BoardView() {
  const { slug } = useParams<{ slug: string }>();
  const [board, setBoard] = useState<Board | null>(null);
  const [cards, setCards] = useState<Card[]>([]);
  const [activity, setActivity] = useState<ActivityEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [activeCard, setActiveCard] = useState<Card | null>(null);
  const [showActivity, setShowActivity] = useState(false);
  const [search, setSearch] = useState("");
  const [tagFilter, setTagFilter] = useState<string | null>(null);
  const [draggedId, setDraggedId] = useState<string | null>(null);
  const [hoveredColumn, setHoveredColumn] = useState<string | null>(null);
  const [theme, setTheme] = useState(defaultTheme);

  const fetchBoard = useCallback(async () => {
    try {
      const r = await fetch(`/api/zoboard/boards/${slug}`, {
        headers: { Accept: "application/json" },
      });
      if (!r.ok) throw new Error(`HTTP ${r.status}`);
      const data = await r.json();
      setBoard(data.board);
      setCards(data.cards ?? []);
      if (data.board?.theme) setTheme({ ...defaultTheme, ...data.board.theme });
      setError(null);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }, [slug]);

  const fetchActivity = useCallback(async () => {
    try {
      const r = await fetch(`/api/zoboard/activity`, {
        headers: { Accept: "application/json" },
      });
      if (!r.ok) return;
      const data = await r.json();
      setActivity(
        (data.activity ?? [])
          .filter((e: ActivityEntry) => e.board_slug === slug)
          .reverse()
          .slice(0, 50),
      );
    } catch {}
  }, [slug]);

  useEffect(() => {
    fetchBoard();
    fetchActivity();
  }, [fetchBoard, fetchActivity]);

  useEffect(() => {
    const interval = setInterval(() => {
      if (!activeCard) {
        fetchBoard();
        fetchActivity();
      }
    }, 30000);
    return () => clearInterval(interval);
  }, [fetchBoard, fetchActivity, activeCard]);

  const allTags = Array.from(
    new Set(cards.flatMap((c) => c.tags ?? [])),
  ).sort();

  const visibleCards = cards.filter((c) => {
    if (search) {
      const q = search.toLowerCase();
      const hay = `${c.title} ${(c.tags ?? []).join(" ")} ${c.body ?? ""}`.toLowerCase();
      if (!hay.includes(q)) return false;
    }
    if (tagFilter && !(c.tags ?? []).includes(tagFilter)) return false;
    return true;
  });

  const columnsWithCards = (board?.columns ?? []).map((col) => ({
    ...col,
    cards: visibleCards
      .filter((c) => c.column_id === col.id)
      .sort((a, b) => a.order - b.order),
  }));

  async function createCard(columnId: string) {
    const title = prompt("Card title?");
    if (!title) return;
    const r = await fetch(`/api/zoboard/boards/${slug}/cards`, {
      method: "POST",
      headers: { "Content-Type": "application/json", Accept: "application/json" },
      body: JSON.stringify({ title, column_id: columnId, order: Date.now() }),
    });
    if (r.ok) {
      await fetchBoard();
      await fetchActivity();
    }
  }

  async function moveCard(cardId: string, columnId: string) {
    const card = cards.find((c) => c.id === cardId);
    if (!card || card.column_id === columnId) return;
    const optimistic = cards.map((c) =>
      c.id === cardId ? { ...c, column_id: columnId } : c,
    );
    setCards(optimistic);
    const r = await fetch(`/api/zoboard/cards/${cardId}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json", Accept: "application/json" },
      body: JSON.stringify({ column_id: columnId, order: Date.now() }),
    });
    if (r.ok) {
      await fetchBoard();
      await fetchActivity();
    } else {
      setCards(cards);
    }
  }

  async function saveCard(updated: Partial<Card>) {
    if (!activeCard) return;
    const r = await fetch(`/api/zoboard/cards/${activeCard.id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json", Accept: "application/json" },
      body: JSON.stringify(updated),
    });
    if (r.ok) {
      const data = await r.json();
      setActiveCard(data.card);
      await fetchBoard();
      await fetchActivity();
    }
  }

  async function deleteCard() {
    if (!activeCard) return;
    if (!confirm(`Delete "${activeCard.title}"?`)) return;
    const r = await fetch(`/api/zoboard/cards/${activeCard.id}`, {
      method: "DELETE",
      headers: { Accept: "application/json" },
    });
    if (r.ok) {
      setActiveCard(null);
      await fetchBoard();
      await fetchActivity();
    }
  }

  return (
    <main
      style={
        {
          "--page-bg": theme.background,
          "--page-fg": theme.foreground,
          "--page-card": theme.card,
          "--page-card-hover": theme.cardHover,
          "--page-muted": theme.muted,
          "--page-accent": theme.accent,
          "--page-border": theme.border,
          "--page-col": theme.columnBg,
        } as React.CSSProperties
      }
      className="min-h-screen bg-[var(--page-bg)] text-[var(--page-fg)]"
    >
      <header className="sticky top-0 z-30 backdrop-blur-md bg-[var(--page-bg)]/80 border-b border-[var(--page-border)]">
        <div className="max-w-[1600px] mx-auto px-4 py-3 flex items-center gap-3">
          <Link
            to="/zoboard"
            className="p-1.5 rounded hover:bg-white/5 text-[var(--page-muted)] hover:text-[var(--page-fg)]"
          >
            <ArrowLeft className="w-5 h-5" />
          </Link>
          <Layout className="w-6 h-6 text-[var(--page-accent)]" />
          <h1 className="text-xl font-bold">
            {board?.title ?? slug}
          </h1>
          <span className="text-xs text-[var(--page-muted)] ml-2">
            {cards.length} card{cards.length === 1 ? "" : "s"}
          </span>
          <div className="flex-1" />
          <div className="relative w-64 hidden md:block">
            <Search className="w-4 h-4 absolute left-2.5 top-2 text-[var(--page-muted)]" />
            <input
              type="text"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Search title, tag, body..."
              className="w-full pl-8 pr-3 py-1.5 text-sm rounded-md bg-white/5 border border-[var(--page-border)] focus:outline-none focus:border-[var(--page-accent)]/40"
            />
          </div>
          <button
            onClick={() => setShowActivity((v) => !v)}
            className={`p-1.5 rounded hover:bg-white/5 ${showActivity ? "text-[var(--page-accent)]" : "text-[var(--page-muted)]"}`}
            title="Activity feed"
          >
            <ActivityIcon className="w-5 h-5" />
          </button>
        </div>
        <div className="md:hidden max-w-[1600px] mx-auto px-4 pb-2">
          <div className="relative">
            <Search className="w-4 h-4 absolute left-2.5 top-2 text-[var(--page-muted)]" />
            <input
              type="text"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Search title, tag, body..."
              className="w-full pl-8 pr-3 py-1.5 text-sm rounded-md bg-white/5 border border-[var(--page-border)] focus:outline-none focus:border-[var(--page-accent)]/40"
            />
          </div>
        </div>
        {allTags.length > 0 && (
          <div className="max-w-[1600px] mx-auto px-4 pb-2 flex items-center gap-1.5 overflow-x-auto">
            <Tag className="w-3.5 h-3.5 text-[var(--page-muted)] shrink-0" />
            <button
              onClick={() => setTagFilter(null)}
              className={`px-2 py-0.5 rounded-full text-xs whitespace-nowrap ${
                tagFilter === null
                  ? "bg-[var(--page-accent)]/20 text-[var(--page-accent)] border border-[var(--page-accent)]/40"
                  : "bg-white/5 text-[var(--page-muted)] border border-transparent hover:border-[var(--page-border)]"
              }`}
            >
              all
            </button>
            {allTags.map((t) => (
              <button
                key={t}
                onClick={() => setTagFilter(tagFilter === t ? null : t)}
                className={`px-2 py-0.5 rounded-full text-xs whitespace-nowrap ${
                  tagFilter === t
                    ? "bg-[var(--page-accent)]/20 text-[var(--page-accent)] border border-[var(--page-accent)]/40"
                    : "bg-white/5 text-[var(--page-muted)] border border-transparent hover:border-[var(--page-border)]"
                }`}
              >
                {t}
              </button>
            ))}
          </div>
        )}
      </header>

      <div className="max-w-[1600px] mx-auto px-4 py-6 flex gap-4">
        <div className="flex-1 min-w-0">
          {loading && (
            <div className="flex items-center gap-2 text-[var(--page-muted)] py-12 justify-center">
              <Loader2 className="w-5 h-5 animate-spin" />
              Loading board...
            </div>
          )}

          {error && (
            <div className="flex items-center gap-2 text-red-400 bg-red-950/30 border border-red-800/30 rounded-lg p-4 mb-4">
              <AlertCircle className="w-5 h-5" />
              <span>Failed to load: {error}</span>
            </div>
          )}

          {!loading && !error && board && (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {columnsWithCards.map((col) => (
                <div
                  key={col.id}
                  onDragOver={(e) => {
                    e.preventDefault();
                    setHoveredColumn(col.id);
                  }}
                  onDragLeave={() => setHoveredColumn(null)}
                  onDrop={(e) => {
                    e.preventDefault();
                    setHoveredColumn(null);
                    if (draggedId) {
                      moveCard(draggedId, col.id);
                      setDraggedId(null);
                    }
                  }}
                  className={`flex flex-col rounded-xl border bg-[var(--page-col)] transition-colors ${
                    hoveredColumn === col.id
                      ? "border-[var(--page-accent)]/40 bg-[var(--page-accent)]/5"
                      : "border-[var(--page-border)]"
                  }`}
                >
                  <div className="flex items-center justify-between px-3 py-2 border-b border-[var(--page-border)]">
                    <div className="flex items-center gap-2">
                      <h2 className="font-semibold text-sm uppercase tracking-wide text-[var(--page-muted)]">
                        {col.title}
                      </h2>
                      <span className="text-xs text-[var(--page-muted)] bg-white/5 px-1.5 rounded">
                        {col.cards.length}
                      </span>
                    </div>
                    <button
                      onClick={() => createCard(col.id)}
                      className="p-1 rounded hover:bg-white/5 text-[var(--page-muted)] hover:text-[var(--page-accent)]"
                      title="New card"
                    >
                      <Plus className="w-4 h-4" />
                    </button>
                  </div>
                  <div className="flex flex-col gap-2 p-2 min-h-[200px]">
                    {col.cards.map((card) => (
                      <article
                        key={card.id}
                        draggable
                        onDragStart={(e) => {
                          e.dataTransfer.setData("text/plain", card.id);
                          setDraggedId(card.id);
                        }}
                        onDragEnd={() => setDraggedId(null)}
                        onClick={() => setActiveCard(card)}
                        className={`rounded-lg border border-[var(--page-border)] bg-[var(--page-card)] hover:bg-[var(--page-card-hover)] hover:border-[var(--page-accent)]/30 p-3 cursor-pointer transition-colors ${
                          draggedId === card.id ? "opacity-40" : ""
                        }`}
                      >
                        <h3 className="font-medium text-sm leading-snug mb-2">
                          {card.title}
                        </h3>
                        {card.tags && card.tags.length > 0 && (
                          <div className="flex flex-wrap gap-1 mb-2">
                            {card.tags.map((t) => (
                              <span
                                key={t}
                                className="text-[10px] px-1.5 py-0.5 rounded-full bg-[var(--page-accent)]/10 text-[var(--page-accent)]"
                              >
                                {t}
                              </span>
                            ))}
                          </div>
                        )}
                        <div className="text-[11px] text-[var(--page-muted)]">
                          {relTime(card.updated_at)}
                        </div>
                      </article>
                    ))}
                    {col.cards.length === 0 && (
                      <div className="text-center text-[var(--page-muted)] text-xs py-8 opacity-60">
                        Drop cards here
                      </div>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {showActivity && (
          <aside className="hidden lg:block w-80 shrink-0">
            <div className="sticky top-20 rounded-xl border border-[var(--page-border)] bg-[var(--page-col)] max-h-[calc(100vh-6rem)] overflow-hidden flex flex-col">
              <div className="px-3 py-2 border-b border-[var(--page-border)] flex items-center gap-2">
                <ActivityIcon className="w-4 h-4 text-[var(--page-accent)]" />
                <h3 className="text-sm font-semibold uppercase tracking-wide text-[var(--page-muted)]">
                  Activity
                </h3>
              </div>
              <div className="overflow-y-auto p-2 flex-1">
                {activity.length === 0 ? (
                  <p className="text-xs text-[var(--page-muted)] py-4 text-center">
                    No activity yet
                  </p>
                ) : (
                  activity.map((e, i) => (
                    <div
                      key={i}
                      className="text-xs py-2 px-2 border-b border-[var(--page-border)] last:border-0"
                    >
                      <div className="flex items-center gap-1.5">
                        <span
                          className={`px-1.5 py-0.5 rounded text-[10px] uppercase font-mono ${
                            e.action === "create"
                              ? "bg-emerald-500/20 text-emerald-300"
                              : e.action === "delete"
                                ? "bg-red-500/20 text-red-300"
                                : e.action === "move"
                                  ? "bg-blue-500/20 text-blue-300"
                                  : "bg-white/10 text-[var(--page-muted)]"
                          }`}
                        >
                          {e.action}
                        </span>
                        <span className="text-[10px] text-[var(--page-muted)] ml-auto">
                          {relTime(e.timestamp)}
                        </span>
                      </div>
                      <div className="mt-1 truncate">{e.card_title}</div>
                      <div className="text-[10px] text-[var(--page-muted)]">
                        via {e.origin}
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>
          </aside>
        )}
      </div>

      {activeCard && (
        <CardDrawer
          card={activeCard}
          board={board}
          onClose={() => setActiveCard(null)}
          onSave={saveCard}
          onDelete={deleteCard}
        />
      )}
    </main>
  );
}

function CardDrawer({
  card,
  board,
  onClose,
  onSave,
  onDelete,
}: {
  card: Card;
  board: Board | null;
  onClose: () => void;
  onSave: (updated: Partial<Card>) => Promise<void>;
  onDelete: () => Promise<void>;
}) {
  const [title, setTitle] = useState(card.title);
  const [body, setBody] = useState(card.body ?? "");
  const [tags, setTags] = useState((card.tags ?? []).join(", "));
  const [columnId, setColumnId] = useState(card.column_id);
  const [saving, setSaving] = useState(false);
  const [loadedBody, setLoadedBody] = useState(card.body !== undefined);

  useEffect(() => {
    if (loadedBody) return;
    fetch(`/api/zoboard/boards/${card.id}`).catch(() => {});
    setLoadedBody(true);
  }, [card.id, loadedBody]);

  useEffect(() => {
    setTitle(card.title);
    setBody(card.body ?? "");
    setTags((card.tags ?? []).join(", "));
    setColumnId(card.column_id);
  }, [card]);

  async function handleSave() {
    setSaving(true);
    await onSave({
      title,
      body,
      tags: tags.split(",").map((t) => t.trim()).filter(Boolean),
      column_id: columnId,
    });
    setSaving(false);
  }

  return (
    <div
      className="fixed inset-0 z-50 flex"
      onKeyDown={(e) => {
        if (e.key === "Escape") onClose();
      }}
    >
      <div
        className="flex-1 bg-black/60 backdrop-blur-sm"
        onClick={onClose}
      />
      <div className="w-full max-w-xl bg-[var(--page-bg)] border-l border-[var(--page-border)] flex flex-col h-screen">
        <div className="flex items-center justify-between p-4 border-b border-[var(--page-border)]">
          <h2 className="font-semibold text-[var(--page-muted)] uppercase text-xs tracking-wider">
            Card detail
          </h2>
          <button
            onClick={onClose}
            className="p-1 rounded hover:bg-white/5 text-[var(--page-muted)]"
          >
            <X className="w-5 h-5" />
          </button>
        </div>
        <div className="flex-1 overflow-y-auto p-4 space-y-4">
          <div>
            <label className="block text-xs font-medium text-[var(--page-muted)] uppercase mb-1.5">
              Title
            </label>
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              className="w-full px-3 py-2 rounded-md bg-white/5 border border-[var(--page-border)] focus:outline-none focus:border-[var(--page-accent)]/50 text-base"
            />
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-medium text-[var(--page-muted)] uppercase mb-1.5">
                Column
              </label>
              <select
                value={columnId}
                onChange={(e) => setColumnId(e.target.value)}
                className="w-full px-3 py-2 rounded-md bg-white/5 border border-[var(--page-border)] focus:outline-none focus:border-[var(--page-accent)]/50 text-sm"
              >
                {(board?.columns ?? []).map((c) => (
                  <option key={c.id} value={c.id}>
                    {c.title}
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-xs font-medium text-[var(--page-muted)] uppercase mb-1.5">
                Tags (comma-sep)
              </label>
              <input
                type="text"
                value={tags}
                onChange={(e) => setTags(e.target.value)}
                placeholder="todo, idea"
                className="w-full px-3 py-2 rounded-md bg-white/5 border border-[var(--page-border)] focus:outline-none focus:border-[var(--page-accent)]/50 text-sm"
              />
            </div>
          </div>
          <div>
            <label className="block text-xs font-medium text-[var(--page-muted)] uppercase mb-1.5">
              Body (markdown)
            </label>
            <textarea
              value={body}
              onChange={(e) => setBody(e.target.value)}
              rows={16}
              className="w-full px-3 py-2 rounded-md bg-white/5 border border-[var(--page-border)] focus:outline-none focus:border-[var(--page-accent)]/50 text-sm font-mono leading-relaxed resize-none"
              placeholder="Markdown content..."
            />
          </div>
          <div className="text-xs text-[var(--page-muted)] space-y-1 pt-2 border-t border-[var(--page-border)]">
            <div>ID: <span className="font-mono">{card.id}</span></div>
            {card.mengram_id && (
              <div>Mengram: <span className="font-mono">{card.mengram_id}</span></div>
            )}
            <div>Updated: {relTime(card.updated_at)}</div>
            {card.created_at && <div>Created: {relTime(card.created_at)}</div>}
          </div>
        </div>
        <div className="p-4 border-t border-[var(--page-border)] flex items-center gap-2">
          <button
            onClick={handleSave}
            disabled={saving}
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-md bg-[var(--page-accent)]/20 text-[var(--page-accent)] border border-[var(--page-accent)]/40 hover:bg-[var(--page-accent)]/30 disabled:opacity-50"
          >
            {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
            Save
          </button>
          <button
            onClick={onDelete}
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-md bg-red-500/10 text-red-300 border border-red-500/30 hover:bg-red-500/20"
          >
            <Trash2 className="w-4 h-4" />
            Delete
          </button>
          <div className="flex-1" />
          <button
            onClick={onClose}
            className="px-3 py-1.5 rounded-md text-[var(--page-muted)] hover:bg-white/5"
          >
            Cancel
          </button>
        </div>
      </div>
    </div>
  );
}
